INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(6,0,2,'zhCN','别杀我！别杀我！'),
(29,1,0,'zhCN','让远古海滩的战斗开始吧！'),
(29,2,0,'zhCN','第 1 回合 - 结束！'),
(38,1,0,'zhCN','都已经半小时了，快出来！！'),
(40,0,1,'zhCN','咿咿咿！我跑！'),
(40,0,2,'zhCN','别杀我！别杀我！'),
(54,0,0,'zhCN','你好，$N！'),
(68,2,0,'zhCN','%s 向 $n 扔了一只烂苹果。'),
(68,3,0,'zhCN','%s 把烂香蕉扔到 $n 身上。'),
(68,4,0,'zhCN','%s 朝 $n 吐了口唾沫。'),
(68,5,0,'zhCN','怪物！'),
(68,5,1,'zhCN','杀人凶手！'),
(68,5,2,'zhCN','拿绳子来！'),
(68,5,3,'zhCN','你竟敢踏足我们的城市！'),
(68,5,4,'zhCN','你让我恶心。'),
(68,5,5,'zhCN','看来我们要处决一个人了。'),
(68,5,6,'zhCN','叛徒走狗。'),
(68,5,7,'zhCN','我的家人都被天灾军团杀光了！怪物！'),
(80,0,2,'zhCN','别杀我！别杀我！'),
(103,0,1,'zhCN','这片土地现在属于迪菲亚兄弟会了！'),
(233,0,0,'zhCN','现在我该怎么把那些机械废品从我田里弄走？'),
(233,0,1,'zhCN','一群暴徒和小偷休想把我从我的土地上赶走！'),
(233,0,2,'zhCN','他们也许把别的农民都赶跑了，但萨尔迪亚一家永远不会离开西部荒野。'),
(234,0,1,'zhCN','万岁，$n！人民卫士！'),
(234,0,2,'zhCN','$n 万岁！这片土地终将重归我们手中！'),
(234,1,0,'zhCN','举目四望，尽是盗贼。我们人民民兵团必须让这片土地重归农民之手。'),
(234,1,1,'zhCN','农场必须被解放。暴风城或许抛弃了这些人，但我绝不会。'),
(234,1,2,'zhCN','西部荒野的人民不会原谅暴风城的背弃。'),
(237,0,0,'zhCN','真不敢相信那破车抛锚了。这片土地上一点运气都没有……'),
(237,0,1,'zhCN','只要我把这辆车修好，咱们就能离开这儿了……'),
(238,0,0,'zhCN','别担心，老布兰奇，很快给你弄点吃的……'),
(238,0,1,'zhCN','我从没想过有一天会离开西部荒野的家乡……'),
(257,0,2,'zhCN','别杀我！别杀我！'),
(263,0,1,'zhCN','单靠夜色守望无法永远保护我们。我们需要暴风城军队的支持。'),
(263,1,0,'zhCN','这消息令人忧心，我担心它与 $n 和那位防腐师之间的交易有关。'),
(263,2,0,'zhCN','守望者，去通知阿尔西娅，一股可怕的威胁正在朝我们镇子集结。我们必须备战！'),
(264,0,0,'zhCN','待在路上。森林里到处都是亡灵。'),
(264,0,1,'zhCN','别怕。夜色守望很快会清除这片土地上的污秽。'),
(264,1,0,'zhCN','这不是好兆头。派侦察兵收集更多情报，并保持警戒。'),
(264,2,0,'zhCN','区区一具腐烂的尸体，拦不住我们！'),
(265,0,0,'zhCN','我感觉到有邪恶正在酝酿……'),
(265,0,1,'zhCN','星辰向我诉说着。它们低语着黑夜中潜伏的恐怖。'),
(265,0,2,'zhCN','未来充满了死亡与未知，与过去并无二致。'),
(265,0,3,'zhCN','灵魂在我耳边低语。它们躁动不安，满心焦虑。'),
(268,0,0,'zhCN','%s 开始翻译……'),
(268,1,0,'zhCN','$n，翻译完成了！'),
(270,0,1,'zhCN','森林里爬满了狼人和食尸鬼。必须做点什么了！'),
(273,0,0,'zhCN','这黑暗的污秽对生意可不妙。'),
(274,0,0,'zhCN','嘘——。我们刚进了一批月光酒……'),
(274,0,1,'zhCN','快来快来，润润嗓子吧。'),
(276,0,0,'zhCN','今晚的星辰将格外璀璨！'),
(276,0,1,'zhCN','夜空中运转着比魔法更伟大的力量。总有一天他们会听我的……'),
(295,0,0,'zhCN','欢迎来到狮王之傲旅店。请自便！'),
(295,1,0,'zhCN','要做的事太多了，太多了！时间都去哪了？'),
(295,1,1,'zhCN','若你酒杯已满，愿它再次斟满！'),
(295,2,0,'zhCN','迪菲亚？我从没跟他们打过交道……呃，自从老石匠公会时代起就没了。还要别的吗？'),
(300,0,0,'zhCN','嗷！！！我砸碎 $r！'),
(300,0,1,'zhCN','我砸！你死！'),
(300,0,2,'zhCN','我要碾碎你！'),
(325,0,3,'zhCN','什么时候才会有人对亡灵做点什么？'),
(325,0,4,'zhCN','大家都去哪了？'),
(325,0,5,'zhCN','我现在连安安静静去父亲坟前祭拜都做不到了。'),
(327,0,1,'zhCN','你不准拿蜡烛！'),
(327,0,2,'zhCN','别杀我！别杀我！'),
(334,0,0,'zhCN','蠢 $R！黑石氏族会在你的坟前起舞！'),
(334,0,1,'zhCN','愚蠢的 $C！你根本不是我的对手！'),
(334,0,2,'zhCN','我是加斯·伊尔佐格！而你，是濒临死亡的 $R！'),
(334,0,3,'zhCN','让 $n 去死！黑石氏族万岁！'),
(334,0,4,'zhCN','谁敢擅闯黑石氏族？让这 $R 去死！'),
(334,0,5,'zhCN','渺小的 $C！你根本不是黑石氏族的对手！'),
(334,0,6,'zhCN','愚蠢的 $C！我会折断这个弱小 $R 的骨头！'),
(334,0,7,'zhCN','强大的黑石氏族万岁！'),
(341,0,0,'zhCN','快点伙计们，我们得把这座桥重建起来。'),
(346,0,0,'zhCN','拉个凳子坐下喝一杯吧！'),
(346,0,1,'zhCN','瓶子虽落了灰，酒下肚却清冽！'),
(348,0,0,'zhCN','没鱼上钩……'),
(348,0,1,'zhCN','鱼儿乖乖……到爸爸这儿来。'),
(412,0,0,'zhCN','嗷嗷嗷嗷！！'),
(412,0,1,'zhCN','夜色镇……我饥饿难耐！！'),
