(446,0,2,'zhCN','吼吼吼！'),
(468,1,0,'zhCN','夜色镇的居民们，拿起武器！一具亡灵憎恶正沿着道路逼近！'),
(468,2,0,'zhCN','那憎恶已经冲破了夜色守望的营地！快，我们必须在它抵达镇子前拦截它！'),
(468,3,0,'zhCN','还不够！守卫者们，到镇子中央集合。我们并肩对抗这亡灵怪物！'),
(468,4,0,'zhCN','憎恶来了！前进！'),
(468,5,0,'zhCN','野兽已被诛杀！夜色镇平安了！'),
