(476,0,2,'zhCN','别杀我！别杀我！'),
(483,0,0,'zhCN','日安，科贝特。这是你的奶酪，今早刚做的！你店里生意如何？'),
(483,0,1,'zhCN','嗨，科贝特！给，拿着！你那布料店生意还好吧？'),
(487,0,0,'zhCN','据报道，金海岸采石场和江戈尔矿洞有大量豺狼人活动。'),
(490,0,0,'zhCN','海岸线上有迪菲亚活动的报告。哨兵岭一切正常。'),
(550,0,3,'zhCN','谁敢干扰迪菲亚兄弟会的生意？去死吧，$C！'),
(550,0,4,'zhCN','挡我者 $R 死！'),
(550,0,5,'zhCN','谁敢挑衅艾德温·范克里夫的信使？去死吧，$R！'),
(550,0,6,'zhCN','我有寄给 $n 的信吗？哎呀，没有！看来是时候让你去死了！'),
(550,0,7,'zhCN','给 $n 一首电报歌：玫瑰红艳艳，紫罗兰蓝盈盈，见 $R 我必杀，包括你在内！'),
