(733,0,0,'zhCN','很好。你下岗了，列兵。休息吧，但别太安逸。库尔森不会永远放过我们。'),
(738,0,0,'zhCN','该巡逻了。我很快回来。'),
(738,1,0,'zhCN','既然周围安全了……'),
(738,2,0,'zhCN','嗯，我到了。我准备好归队了……'),
(738,3,0,'zhCN','谢谢你救了我！'),
(738,4,0,'zhCN','我离开了很久……我得回去了。'),
(738,5,0,'zhCN','索尔森列兵巡逻归来。没有新情况报告——外面挺安静的……'),
(751,0,0,'zhCN','%s 变得狂怒！'),
(773,0,0,'zhCN','%s 吸了一小撮梦境之尘进鼻子……'),
(773,1,0,'zhCN','%s 晕头转向……'),
(773,2,0,'zhCN','阿嚏！'),
(773,3,0,'zhCN','哇！$n，那梦境之尘可真厉害！'),
(775,0,0,'zhCN','你哪儿也别想加入，索尔森……'),
(775,1,0,'zhCN','现在你去死吧！'),
(777,0,0,'zhCN','你好，安东尼奥。真高兴又看到你平安到达。需要什么尽管说。'),
(777,1,0,'zhCN','保重，安东尼奥。一周后再见。'),
(794,0,0,'zhCN','可恶！这儿也没鱼上钩。我要回我老钓鱼点去！'),
(794,1,0,'zhCN','哎呀，这儿的鱼好像也不上钩。也许我该去水晶湖碰碰运气！'),
(821,0,0,'zhCN','哨兵岭一切正常，斯托曼特尔领主。不过月溪镇有大量迪菲亚活动的报告。'),
(844,0,0,'zhCN','卖货啦！卖货啦！在我离开之前，来逛逛安东尼奥的货品吧，闪金镇的乡亲们。'),
(844,0,1,'zhCN','来吧，大家都来！安东尼奥的货品大甩卖。我可能很久都不会回来，所以快来吧，都来吧。'),
(844,0,2,'zhCN','闪金镇的好人们，快来趁我稀有货物超低价抢购。我一段时间都不会回来了！'),
(844,1,0,'zhCN','再见了，闪金镇。我很快会回来——大概一周吧。'),
(844,2,0,'zhCN','闻名各地的安东尼奥·佩雷利的货物，现在哨兵岭附近有售！我很快就要走了，抓紧时间。'),
(844,2,1,'zhCN','经久耐用、做工精良的物品在哨兵岭附近出售！来吧，大家都来！时间不多，抓紧了。'),
(844,2,2,'zhCN','是时候再次让途经哨兵岭的旅人都能买到我的货品了！来吧，大家都来！'),
(844,3,0,'zhCN','谢谢大家。我大约一周后再来。'),
(844,4,0,'zhCN','那，接下来去夜色镇吧。'),
(844,5,0,'zhCN','%s 长长地叹了口气。'),
(844,6,0,'zhCN','我最讨厌工作的这一环了。噢，暮色森林，对可怜的安东尼奥温柔些吧。'),
(844,7,0,'zhCN','旅人和冒险者们，快到镇中心广场来，趁安东尼奥的优惠价格抢购！来吧，大家都来！'),
(844,7,1,'zhCN','幸会，暮色森林的旅人们！我的好货只在夜色镇短期出售。快些来！'),
(844,7,2,'zhCN','放下你的战斗或差事，来看看我的好货吧！只在夜色镇停留片刻……愿圣光为此赞颂。'),
(844,8,0,'zhCN','再会了，夜色镇的乡亲们。下次见……'),
(844,9,0,'zhCN','终于到赤脊山了。比起暮色森林那黑暗冰冷的雾气，这儿令人心旷神怡。'),
(844,10,0,'zhCN','你好，你好，艾米。能回到湖畔镇见到你真好，小姐。'),
(844,11,0,'zhCN','我终于到了湖畔镇——来吧，大家都来，趁安东尼奥·佩雷利的超值优惠抢购。'),
(844,11,1,'zhCN','足以助你穿越暮色森林的强力物品，安东尼奥·佩雷利的货物现于湖畔镇出售。'),
(844,11,2,'zhCN','听着，听着！我只在湖畔镇稍作停留卖货。快到镇公所来！'),
(844,12,0,'zhCN','又见到你了，艾米，真好。保重，亲爱的。我现在要去闪金镇了。'),
(844,13,0,'zhCN','你们好，朋友们。真高兴又见到你们。看来你们仍在守护着我们的边境。安东尼奥感激你们的辛劳。'),
(844,14,0,'zhCN','不必客气！我得赶路了……你们都要保重。'),
(844,15,0,'zhCN','噢，我会的，朋友。我一定会的。你也保重。'),
(844,16,0,'zhCN','古董、兵器、稀有护甲。若不来看看，谁知道安东尼奥这周会带些什么。'),
(844,16,1,'zhCN','这周也许是蝾螈之眼，或许是一张藏宝图。不来看看你永远不知道。安东尼奥会带些什么呢？'),
(844,16,2,'zhCN','各地的冒险者都把东西卖给安东尼奥——亲自来看看他这周为你准备了什么小宝贝吧。'),
(903,0,0,'zhCN','马里斯元帅随时等待暴风城的援军……'),
(932,0,0,'zhCN','暴风城的增援在哪？东边有黑石氏族大量活动的报告。'),
(933,0,0,'zhCN','希望暴风城的增援快点到……'),
(935,0,0,'zhCN','仍不见暴风城第二营的踪影。有报告称东北方向有暗影隐匿氏族的动向。'),
(946,0,0,'zhCN','我的武器渴了！'),
