(1364,0,1,'zhCN','$n！拉格纳罗斯的背叛者！'),
(1364,0,2,'zhCN','黑铁矮人终将收复他们应得的大地！'),
(1364,0,3,'zhCN','愚蠢的 $C！你根本不是拉格纳罗斯爪牙的对手！'),
(1364,0,4,'zhCN','像你这样卑贱的 $R，$n，根本不配踏上这片土地！'),
(1364,0,5,'zhCN','$n！准备迎接你的末日吧！'),
(1364,0,6,'zhCN','这个敢挑战本座威能的弱小 $C 是谁？去死吧，蠢货！'),
(1364,0,7,'zhCN','我是污秽者巴尔加拉。而你，$n，即将化为尘土与灰烬。'),
(1366,0,0,'zhCN','你在胡编乱造。'),
(1366,0,1,'zhCN','嘘！你把鱼都吓跑了。'),
(1366,0,2,'zhCN','真的？'),
(1366,0,3,'zhCN','才没有。'),
(1366,0,4,'zhCN','也许我们该去桥上钓。'),
(1366,0,5,'zhCN','骗子！'),
(1366,0,6,'zhCN','你要是钓鱼和嘴皮子一样厉害，海里早没鱼了。'),
(1366,0,7,'zhCN','你要是真能钓上一条配得上你那张嘴的大鱼，咱们就再也不会饿了。'),
(1366,1,0,'zhCN','快点，我们换个地方试试。'),
(1367,0,0,'zhCN','我听说有种巨大的鱼能在陆地上行走捕猎，还会吃人！'),
(1367,0,1,'zhCN','我爸爸说，海里有一种鱼大得能吞下一整艘船。'),
(1367,0,2,'zhCN','我听过一个故事，说有条金鱼，要是钓到它就能实现三个愿望！'),
(1367,0,3,'zhCN','还有一次，在营地，我钓到一条比我还大的鱼！！'),
(1367,0,4,'zhCN','我上周钓到一条大的，它有三只眼睛！'),
(1367,0,5,'zhCN','我爸爸钓的鱼比你爸爸多！'),
(1367,1,0,'zhCN','你觉得这里面有鱼吗？'),
(1367,2,0,'zhCN','看！看！我钓到东西了！唉……只是一只臭烘烘的旧靴子。'),
(1368,0,0,'zhCN','于是骑士们列阵于冲锋的部落之前，当上千名狂暴兽人涌过山谷时，他们坚守阵地。'),
(1368,0,1,'zhCN','洛萨就是这么赤手空拳杀死了三十六个兽人！'),
(1368,0,2,'zhCN','然后那只兔子一口咬掉了他的脑袋……我发誓是真的。'),
(1368,0,3,'zhCN','据说他有时能变成一只乌鸦。'),
(1368,0,4,'zhCN','你知道吗，运河里有鳄鱼。它们本是当宠物从沼泽带来的，后来被丢进了运河。'),
(1368,0,5,'zhCN','你知道兽人的眼睛为什么发红光吗？因为他们喝血！'),
(1368,0,6,'zhCN','我发誓，真有人见过他们。熊猫人真的存在！'),
(1368,0,7,'zhCN','这里没有勺子。'),
(1370,0,0,'zhCN','我爸爸说那只是个故事。'),
(1370,0,1,'zhCN','你能想象吗？'),
(1370,0,2,'zhCN','噢得了吧，那不是真的。'),
(1370,0,3,'zhCN','噢对，我听说过那事。'),
(1370,0,4,'zhCN','真的？'),
(1370,0,5,'zhCN','听起来倒像比利的吹鱼故事。'),
(1370,0,6,'zhCN','真不错。'),
(1370,0,7,'zhCN','哇。'),
(1371,0,0,'zhCN','噫……那不是鱼！'),
(1371,0,1,'zhCN','我觉得这些运河里根本没鱼。'),
(1371,0,2,'zhCN','我鞋上沾了蚯蚓内脏。'),
(1371,0,3,'zhCN','希望那是一条鱼！'),
(1371,0,4,'zhCN','我觉得我看见什么了。'),
(1371,0,5,'zhCN','有什么怪味。'),
(1371,0,6,'zhCN','蚯蚓穿钩，钩入水中。鱼在水里，是我们的鱼。'),
(1371,0,7,'zhCN','我好像听见什么了。'),
(1377,0,0,'zhCN','啊对。那些新玩意儿我全听过了。说是拆了外壳的装甲来减重。呸！胡扯！'),
(1377,1,0,'zhCN','呸！等你进入老巨魔犁的射程，早就被轰成碎片了！'),
(1377,2,0,'zhCN','嘿，菲泽，我有没有跟你讲过那次我骑车穿过运河，几个穿收割机装甲服的地精想伏击我？'),
(1377,3,0,'zhCN','布拉哈！老巨魔犁的炮塔转过来对准他们时，他们脸上的表情！他们的锯子连我边都蹭不到！'),
(1377,4,0,'zhCN','呸！那有什么意思！'),
(1377,5,0,'zhCN','哎，行，只要之后咱们能立刻上竞技场就行！'),
(1377,6,0,'zhCN','哈！你怕我把你那小娇车弄坏？'),
(1377,7,0,'zhCN','哈哈！结实的老巨魔犁只有几道浅浅的战斗伤痕！'),
(1377,8,0,'zhCN','哈！比起那个，我天天都选火山炮XT发射炮弹的轰鸣声！'),
(1377,9,0,'zhCN','也许吧，可它要是真砸我脑袋上，我正好知道用哪门炮把它轰成最小的碎渣！'),
(1378,0,0,'zhCN','嘿，斯通，你听说老通克伦德换上的新蒸汽引擎没？'),
(1378,1,0,'zhCN','你就不能想点打架以外的事？在赛道上我绕你几圈都没问题！'),
(1378,2,0,'zhCN','啊！你真是没救了！'),
(1378,3,0,'zhCN','啊，让我想想。是啊，我赌现在差不多快一百次了！'),
(1378,4,0,'zhCN','我早就在油箱里加点永耀油，趁他们发现我溜了之前就回家了！'),
(1378,5,0,'zhCN','嘿斯通，找个时间咱们去赛道跑跑。绕几圈看看谁赢？'),
(1378,6,0,'zhCN','你说什么我都不会上竞技场，去对付你那叫蒸汽坦克的怪物机器！'),
(1378,7,0,'zhCN','哈！我更怕那些旧窟窿和裂口把那玩意儿崩开，让我被弹片淋一身！'),
(1378,8,0,'zhCN','没有什么比双化油器叉环蒸汽引擎烧纯火石的声音更动听了！'),
(1378,9,0,'zhCN','呸！就算好蒸汽引擎砸你脑袋上你也认不出来！'),
(1379,3,0,'zhCN','啊，终于到了！把这些桶卸掉可真痛快。'),
(1380,0,0,'zhCN','抱歉，胡尔达……不过看来我误导了你。'),
(1386,0,0,'zhCN','她的手段怯懦。她让我想起被遗忘者的药剂师。'),
(1386,1,0,'zhCN','安静。'),
(1386,1,1,'zhCN','还记得精灵来之前这里有多安静吗？我真怀念。'),
(1386,1,2,'zhCN','闭嘴。'),
(1386,1,3,'zhCN','我也拿不准谁更疯。'),
(1386,1,4,'zhCN','我宁愿把杵臼扔了换副耳塞。'),
(1395,0,3,'zhCN','能施舍几个硬币不？'),
(1395,0,4,'zhCN','帮帮穷光蛋呗？'),
(1395,0,5,'zhCN','擦盔甲，一个铜板。'),
(1395,0,6,'zhCN','都怪那些蠢兽人。非把我农场烧个精光。'),
(1395,0,7,'zhCN','给穷人施舍点？'),
(1405,0,3,'zhCN','都怪那蠢暴风城军队。非在我农场后头建塔。'),
(1405,0,4,'zhCN','给可怜的瞎子施舍点零钱？……你说我不是瞎子什么意思？……我不瞎！我能看见！！真是奇迹！'),
(1405,0,5,'zhCN','今天先吃个汉堡，星期二我一定付你钱。'),
(1405,0,6,'zhCN','都怪那些蠢兽人。非把我农场烧个精光。'),
(1405,0,7,'zhCN','给穷人施舍点？'),
(1413,0,0,'zhCN','如果我们逆转精华的流向，也许能改变极性。'),
(1413,0,1,'zhCN','那样魔法阵列就会级联成一股带正电荷能量的连锁反应。'),
(1413,0,2,'zhCN','传送门会微微偏移，此时若施一个束缚小法术，就能将它固定原位。'),
(1413,0,3,'zhCN','当正向能量与负电荷能量相撞，它们并不会相互抵消。'),
(1413,0,4,'zhCN','马吉诺说，扭转折叠的正能量流反而能形成更稳定的流动。'),
(1413,0,5,'zhCN','那时的魔法结界应能得到能量流足够的支撑，从而禁锢那个实体。'),
(1413,0,6,'zhCN','我们为何不直接调整阵列来补偿能量流的偏差？'),
(1413,0,7,'zhCN','设置十二个聚焦点，也许能让魔法能量成形得更稳固，增添必要的稳定性。'),
(1414,0,0,'zhCN','可若由此产生的频率偏移让魔法反噬顺流而上呢？'),
(1414,0,1,'zhCN','若施法前未妥善锚定，那不会让法网崩解吗？'),
(1414,0,2,'zhCN','可那岂不是意味着水流交汇？那不是很糟糕吗？'),
(1414,0,3,'zhCN','不过生成的能量可能会坍缩，引发一股能量流，让你头痛好几周。'),
(1414,0,4,'zhCN','可那不正是导致修士西莱莉雅魔法公式最初出问题的原因吗？'),
(1414,0,5,'zhCN','我看不会，我可不想再被炸一次。'),
(1414,0,6,'zhCN','不过那会打破魔法焦点的平衡，并在以太中引发反向振动。'),
(1414,0,7,'zhCN','我想那也许行得通，只要我们有二十个人一起施法。'),
(1415,0,0,'zhCN','要是我们用三处泰瑞安式的聚焦点呢？应该能解决。'),
(1415,0,1,'zhCN','但若我们在恰当的能流枢纽用锚线将它稳定，应该就可行。'),
(1415,0,2,'zhCN','你总是这么消极。那种事发生的概率介于零和零之间。'),
(1415,0,3,'zhCN','只要用对顺序就没问题。只是开始前得好好钻研一番。'),
(1415,0,4,'zhCN','哇，折腾这么大阵仗就为瓶爱情药水。希望他值得。'),
(1415,0,5,'zhCN','若用苏瑞安理论，那就行；但若走伊瑟瑞安一派则不行。'),
(1415,0,6,'zhCN','至少到时我们已不在这儿，不必收拾残局。'),
(1415,0,7,'zhCN','除非我们没按正确的初始化流程来。'),
(1416,2,0,'zhCN','%s 开始施法……'),
(1416,3,0,'zhCN','神了！成功了！$n，你的盔甲我做好了。'),
(1421,0,0,'zhCN','诅咒你，$n！总有一天，复仇属于我！'),
(1423,0,0,'zhCN','又见面了，安东尼奥。再次谢谢你给我妻子的帽子。她爱极了。'),
(1423,1,0,'zhCN','保重，安东尼奥。'),
(1427,0,0,'zhCN','啊，多谢，科贝特。我们马上把这些上架。'),
(1427,0,1,'zhCN','啊对，而且送达及时。一如既往，和你做生意是种享受，科贝特。'),
(1428,0,0,'zhCN','亲爱的科贝特。哈兰急需一批针织衫和裤子，尽快安排。'),
(1428,0,1,'zhCN','科贝特，在吗？哈兰又需要一批针织货。你能送给他吗？'),
(1433,0,0,'zhCN','乐意之至，小甜心。我很快回来……'),
(1433,0,1,'zhCN','集市那边生意一定不错。我这就给他补货！'),
(1433,1,0,'zhCN','嗯……卸完这趟，我想去那家奶酪店吃点东西。'),
(1433,1,1,'zhCN','这单该能多赚几个硬币。也许给自己买份午饭……'),
(1433,2,0,'zhCN','嘿，哈兰。这是给你的一批针织布料。'),
(1433,2,1,'zhCN','哎哟！哈兰，这又是一批补给。肯定卖得飞快！'),
(1433,3,0,'zhCN','那我走了。保重，哈兰。'),
(1433,3,1,'zhCN','很高兴见你生意这么红火，哈兰。希望很快再见到你……'),
(1433,4,0,'zhCN','现在去吃零食……'),
(1433,5,0,'zhCN','日安，埃林！嗨，伊莱恩！给我来一轮蓝纹奶酪，如何？'),
(1433,5,1,'zhCN','嗨，特里亚斯家族！请给我一团你们家的烟熏马苏里拉！'),
(1433,6,0,'zhCN','是的女士，生意兴隆！'),
(1433,7,0,'zhCN','多谢您的好意！'),
(1433,7,1,'zhCN','谢了，奶酪！'),
(1433,8,0,'zhCN','我得在蕾玛开始担心前回去……'),
(1433,8,1,'zhCN','该回店里了……'),
(1433,9,0,'zhCN','我回来了！'),
(1436,0,0,'zhCN','让路！让路！'),
(1436,1,0,'zhCN','市长阁下！我们的侦察兵报告西边有异常活动。'),
(1436,1,1,'zhCN','艾洛市长！我们的墓地侦察兵带回了不祥的报告……'),
(1436,2,0,'zhCN','从那个老隐士的小屋传来可怕的咆哮与低吼！'),
(1436,3,0,'zhCN','狼群朝这边奔来，仿佛在逃离……什么可怕的东西。'),
(1436,4,0,'zhCN','遵命，市长阁下。'),
(1436,5,0,'zhCN','阿尔西娅，有报告说墓地发生怪事。艾洛认为这预示着夜色镇将遭袭击。'),
(1436,6,0,'zhCN','是，指挥官！'),
(1436,7,0,'zhCN','警戒！警戒！荒野中潜藏威胁！夜色守望者，保持警惕！'),
(1439,0,0,'zhCN','哎呀，那黑爪烈啤后劲可真足！'),
(1439,1,0,'zhCN','我觉……头晕。这……里……好……热……'),
