(1449,0,0,'zhCN','大家准备好！猿猴来啦！'),
(1476,0,0,'zhCN','外头海面不平静。海灵一定躁动不安……呃！'),
(1476,0,1,'zhCN','我有次见过一个海巨人。那场面我可不想再看一次。嗝！'),
(1476,0,2,'zhCN','我本想出去清掉些豺狼人，可这条老腿不行了，怕是只会送命。'),
(1476,0,3,'zhCN','外头走路当心。不少冒险者进了沼泽就没再出来。呃！'),
