(3446,2,0,'zhCN','嘿 $n！别忘了拿箱子、说明书和指挥棒！'),
(3454,0,0,'zhCN','敌舰！那定是兽人的船！开火！'),
(3454,0,1,'zhCN','地平线上那是啥？必是敌舰无疑！开火！'),
(3454,0,2,'zhCN','东边地平线出现船帆。必是入侵者！开火！'),
(3454,0,3,'zhCN','那是什么？海巨人？宁可谨慎勿后悔。开火！'),
(3454,0,4,'zhCN','外头有动静。放一发警告弹！'),
