(3504,0,6,'zhCN','为啥咱们总走同一条路？'),
(3504,0,7,'zhCN','我要尿尿。'),
(3511,0,0,'zhCN','反正咱为啥非得学这些东西？'),
(3511,0,1,'zhCN','这比历史书里的插图好看。'),
(3511,0,2,'zhCN','老师，咱们什么时候去看闪闪发光的法师塔？'),
(3511,0,3,'zhCN','老师，我要尿尿！'),
(3511,0,4,'zhCN','老师，暴风城有暗夜精灵吗？我以前从没见过暗夜精灵。'),
(3511,0,5,'zhCN','老师，他老是戳我！'),
(3511,0,6,'zhCN','我听说底下还埋着兽人呢。'),
(3511,0,7,'zhCN','我想看大图书馆里的巨龙骨架。'),
(3512,0,0,'zhCN','圣骑士真的在这里训练吗？'),
(3513,0,0,'zhCN','这里是光明大教堂，暴风城灵性启迪的中心。'),
(3513,1,0,'zhCN','这里是暴风要塞。它建于暴风城堡的废墟之上，那座城堡在第一次大战中被部落摧毁。'),
(3513,2,0,'zhCN','是的，确有其事。圣骑士与牧师都在大教堂的围墙之内修炼技艺、探究至理。'),
(3513,3,0,'zhCN','孩子们，请随我来，我们现在去要塞，那里瓦里安·乌瑞恩国王正端坐于王座之上。'),
(3513,4,0,'zhCN','部落溃散之后，人们回到这里，重建这座伟大的城市，以见证我们的存续。'),
(3513,5,0,'zhCN','好吧……我们前往纪念两次大战英雄的纪念碑，英雄谷。跟我来。'),
(3513,6,0,'zhCN','孩子们，难道不令人惊叹吗？所有进城之人都须从这些大地最伟大的英雄注目之下走过。'),
(3513,7,0,'zhCN','叹为观止。孩子们，回学校后，你们每人要就其中一位传奇人物做口头报告。'),
(3513,8,0,'zhCN','现在，再好好看一眼，然后我们前往圣区与伟大的光明大教堂。'),
(3521,0,0,'zhCN','从桌上取一块石头，$n。你的任务用得上。'),
(3540,0,0,'zhCN','卫兵！救我！'),
(3541,0,0,'zhCN','卫兵！救我！'),
(3543,0,0,'zhCN','卫兵！救我！'),
