(3583,1,0,'zhCN','谢谢你，$n。也祝你好运。'),
(3616,3,0,'zhCN','%s 继续冥想……'),
(3626,1,7,'zhCN','你觉得我还需要再多些花哨的装饰吗？'),
(3626,2,0,'zhCN','觉得热？来猪与哨声酒馆喝点凉的降降温！'),
(3626,2,1,'zhCN','每晚都有群殴和美酒！猪与哨声酒馆统统都有！'),
(3626,2,2,'zhCN','来猪与哨声酒馆免费喝啤酒！'),
(3626,2,3,'zhCN','跟我说说话，就能在猪与哨声酒馆免费喝一杯！'),
(3626,2,4,'zhCN','比精灵还顺滑，比兽人还浓烈！全暴风城没有更好的酒！'),
(3626,2,5,'zhCN','受够了那些娘娘腔法师的饮品？来猪与哨声酒馆尝点够劲的！'),
(3626,2,6,'zhCN','远行归来？来猪与哨声酒馆歇歇脚、放松下！'),
(3626,2,7,'zhCN','暴风城最好的酒！'),
(3627,0,7,'zhCN','问我怎么在蓝色隐士酒馆免费喝一杯！'),
(3628,0,0,'zhCN','好！好！'),
(3658,0,0,'zhCN','贫瘠之地最好的武器在这儿！'),
(3658,0,1,'zhCN','快来！灰谷这一带最精良的武器任你挑！'),
(3658,0,2,'zhCN','利扎里克有刀剑。利扎里克有锤斧。利扎里克这儿全有你需要的武器！'),
(3658,0,3,'zhCN','手快有手慢无！武器赶紧来这买！'),
(3660,0,0,'zhCN','阿瑟里克斯指着你在你耳边咆哮，那话语刮擦着你的耳膜。这是你听到的最后声响。'),
(3660,1,0,'zhCN','我……我的力量消退了……你这傲慢之徒，必付出代价！'),
(3660,2,0,'zhCN','不！你不可能击败我！'),
(3663,0,0,'zhCN','击碎这块灵魂石倒不是难事！'),
(3663,1,0,'zhCN','那我们必须了结阿瑟里克斯·纳拉辛。告诉我，灵魂，我们到哪里去找其余灵魂宝石，以解除他的魔法？'),
(3664,0,0,'zhCN','我们要割开你们的喉咙，放干你们的血！'),
(3664,0,1,'zhCN','我们要你们的头颅！'),
(3664,0,2,'zhCN','为了黑暗之岸！'),
(3692,4,0,'zhCN','噢不！他们来了！'),
(3692,5,0,'zhCN','我们成功了，我的朋友。记得找到泰伦西斯，告诉他我们平安。再次感谢。'),
(3693,8,0,'zhCN','我这就动手，$n。'),
(3693,9,0,'zhCN','现在……我的线和针放哪了。啊！在这……'),
(3693,10,0,'zhCN','%s 在你取走披风时开始施法。'),
(3693,11,0,'zhCN','走吧，$n。去找沃尔科……记住，护你的魔法一旦与任何人交互便会失效，交谈除外。'),
(3694,0,0,'zhCN','泰伦西斯，蕾妮派我来找你。哨兵们在灰谷需要援助。'),
(3694,1,0,'zhCN','谢谢你，泰伦西斯。我会在此坚守，能撑多久是多久。'),
(3694,2,0,'zhCN','但愿我能派几个得力之人去援助灰谷和哨兵。'),
(3694,3,0,'zhCN','再次感谢，泰伦西斯。若还需援助，我会再来。在此之前，请多派冒险者前往灰谷。'),
(3695,1,0,'zhCN','%s 一边朝泰伦西斯低吼，一边用爪子跺地。'),
(3695,2,0,'zhCN','%s 对泰伦西斯吼得更凶，但这次德鲁伊似乎听懂了熊的意思。'),
