(3916,0,0,'zhCN','这根法杖的设计很简单。达托尔创造它时并未用上他的奥术知识……它本质上更偏德鲁伊之道。'),
(3916,1,0,'zhCN','嘿嘿……我讲了个双关，对吧？Druidic in nature……我真幽默。'),
