(3916,3,0,'zhCN','好了！没那么难。你刚才说你和蕾妮要用这东西做什么来着？它可真厉害！'),
(3932,0,0,'zhCN','%s 变得狂怒！'),
(3976,3,0,'zhCN','$n，你握着我父亲的剑。我的士兵任你调遣，我的$g Lord:Lady;。收下他们……率领他们……不洁者必须被清除。他们身上的污秽必须被净化。'),
