(7956,0,0,'zhCN','你准备好了我就好了，$n。带路吧！'),
(7956,1,0,'zhCN','我们成功了！回到格里姆图腾营地上方的杰凯身边与我会合。'),
(7956,2,0,'zhCN','不！精灵龙撑不住了，$n！我得回去找杰凯，确认她没被发现。艾露恩与你同在。'),
(7956,3,0,'zhCN','快！$n进攻了！'),
(7956,3,1,'zhCN','死吧，$n。艾露恩不会再任你伤害她的生灵！'),
(7956,3,2,'zhCN','受死吧，$n。你竟敢靠近我一箭之遥！'),
(7956,3,3,'zhCN','你竟敢碰我？！'),
(7956,4,0,'zhCN','噢，不！我们没时间了。'),
