(8115,3,0,'zhCN','武器我已经完成了，$n。'),
(8216,0,0,'zhCN','%s变得狂暴！'),
(8256,1,0,'zhCN','正好有个地方可以放这只号角！'),
(8256,2,0,'zhCN','我一直留着这地方，等一件特别的东西。我想再没有比这更特别的了，$n。'),
(8256,3,0,'zhCN','好了，大功告成！'),
(8284,0,0,'zhCN','停下……得喘……口气。'),
(8284,1,0,'zhCN','就是这儿，$r：大锅！在地图上做个记号，或者想点办法，可别忘''''了。万一我有个三长两短，我的队友就永远困在那矿里了。'),
(8284,2,0,'zhCN','我''''得戒烟了！让我喘口气。'),
(8284,3,0,'zhCN','我们''''快到安全的地方了。从这开始跑。别掉太远！走！'),
(8284,4,0,'zhCN','门就在眼前！我们''''能逃出去了！但先让我歇口气。'),
(8284,5,0,'zhCN','啊啊啊啊！他打中我了！'),
(8284,6,0,'zhCN','%s指向地上的羊皮纸。'),
(8284,7,0,'zhCN','%s在一阵尘土中消失了。'),
(8284,8,0,'zhCN','你打算让一个受伤的矮人替你把所有活儿都干了吗？'),
(8284,8,1,'zhCN','来吧！$n，认识一下我的拳头。拳头，跟$n打个招呼。'),
(8284,9,0,'zhCN','前进！这次给我打起精神！我可不会再替你打任何仗了。'),
(8337,0,0,'zhCN','桑塔拉的秘密绝不会传出这片土地。'),
(8338,0,0,'zhCN','他''''归我了……'),
(8383,210,0,'zhCN','你''''太过分了，$N。'),
(8383,210,1,'zhCN','接着''''这么干，$N，我就替你长长规矩。'),
(8383,210,2,'zhCN','别''''逼我跟你来狠的。'),
(8383,211,0,'zhCN','%s不以为然。'),
(8390,0,0,'zhCN','好了！活儿干完了。'),
(8392,0,1,'zhCN','等你很久了，$n。很高兴你赶到了。货带来了吗？'),
(8393,0,0,'zhCN','什……发生了什么？'),
(8419,0,0,'zhCN','异教徒！'),
(8419,0,1,'zhCN','你竟敢打断我们的祈祷？处决他们！'),
(8419,0,2,'zhCN','你将作为献给拉格纳罗斯的合适祭品。'),
(8419,0,3,'zhCN','好极了，新鲜的血来了。'),
(8421,2,0,'zhCN','当我在格里姆西尔特挖掘场偶然发现桑塔拉之石时，拉格纳罗斯的力量贯穿了我的全身。是拉格纳罗斯赋予了我使命。'),
(8421,3,0,'zhCN','是拉格纳罗斯的意志造就了黑曜石魔。黑曜石魔将摧毁黑石塔中的黑石兽人，让我们与炽热深渊中的同胞合而为一。'),
(8421,4,0,'zhCN','而最终，当我重生为火焰侍僧时，是拉格纳罗斯为我命名：拉索里克……黑衣拉索里克。'),
(8439,0,0,'zhCN','当你靠近暗丝偷猎者时，用这根号令之杖对雷兹施法，他会让他们后悔来这些土地上偷猎。'),
(8441,0,0,'zhCN','雷兹跟$n！雷兹砸偷猎者！砸砸砸！用棍子逗雷兹去砸！砸！'),
(8441,1,0,'zhCN','用棍子，告诉雷兹干啥！给雷兹看偷猎者！雷兹砸！'),
(8441,2,0,'zhCN','雷兹现在要回家。拜拜，$r。'),
(8441,2,1,'zhCN','拜拜，小小的$r。雷兹走了。'),
(8479,1,0,'zhCN','耐心点，$n。火把马上就完成了。'),
(8479,2,0,'zhCN','%s单膝跪地。他看起来筋疲力尽。'),
(8479,3,0,'zhCN','完成了……'),
(8480,0,0,'zhCN','确实辉煌，马尔特雷克。看来我的计划完美奏效了。你不这么认为吗，凡人？'),
(8480,1,0,'zhCN','%s发出一声爬虫般的笑声……至少你觉得那是笑。'),
(8480,2,0,'zhCN','若我们只是开口求助，你是绝不会去帮黑石军团的，不是吗？'),
(8480,3,0,'zhCN','闭嘴，蠢货！'),
(8480,4,0,'zhCN','他们会活下去，好亲眼看看自己劳作的果实：黑石军团入侵峡谷时必将随之而来的毁灭与混乱。'),
(8480,5,0,'zhCN','我这就离开你们了，凡人。活着，带着这些小玩意儿。马尔特雷克！把小玩意儿给他们！'),
(8480,6,0,'zhCN','%s开始更快地拍打他巨大的翅膀。他在为起飞做准备。'),
(8480,7,0,'zhCN','哦对，那层蜕皮——别弄丢了。在燃烧平原有我的同族，能用只有黑龙军团的蜕皮才能强化的物品来锻造。'),
(8480,8,0,'zhCN','黑石军团来了，矮子们！我们要焦土燎原，焚天烈焰。无人能活……'),
(8509,0,0,'zhCN','主人，我们该怎么处置他们？他们对我们没用了。'),
(8509,1,0,'zhCN','遵命，主人！'),
(8578,0,0,'zhCN','你竟敢！现在尝尝我的怒火！'),
(8579,0,0,'zhCN','千真万确，$n。厄运之轮如今正无可逆转地转向哈卡的真正归来！'),
(8579,1,0,'zhCN','血与灵魂，献给哈卡！哈哈哈哈！'),
(8581,0,0,'zhCN','谁敢？！我要毁灭你！'),
(8581,1,0,'zhCN','主人！！他们想毁掉您的杰作！！'),
(8581,2,0,'zhCN','哈！现在你死定了！'),
(8666,0,0,'zhCN','别担心，俺会给你找个好归宿的。'),
(8666,0,1,'zhCN','有人愿意收留我这只可爱的小猫咪吗？'),
(8666,0,2,'zhCN','我真不敢相信爹不让俺留下你姐姐。'),
(8666,0,3,'zhCN','出售小猫，寻个好人家。'),
(8666,0,4,'zhCN','过敏到底是什么意思？而且这跟我的两只小猫又有什么关系？'),
(8666,0,5,'zhCN','拜托，谁愿意收留我的小猫好不好？'),
(8668,0,0,'zhCN','%s搜寻着奥术能量的来源。'),
(8668,1,0,'zhCN','%s低吼着。'),
(8887,0,0,'zhCN','离开此地。<圣物迸发出一道炽白的火弧。你获得了一段记忆：一名黑铁矮人孤身被七具尸体环绕，跪在一座烈焰巨碑前。>'),
(8887,0,1,'zhCN','你将葬身于此。<你的脑海充满了混乱与毁灭的景象。>'),
(8887,0,2,'zhCN','凡人，勿要玷污这些废墟。<你被一道刺目的闪光吞没。你只记得曾看见一个完全由火焰构成的生物。>'),
(8887,0,3,'zhCN','帮帮我们，外乡人。<圣物化为尘土。八名黑铁矮人正在举行某种仪式的幻象涌入你的脑海。>'),
(8887,0,4,'zhCN','他无法被击败。<圣物燃为虚无。它所承载的记忆如今已属于你。这座城市是被一个非此世的存在毁灭的。>'),
(8887,0,5,'zhCN','你的存在已被知晓。<圣物化为尘埃。新知令你头痛欲裂。某种邪恶潜伏在山脉的深处。>'),
(8887,0,6,'zhCN','污染者……你必因这次入侵受惩。<圣物坠地碎裂前，一道火焰之徽从中散发。>'),
(8891,0,0,'zhCN','你躲不过我们。准备受焚吧！'),
(8905,0,0,'zhCN','入侵者！！'),
(8906,0,0,'zhCN','%s陷入狂乱！'),
(8929,0,0,'zhCN','%s因索瑞森大帝之死而明显震惊。'),
(8962,0,0,'zhCN','我会说猫语，埃夫西说谢谢你。'),
(8963,0,0,'zhCN','喵！'),
(8983,0,0,'zhCN','制造车间里有入侵者？我的构造体将摧毁你们！'),
(9017,0,0,'zhCN','我不可被毁灭！凭拉格纳罗斯的意志，我将重生！'),
(9019,2,0,'zhCN','国王万岁，宝贝！'),
(9019,3,0,'zhCN','你们的挣扎毫无意义，蠢货！你们永远无法击败我！'),
(9019,4,0,'zhCN','反正他们也只是碍事罢了。'),
(9019,5,0,'zhCN','哈！你根本无法想象你的挣扎有多徒劳。'),
(9019,6,0,'zhCN','你就这点能耐？你真以为能击败像我这样令人敬畏的存在？'),
(9019,7,0,'zhCN','谢谢你清除了那些愚蠢的元老。现在，准备在拉格纳罗斯最强大仆从的手中迎接末日吧。'),
(9021,0,0,'zhCN','钥匙……拿到钥匙……格尔斯塔恩有……钥匙。'),
(9021,0,1,'zhCN','想办法派上点用场吧，$r。快把我弄出去！高阶审问官拿着钥匙。'),
(9021,0,2,'zhCN','嘿！喂你！$R！快把我弄出去！'),
(9039,0,0,'zhCN','你已挑战了七人众，现在受死吧！'),
(9042,0,0,'zhCN','%s变得狂暴！'),
(9116,0,0,'zhCN','愿这邪恶气息从此器物上被驱散！'),
(9116,1,0,'zhCN','我能感觉到邪恶正在离去……'),
(9117,1,0,'zhCN','蓝加红……我预测……'),
(9117,2,0,'zhCN','$n，就是这样！我终于想通了！'),
(9117,3,0,'zhCN','啊……我的实验似乎从没成功过。也许我该回到下游去。'),
(9117,4,0,'zhCN','%s开始将不同颜色的晶体组合在一起。'),
(9117,5,0,'zhCN','我想……我想成了！'),
(9117,6,0,'zhCN','嗷！不对劲！'),
(9117,7,0,'zhCN','算了……也许下次吧。'),
(9117,8,0,'zhCN','我知道这次一定行……'),
(9117,8,1,'zhCN','这将是我至今最棒的实验！'),
(9117,8,2,'zhCN','这次肯定行……前面13次都只是练手！'),
(9117,9,0,'zhCN','现在，要是我把黄色的加进去……'),
(9119,0,0,'zhCN','希望这次能成！'),
(9119,1,0,'zhCN','%s把雾气加到血瓣花的嫩芽上。'),
(9119,2,0,'zhCN','看它们长得多欢！'),
(9119,3,0,'zhCN','%s看着那些害虫逃窜，大笑起来。'),
(9298,0,0,'zhCN','%s紧张地环顾四周。'),
(9298,1,0,'zhCN','你确定没被人跟踪到这里？我突然有种很不祥的预感……'),
(9298,2,0,'zhCN','保持警戒！'),
(9298,3,0,'zhCN','请跟我来。'),
(9298,4,0,'zhCN','我还没真正搞清楚那是什么，但这温泉有点不对劲……'),
(9298,5,0,'zhCN','%s把剑抛入浅池中。'),
(9298,6,0,'zhCN','我发现，把东西扔进这水里，捞上来时竟会不可思议地变好。'),
(9298,7,0,'zhCN','管它是什么呢，反正效果相当不错！'),
(9298,8,0,'zhCN','而我决心弄清更多……所以若你还需要我帮忙，知道上哪儿找我。'),
