(12018,2,1,'zhCN','烧吧，凡人！为这僭越之举而燃烧吧！'),
(12018,7,0,'zhCN','鲁莽之徒，你竟来夺取永恒之焰的秘密！你很快会为这草率的行径后悔。'),
(12018,8,0,'zhCN','我现在去召唤这座府邸的主人。若你执意要面见他，你那卑微的性命必被没收！不过，若你胆敢，尽管去寻他的巢穴！'),
(12018,9,0,'zhCN','很好，$n'),
(12018,10,0,'zhCN','放肆的雏龙！你们''''一头撞向自己的死路！看，主人动了！'),
(12018,11,0,'zhCN','我的火焰……求求你，别夺走我的火焰……'),
(12057,0,0,'zhCN','%s迫使他的一名火焰誓约随从喷发！'),
(12137,0,0,'zhCN','飞往幽暗城的飞艇刚刚抵达！前往提瑞斯法林地的旅客请登艇！'),
(12178,0,0,'zhCN','%s的死亡哀嚎惊动了附近的其拉虫巢！'),
(12179,0,0,'zhCN','%s的死亡哀嚎惊动了附近的其拉虫巢！'),
(12265,0,0,'zhCN','%s分裂成两只新的熔岩之子！'),
(12319,0,0,'zhCN','你最后一次阻挠我们的计划了，愚蠢的$c！'),
(12321,0,0,'zhCN','你最后一次阻挠我们的计划了，愚蠢的$c！'),
(12337,1,0,'zhCN','刺客！卫兵！卫兵！'),
(12347,0,0,'zhCN','%s变得狂暴！'),
(12384,0,0,'zhCN','你到哪儿都找不到更便宜的价钱！'),
(12384,0,1,'zhCN','我是奥古斯都，我的价钱疯狂到家了！'),
(12384,0,2,'zhCN','我是奥古斯都！你要的我有！你想卖的，我也收！'),
(12802,0,0,'zhCN','%s变得狂暴！'),
(12803,0,0,'zhCN','%s陷入狂乱！'),
(12807,0,0,'zhCN','看下面那娘们！她以为她是谁啊？'),
(12818,0,0,'zhCN','好啦$n，我们出发！'),
(12818,1,0,'zhCN','谢谢你救了我。去碎木哨岗找我妹妹。我……我得找个地方歇息……'),
(12858,5,0,'zhCN','为了部落！'),
(12858,6,0,'zhCN','稳住，弟兄们。我们很快就要出征了。'),
(12858,6,1,'zhCN','运气好的话，今天能添几道漂亮伤疤。'),
(12858,6,2,'zhCN','这片林子让我的獠牙发痒……'),
(12858,6,3,'zhCN','他们说杜瑞尔是个凶悍的暗夜精灵。会是一场恶战！'),
(12858,6,4,'zhCN','打完这仗，咱们就该在斧上刻记功了。'),
(12858,6,5,'zhCN','冷静点，弟兄们。可别暴露了我们的位置。'),
(12860,0,0,'zhCN','谁敢袭击银翼哨站？！？'),
(12938,0,0,'zhCN','我得救了！谢谢你，医生！'),
(12997,1,0,'zhCN','老鼠泛滥成灾！帮帮海盗吧，老兄！'),
(12997,1,1,'zhCN','别挤着我，弟兄们！'),
(12997,1,2,'zhCN','为保持深铁地铁的整洁出份力吧！'),
(13716,7,0,'zhCN','我的权杖将再度完整！'),
(13716,8,0,'zhCN','也许我们稍后可以再试。若你愿意，请再来与我交谈。'),
(13996,0,0,'zhCN','跑！他们来了！'),
(14041,0,0,'zhCN','给点零钱？'),
(14041,0,1,'zhCN','我曾拥有一切！拥有一切，然后失去了。失去……全没了……就像……我的理智。我的理智就像……奶酪。我喜欢奶酪。'),
(14041,0,2,'zhCN','四十二……四十二……四十二什么？可能是任何东西！四十二……嗯……'),
(14041,0,3,'zhCN','烤老鼠串！好吃的烤老鼠串这儿有！趁热来买！'),
(14041,0,4,'zhCN','到处是老鼠。我到哪儿都能看见老鼠。老是拿它们那对小眼睛盯着我。我要给它们点颜色看看。给它们全体点颜色看看！'),
(14041,1,0,'zhCN','%s打着哈欠。'),
(14041,2,0,'zhCN','%s翻捡着垃圾。'),
(14101,0,0,'zhCN','%s陷入狂乱！'),
(14225,0,0,'zhCN','%s变得狂暴！'),
(14267,1,0,'zhCN','%s变得狂暴！'),
(14304,1,0,'zhCN','%s变得狂暴！'),
(14304,2,0,'zhCN','%s朝$n扔了一个烂苹果。'),
(14304,3,0,'zhCN','%s把烂香蕉丢在$n身上。'),
(14304,4,0,'zhCN','%s朝$n啐了一口。'),
(14304,5,0,'zhCN','怪物！'),
(14304,5,1,'zhCN','杀人犯！'),
(14304,5,2,'zhCN','拿绳子来！'),
(14304,5,3,'zhCN','你竟敢踏入我们的城市！'),
(14304,5,4,'zhCN','你让我恶心。'),
(14304,5,5,'zhCN','看来我们要在这儿处决人了。'),
(14304,5,6,'zhCN','叛徒走狗。'),
(14304,5,7,'zhCN','我的家人被天灾军团灭门了！怪物！'),
(14344,0,0,'zhCN','%s变得狂暴！'),
(14392,2,0,'zhCN','奈法利安已被斩杀！奥格瑞玛的同胞们，在$n与$g 他:她; 盟友的威能面前俯首吧，因为他们重创了黑龙军团，这一击必能将沉睡的巨龙之首惊醒！今日，黑龙之父——死亡之翼——定能感到这败绩带来的痛楚与煎熬！'),
(14392,3,0,'zhCN','为$n的功绩而振奋吧！沉浸于$g 他:她; 的集结呐喊中！'),
(14394,0,0,'zhCN','暴风城的市民与盟友们，就在今日，历史被书写。$n摧毁了那妄图篡夺王国统治的存在。围拢过来，与我一同向我们的英雄致敬。'),
(14394,1,0,'zhCN','见证联盟的威能吧！那可怖的女士奥妮克希亚，已悬于拱梁之上！让屠龙者的集结呐喊振奋你们的心灵！'),
(14452,0,0,'zhCN','若我日被召遣，必需献祭，凡人……'),
(14459,0,0,'zhCN','%s在宝珠的控制力被抽干时逃窜。'),
(14469,3,0,'zhCN','就是现在了，因普西。我感觉到了！这一回是大动作！'),
(14469,3,1,'zhCN','做好准备迎接那辉煌的冲击吧，因普西！'),
(14469,3,2,'zhCN','他们敢赶我走！？我要让暴风城那些死板的尖脑袋见识见识尼比的真正力量！看好了！'),
(14469,4,0,'zhCN','%s懊恼地挥舞着拳头。'),
(14469,5,0,'zhCN','你这小……！'),
(14470,2,0,'zhCN','尼比，你真蠢。'),
(14470,2,1,'zhCN','哎呀，真意外！又失败了！？可是怎么会呢，伟大的主人？？'),
(14470,2,2,'zhCN','令人叹为观止，主人。您的无能同样令人叹为观止。'),
(14470,3,0,'zhCN','啊！救命！有个疯侏儒要杀我！'),
(14491,0,0,'zhCN','%s变得狂暴！'),
(14497,0,0,'zhCN','你们这些可怜的孩子真让人心酸。'),
(14497,0,1,'zhCN','孩子们，快停下！我是说真的！'),
(14497,0,2,'zhCN','一切都会好起来的，孩子们。圣光会眷顾的！'),
(14497,0,3,'zhCN','我相信你们孩子就是我们的未来……'),
(14498,0,0,'zhCN','你们现在归我了，孩子们。你们将成长为部落坚强的力量！'),
(14498,0,1,'zhCN','别哼唧了！'),
(14498,0,2,'zhCN','把这儿打扫干净！我们可不住这种猪窝。'),
(14498,0,3,'zhCN','要么听我的，要么滚去金之路。听懂没？'),
(14509,2,0,'zhCN','%s死亡。'),
(14510,4,0,'zhCN','族群不会覆灭！'),
(14517,3,0,'zhCN','%s发出一声震耳欲聋的尖啸！'),
(14517,4,0,'zhCN','%s开始施放强效治疗术！'),
(14523,0,0,'zhCN','你这狗东西！现在我要把你的灵魂封进碎片，给我的小鬼当玩物！'),
(14566,0,0,'zhCN','%s伴随着一声惊雷般的巨响，挣脱了幽灵的束缚！'),
(14635,0,0,'zhCN','我们的皮拉斯！有人偷走了我们的皮拉斯！'),
(14635,1,0,'zhCN','我们不会让这疯狂行径逃脱惩罚！'),
(14636,0,0,'zhCN','贼！无赖！恶棍！来当面见我，巨大的皮拉斯！'),
(14682,0,0,'zhCN','%s陷入狂乱！'),
(14686,0,0,'zhCN','谢谢你成为我的下一个牺牲品！'),
(14721,1,0,'zhCN','让你们的精神高昂！簇拥你们的勇士，沐浴在$G 他:她; 的荣光中！沉醉于屠龙者的集结呐喊！'),
(14748,0,0,'zhCN','又一个蠢货落入陷阱！'),
(14748,0,1,'zhCN','晚餐到了！'),
(14748,0,2,'zhCN','高阶女祭司将把你的骨头当美餐！'),
(14757,0,0,'zhCN','终于，我自由了！我很快就能回家了，亲爱的！'),
(14834,4,0,'zhCN','你对我们古拉巴什帝国至高威权的冷漠无视，已被记下。祖尔格拉布的居民已被告知你的到来。'),
(14834,5,0,'zhCN','向哈卡宣誓效忠，你所受的痛苦便会减到最低。'),
(14834,6,0,'zhCN','在我的统治之下，世界将遭受无法估量的残暴。'),
(14834,7,0,'zhCN','逃跑对你们没用，凡人！'),
(14850,0,0,'zhCN','先生，您还想再吃点什么吗？'),
(14850,1,0,'zhCN','马上就来，先生。'),
(14850,2,0,'zhCN','您的面包，先生。'),
(14850,3,0,'zhCN','遵您所愿，先生。'),
(14857,0,0,'zhCN','嗯……我的鱼钩呢？哦，在那儿。'),
(14857,1,0,'zhCN','看看鱼咬不咬钩。'),
(14857,2,0,'zhCN','嗯……我想我需要更好的饵。我去看看我父亲的马车。'),
(14857,3,0,'zhCN','野猪人碎料！这个应该管用。鱼最爱野猪人。'),
(14857,4,0,'zhCN','钓到了一条！我去看看有没有卫兵饿了。走啊，尖牙！'),
(14857,5,0,'zhCN','我钓到一条鱼，要是你饿了……'),
(14857,6,0,'zhCN','祖格祖格！很高兴能帮上忙！'),
(14859,0,0,'zhCN','再来点面包，小子！'),
(14859,1,0,'zhCN','啊……很好。现在滚吧！'),
(14871,0,0,'zhCN','嗨，贾布贾布。我想你！'),
(14871,1,0,'zhCN','贾布贾布？你在哪儿，贾布贾布？噢不！你这次又跑哪儿去了！'),
(14872,0,0,'zhCN','救命！一群蜜蜂在追我！'),
(14872,1,0,'zhCN','我跑得累死了，可这些蜜蜂就是不放过我！'),
(14872,2,0,'zhCN','我都不知道蜜蜂不喜欢火！'),
(14872,3,0,'zhCN','卡鲁，你能帮我把这些蜜蜂弄走吗？它们蜇人！'),
(14874,0,0,'zhCN','特洛克，你饿不饿？我在做点吃的给我们！'),
(14874,1,0,'zhCN','给你的吃的，特洛克！特洛克？你怎么像受惊的人类一样乱跑？'),
(14874,2,0,'zhCN','随你便，看来你也没那么饿。下次你自己做吃的吧！'),
(14874,3,0,'zhCN','好吃。我爱吃烤平原陆行鸟。'),
(14874,4,0,'zhCN','不知道那些猪饿不饿……'),
(14874,5,0,'zhCN','小猪猪们饿不饿？我有些吃的给你们……'),
(14874,6,0,'zhCN','看来你们是饿了！特洛克本该早些喂你们的……他这段时间都在干啥？'),
(14874,7,0,'zhCN','我们的猪怎么了？'),
(14893,0,0,'zhCN','这一钓真是漂亮！你为部落带来了荣耀，小子，我们感谢你！'),
(14908,0,0,'zhCN','我要去练武，成为像我父亲一样的战士！'),
(14908,1,0,'zhCN','现在去找一只毫无防备的鹰身女妖！'),
(14908,2,0,'zhCN','有一只！为了部落！'),
(14908,3,0,'zhCN','吃我一招，你这脏兮兮的鹰身女妖！嚇！'),
(14908,4,0,'zhCN','你逃不过部落战士的手！吃这招！还有这招！'),
(14908,5,0,'zhCN','现在回你该回的家去吧！'),
(14908,6,0,'zhCN','啊啊……部落又一场辉煌的胜利！'),
(14908,7,0,'zhCN','是，马上，妈妈！'),
(14908,8,0,'zhCN','爸爸什么时候才能从战歌的战事里回来？已经过去好久了……'),
(14909,0,0,'zhCN','莫格，进屋去。你父亲不在，外面不安全。'),
(14909,1,0,'zhCN','快了，孩子……很快了。'),
(15041,0,0,'zhCN','%s已经完全长成了！'),
(15076,0,0,'zhCN','血神，噬魂者，已被击败！我们不再危在旦夕！'),
(15111,0,0,'zhCN','我要把你们变成魔精！'),
(15111,0,1,'zhCN','巨魔魔精才是最强的魔精！'),
(15180,0,0,'zhCN','%s不自在地挪动了一下。'),
(15180,1,0,'zhCN','时机成熟时自会分明，我的女士。当时间对了，一切将水落石出。主人此刻已在躁动。仰望天空吧，诺兹多姆的龙群已经归来。'),
(15183,0,0,'zhCN','我会尽力翻译并描述我所见到的。'),
(15183,1,0,'zhCN','这是历史……是关于希利苏斯的历史……是关于安其拉的历史……是关于泰坦与古神的历史……我念的是克苏恩的预言，由其拉先知斯克拉姆所书。一则预示大灾变的预言……'),
(15183,2,0,'zhCN','在时间诞生之前，当世界尚在襁褓，一场泰坦与不可名状之邪恶巨力的战斗在这片土地上肆虐。预言并未言明那泰坦是否在此战中陨落，却表明有一位泰坦倒下了。一位古神也随之倒下——至少当时人们如此认为。'),
(15183,3,0,'zhCN','数千年来，这存在沉眠于世界之下——静待时机。它在囚笼中等待那个精准的时机，向那些欲加害于它的存在复仇。'),
(15183,4,0,'zhCN','永恒星光之地卡利姆多，是万千生灵的慈母。永恒之井的魔力浸润大地，赋予那无数以世界为家的草木与走兽以力量。从这魔法的以太中，诞生了其拉虫人。正是借由虫人，那蛰伏的古神才得以触及、并试图撕裂它曾无情掌控的世界。'),
(15183,5,0,'zhCN','古神以虫人为模，依己之形象造出化身。这些化身被称为其拉虫人。它们有觉知、有目的，便为造物主命名：克苏恩由此诞生……数千年来，其拉虫人狂热地打造一支能摧毁那背叛其神之世界的力量。伟大的堡垒之城安其拉，便是为容纳日益壮大的军队、并为克苏恩的降临做准备而建。'),
(15183,6,0,'zhCN','这不可能对。绝不容许古神踏入这个世界。后果将是……噢天哪！'),
(15183,7,0,'zhCN','%s重新镇定下来。'),
(15183,8,0,'zhCN','还有更多。'),
(15183,9,0,'zhCN','克苏恩耐心等待的时刻终于到来。他的子嗣耗费数千年，打造出一支能向整个卡利姆多复仇的军队，如今战利品已近在咫尺。'),
(15183,10,0,'zhCN','泰坦早已撤离这个世界。唯有曾居于此地的暗夜精灵留在这里防守。噢我的！下一段真是引人入胜！'),
(15183,11,0,'zhCN','一位名为拉贾克斯将军的强大其拉虫人将指挥首次入侵希利苏斯。唯有一人挡在他面前：一位名为鹿盔的暗夜精灵。在其拉本族语中，他被称为''卡西斯''，意为''大地之手''。'),
(15183,12,0,'zhCN','随着拉贾克斯的部队源源不断涌入希利苏斯，鹿盔和他的军队显然寡不敌众。然而，鹿盔对虫人而言似乎不只是个麻烦。在他的统领下，暗夜精灵大军集结一处，守护卡利姆多，大大拖慢了虫人的步伐。'),
(15183,13,0,'zhCN','遗憾的是，暗夜精灵的防线难以为继，拉贾克斯也清楚他们撑不了多久。然而他们的顽强让拉贾克斯大为光火，更让其国王怒不可遏。等等，国王？难以置信……'),
(15183,14,0,'zhCN','维克尼拉斯与维克洛尔，即安其拉的双子皇帝，在神庙的圣所中观战。这对聪明的兄弟谋划了一条计策，意图瓦解并分化鹿盔的部队。'),
(15183,15,0,'zhCN','瓦尔斯塔恩·鹿盔是范达尔的得力助手。一名骄傲而高贵的战士，对父亲矢志不渝、爱戴至深……而双子皇帝将此视为弱点。一个可被利用的弱点。'),
(15183,16,0,'zhCN','其拉军队奉命后撤，将主力藏入沙漠黄沙之下。在鹿盔军队前线被牵制之际，一支小股部队奉命突袭南风村。'),
(15183,17,0,'zhCN','瓦尔斯塔恩急于取悦父亲，说服范达尔让他带一小队前去驰援南风村。既然战局正转向他们，爱子定然无恙。他们没看出这是个陷阱。瓦尔斯塔恩被埋伏的其拉虫人擒获，南风村被夷为平地。拉贾克斯亲自将俘虏瓦尔斯塔恩押至前线，在鹿盔与暗夜精灵军队面前，残忍地处决了这名年轻的暗夜精灵。'),
(15183,18,0,'zhCN','战争仍在继续，但那位伟大领袖的意志已被抽空。整个希利苏斯很快被其拉虫人与其虫人宿主吞没。'),
(15183,19,0,'zhCN','可怜的人，这倒解开了许多谜团。'),
(15183,20,0,'zhCN','暗夜精灵军队被击退，穿过安戈洛，退至塔纳利斯沙漠边缘。安戈洛中的某种力量阻止了其拉虫人占据那片土地。我不太懂这个词，但我想它的意思是''神之之地''。书上说他们无法''攻占神之之地''。'),
(15183,21,0,'zhCN','有趣，这与''安戈洛曾是泰坦栖居卡利姆多时的家园''之假说相吻合。或许阿曼苏尔本人曾守护着''神之之地''。'),
(15183,22,0,'zhCN','嗯，奇怪……这里戛然而止。在塔纳利斯，其拉虫人的记载中面对着一条青铜龙。其中遗漏甚多……必须找到更多信息！他们定是在谋划再次入侵卡利姆多！'),
(15189,0,0,'zhCN','你向来是家里的捣蛋鬼，诺格尔。一直都是！'),
(15190,0,0,'zhCN','是的！我好了！我好……哇，起得太猛了！'),
(15190,1,0,'zhCN','谢谢你找到我的药剂！*打哈欠* 那毒药让我……有点累……'),
(15190,2,0,'zhCN','什……我在哪儿？好……虚弱……'),
(15203,0,1,'zhCN','你竟敢！岂有此理！我诅咒你，$c。我用……死亡诅咒你！'),
(15203,0,2,'zhCN','什么？如此渺小脆弱的东西竟在召唤我？我要把你的骨头添到我的王座上，$r！！'),
(15203,0,3,'zhCN','杀死你和你的同伙，$c，会让我开心。我会速战速决。'),
