(15692,0,2,'zhCN','这些旱鸭子是冲着驯鹿来的！给他们点厉害看看！'),
(15692,0,3,'zhCN','这是一次营救行动！别放跑任何人！'),
(15692,0,4,'zhCN','让我替大父亲冬代表达一下问候，渣滓……'),
(15692,0,5,'zhCN','胡说！死吧！'),
(15692,0,6,'zhCN','这是一次营救行动！把他们全宰了！'),
(15692,0,7,'zhCN','这个冬幕节，梅岑唯一要做的就是被架在火上烤！'),
(15745,8,0,'zhCN','给每个人的礼物！冬父亲已在树下为所有人放好了礼物。'),
