(15953,6,2,'zhCN','趁还来得及，快逃吧！'),
(15954,4,0,'zhCN','%s召唤出骷髅战士！'),
(15954,5,0,'zhCN','%s又召起了更多骷髅！'),
(15954,6,0,'zhCN','%s传送到了上方的阳台！'),
(15954,7,0,'zhCN','%s传送回到了战斗中！'),
(15954,8,0,'zhCN','%s闪现离开！'),
(15956,3,0,'zhCN','阿努布雷坎开始释放虫群！'),
(15963,0,0,'zhCN','密室中央那颗巨大的漂浮眼球将目光投向你。你正站在一尊神祇面前。'),
(15990,16,0,'zhCN','谁敢亵渎我领域的圣洁？听着，所有擅闯此处者皆注定灭亡。'),
(15990,17,0,'zhCN','蠢货！你以为自己胜利了？你不过朝深渊又近了一步！'),
(15990,18,0,'zhCN','我厌倦了这些把戏。继续前行，我便将你们的灵魂放逐于虚无！'),
(15990,19,0,'zhCN','你根本想象不到前方有何等恐怖。你什么都还没见到！纳克萨玛斯的冰封之心正等待着你！'),
(15990,20,0,'zhCN','来吧，英雄们……凭巫妖王的意志，你们必被毁灭。'),
(16042,1,0,'zhCN','你的狂妄令人发指，蠢货！我要拿你的灵魂饱餐一顿！'),
(16042,2,0,'zhCN','迄今为止我对你们手下留情，如今你们却让我厌倦。见证我力量的恢弘，然后绝望吧！'),
(16042,3,0,'zhCN','我不会再死一次！绝不会死在你们手里！'),
(16059,0,0,'zhCN','我要把你那丑脑袋踢爆！'),
(16059,0,1,'zhCN','想打架？那就让你打个够！'),
(16059,0,2,'zhCN','我每天都能捏碎你这样的弱者！放马过来！'),
(16060,4,0,'zhCN','我等得够久了。现在，你面对的是灵魂的收割者。'),
(16060,5,0,'zhCN','我……被……瓦解了。'),
(16060,6,0,'zhCN','死亡才是唯一的出路！'),
(16060,7,0,'zhCN','%s传送进入了战团！'),
(16060,8,0,'zhCN','中央大门开启！'),
(16061,0,0,'zhCN','照我教的做！'),
(16061,0,1,'zhCN','练习的时间结束了！让我看看你学到了什么！'),
(16061,0,2,'zhCN','对他们绝不留情！'),
(16061,0,3,'zhCN','扫他的腿……你有意见？'),
(16061,1,0,'zhCN','%s发出一声胜利的呐喊。'),
(16061,1,1,'zhCN','你本该待在家里的。'),
(16061,2,0,'zhCN','哈哈，我这才刚热身呢！'),
(16061,2,1,'zhCN','站住，战斗！'),
(16061,2,2,'zhCN','让我看看你的本事！'),
(16061,2,3,'zhCN','你们让我失望了，学生们！'),
(16061,2,4,'zhCN','你本该待在家里的。'),
(16061,3,0,'zhCN','光荣的……死亡。'),
(16061,4,0,'zhCN','可悲……'),
(16061,5,0,'zhCN','趁我把那练习假人换成你、自己开始热身之前，赶紧动点真格的！'),
(16062,0,0,'zhCN','雷诺……'),
(16062,1,0,'zhCN','你以为你的背叛会被遗忘？会淹没在我之死那精心策划的掩盖之中？吾之血脉，那剑在我心脏停止跳动后许久仍感受着你的残忍。而在死亡中，我知晓了你所行之事。但如今，克尔苏加德的锁链再也无法束缚我。我为伸张正义而来。吾乃灰烬使者。'),
(16062,2,0,'zhCN','你被宽恕了……'),
(16063,5,0,'zhCN','入侵者，立刻停止这愚蠢的举动！趁还来得及，回头是岸！'),
(16063,6,0,'zhCN','或许他们会醒悟过来……然后拼命逃走。'),
(16063,7,0,'zhCN','%s向所有人施放谴责！'),
(16064,5,0,'zhCN','抄家伙，伙计们！有客人来了！'),
(16064,6,0,'zhCN','你们的哭哭啼啼我听得够够的了！在我替你闭嘴之前，自己把嘴闭上！'),
(16065,5,0,'zhCN','来吧，泽里克，别把他们赶走。咱们还没玩够呢！'),
(16065,6,0,'zhCN','我着实希望他们能活得久一点，好让我……自我介绍一下。'),
(16065,7,0,'zhCN','%s向所有人施放不屈之痛！'),
(16080,0,0,'zhCN','自然的一切伟力皆听我调遣，渺小的凡人。让我们看看，我众多形态中的哪一种，将终结你们的苦痛！'),
(16080,1,0,'zhCN','虽然我安然离去，但我对你们永怀感激。谢谢你们将我从愚昧与贪婪的诅咒中解救。'),
(16097,0,0,'zhCN','我的折磨结束了，如今我能归于女神之怀。太感谢你们了！'),
(16101,0,0,'zhCN','你好，兄弟。'),
(16101,1,0,'zhCN','只怕是些不速之客。'),
(16101,2,0,'zhCN','是的，我们会的！'),
(16101,3,0,'zhCN','%s在看到$n战死沙场后陷入暴怒！'),
(16102,0,0,'zhCN','你好，妹妹。我们这儿有什么？'),
(16102,1,0,'zhCN','要不要宰了他们，罚他们惊扰我们安眠的无礼？'),
(16102,2,0,'zhCN','%s在看到$n战死沙场后陷入暴怒！'),
(16103,0,0,'zhCN','谢谢你救了我，我的兄弟，还有你们所有人！我们终于能安息了。'),
(16104,0,0,'zhCN','谢谢你救了我，我的妹妹，还有你们所有人！我们终于能安息了。'),
(16113,0,0,'zhCN','谢谢你，钱伯斯夫人。'),
(16113,1,0,'zhCN','这是芒果吗？太棒了！'),
(16113,2,0,'zhCN','钱伯斯夫人，你这次真是超水平发挥。一点霉斑都找不到！'),
(16114,0,0,'zhCN','指挥官，你的口信确实传到了我们这里，但我们的介入绝未得到大十字军的批准。'),
(16114,1,0,'zhCN','异教徒将被迫回应。兽人，牛头人……'),
(16114,2,0,'zhCN','管他呢。那群令人作呕、不修边幅的部落渣滓……'),
(16114,3,0,'zhCN','太少了，也太晚了。堤坝已决。我们充其量只是路上一块绊脚石。'),
(16114,4,0,'zhCN','总还有……灰烬使者。'),
(16114,5,0,'zhCN','谢谢你，杰西卡。'),
(16114,6,0,'zhCN','而且我得说，那件裙子真美！你一定要告诉我是在哪儿买的。'),
(16115,0,0,'zhCN','你们的领袖驻于纳克萨玛斯的门槛之前。你以为他感受不到压力？'),
(16115,1,0,'zhCN','%s压低声音，成了耳语。'),
(16115,2,0,'zhCN','即便是恶魔，也会恐惧……'),
(16115,3,0,'zhCN','瘟疫之地的天灾活动增至十倍。我们收到来自远至卡利姆多的天灾袭击报告！你说说，这怎么可能？这些可悲的不死族是如何做到那原被认为不可能之事的？难道没有安全之地了吗？'),
(16115,4,0,'zhCN','牛头人。'),
(16115,5,0,'zhCN','指挥官，你缺乏圆滑，这并不意外。不过你说得对，部落将被迫行动。但不仅限于部落。他们已经来了——来自世界各地的英雄。'),
(16115,6,0,'zhCN','那你为何来此？若毫无希望，我们又能做什么？'),
(16115,7,0,'zhCN','所以你为此而来？企图夺取那既是黎明之刃存在之因、亦是十字军覆灭之由的物件？指挥官，你的话撕开了旧伤！'),
(16115,8,0,'zhCN','灰烬使者已死，再不会有第二个他。那不成器的莫格莱恩与他父亲相比，判若云泥。你心知肚明，指挥官！毕竟，正是你的指挥导致了红衣领主莫格莱恩的死亡。'),
(16115,9,0,'zhCN','正是你的指挥，操纵一个悲恸的孩子去试图夺回那把剑。那孩子已长成心中只有复仇与仇恨的男人！图什么？如今你离那把剑，并不比五年前更近。'),
(16115,10,0,'zhCN','然而你以为夺回灰烬使者便能扭转战局？让我告诉你一个小秘密，指挥官：灰烬使者的力量，来自执剑之人……我当时在场，指挥官。我见过他在出鞘之前，便以正义之火焚烧了成群的亡灵。唉，你对历史的理解……着实欠缺。'),
(16115,11,0,'zhCN','现在闭嘴，认清你身处何地，免得我去告知福德林领主及其骑士，你已不再是以友好之姿到此。'),
(16115,12,0,'zhCN','这鱼真是鲜美，杰西卡。'),
(16115,13,0,'zhCN','向厨师致以我的敬意！'),
(16115,14,0,'zhCN','美味！'),
(16116,0,0,'zhCN','噢，相当多汁。多谢，钱伯斯夫人。'),
(16116,1,0,'zhCN','这野猪肉棒极了！'),
(16116,2,0,'zhCN','确实……裙子真美，杰西卡。'),
(16118,0,0,'zhCN','你以为你能召唤我们？召唤者是我们，不是你！为此我们要好好砸扁你，吸干你的骨髓！'),
(16118,1,0,'zhCN','你这么小这么弱……不配做科尔莫克的仆人！'),
(16118,2,0,'zhCN','%s变得狂暴！'),
(16118,3,0,'zhCN','我们自由了！谢谢你们这些小不点。'),
(16134,0,0,'zhCN','看哪，德鲁伊。大地仍在呼吸。它渴望被净化。'),
(16135,0,0,'zhCN','那真是奇妙，林布拉特！即便这片污浊破碎的大地，也非无可救药。'),
(16144,0,0,'zhCN','如你所言，亲爱的，如你所言。'),
(16144,0,1,'zhCN','嗯，你说什么？抱歉亲爱的，我方才一定是在做白日梦。'),
(16144,0,2,'zhCN','噢，当然，埃莉萨拉。但请你，能不能稍有点耐心？'),
(16144,0,3,'zhCN','是吗？真有意思。亲爱的，你何不先去补个妆？我有许多事要思量。'),
(16147,0,0,'zhCN','我方才在想……我们真该挑个夜晚往南去一趟，或许在边境的战事上方来场晚间野餐？你觉得如何，大人？那岂不是很有趣？'),
(16147,0,1,'zhCN','大人，既然辛多雷的贵族多半已不幸倾覆，是否意味着您很快便有望晋升？我真是为您高兴！'),
(16147,0,2,'zhCN','大人，您觉得我们很快能加入那场宴会吗？在这里头我好无聊。'),
(16147,0,3,'zhCN','噢，我的大人，我着实希望您已备好更多银月城那种美酒。我敢说，喝它让我觉得自己简直像个寻常女子般放肆！'),
(16147,0,4,'zhCN','我好累。我们真不该昨晚……呃，今早熬到那么晚。不过真开心！大人，你办的晚会总是最棒的。'),
(16147,0,5,'zhCN','萨尔塞里尔大人，亲爱的，你有没有注意到宴会的补给有点不够？我们真该派人去微风村叫个信使，把缺的东西多送些来。我特别喜欢那种裹着烟熏培根的小点心。那叫什么来着？'),
(16147,0,6,'zhCN','萨尔西，你觉得我们是不是让太多''不受欢迎的人''进了宴会？我着实担心朋友们会怎么看这一切。'),
(16147,0,7,'zhCN','你答应带我出去逛夜城的！今晚我们又只是站在这儿发呆吗？'),
(16151,1,0,'zhCN','%s冲去援助她的主人。'),
(16152,0,1,'zhCN','又一件战利品，添到我的收藏里！'),
(16152,2,0,'zhCN','武器对我这等身手的战士来说，不过是锦上添花！'),
(16204,0,0,'zhCN','凯恩德里斯为何还不对达尔坎动手？我们在等什么？'),
(16213,0,0,'zhCN','%s不耐烦地跺着脚。'),
(16213,0,1,'zhCN','%s怒视着卫兵。'),
(16213,0,2,'zhCN','%s明显懊恼地叹了口气。'),
(16213,0,3,'zhCN','%s朝塔里窥探，随后咬紧了牙关。'),
(16217,0,0,'zhCN','吃这一下！'),
(16217,0,1,'zhCN','这里不是银月城！我们这是在哪？噢，我刚才一时糊涂了。'),
(16217,0,2,'zhCN','我现在就告诉你，等回到远行者居所，定要就你的所作所为好好算账，瓦兰娜游侠！损失全是你一人之过，我确信队长会站在我这边。'),
(16217,0,3,'zhCN','我们回去后我定能受褒奖。虽有些许损失，但总体而言我们干得不错，你不觉得吗，瓦兰娜？'),
(16217,0,4,'zhCN','难道我没冲他们喊吗？后撤！后撤并以压制火力重整阵型！！'),
(16217,0,5,'zhCN','他们本该听我的。那样我就能得到所有本属于我的赞誉！'),
(16218,0,0,'zhCN','%s失去了链接！'),
(16218,1,0,'zhCN','%s过载了！'),
(16219,0,0,'zhCN','你准是我见过最不称职的军官！'),
(16219,0,1,'zhCN','再提醒我一次，我为什么不直接走人？'),
(16219,0,2,'zhCN','嗯哼。随你怎么说。'),
(16219,0,3,'zhCN','白痴。'),
(16219,0,4,'zhCN','你能不能闭嘴？！'),
(16219,0,5,'zhCN','恕我直言，长官，去你的！'),
(16222,2,0,'zhCN','即便是圣光，也比不过我们人民不可屈服的意志。'),
(16222,3,0,'zhCN','你的力量令我们全体强盛。'),
(16231,0,0,'zhCN','%s对顾问所言点头称是。'),
(16231,0,1,'zhCN','%s对瓦尔温在她耳边低语的那些话不以为然。'),
(16231,0,2,'zhCN','%s对顾问在她耳边低语的内容似乎无动于衷。'),
(16231,1,0,'zhCN','执行官，你正面强攻的打法会让我们的伤亡超出我能接受的范围。我们需要更细致的策略——先收复周边领土，从村庄入手，从而切断通往死亡之帽的所有增援路线。'),
(16231,2,0,'zhCN','马夫伦，你的话我听进去了。但最后的决定权在我。我感谢你的协助，可被置于险境的多数是血精灵的性命。我绝不容许那些生命被草率葬送！'),
(16231,3,0,'zhCN','被遗忘者的援军还要多久才到？我们在此的阵地岌岌可危。你们的女士答应给我们更多士兵。我们必须能全力专注于死亡之帽与天灾！'),
(16231,4,0,'zhCN','马夫伦，我不要借口，我要结果！远行者抽不开身，而我们从银月城能得到的东西也都到手了。我无法无视暗针巨魔与祖阿曼……它们正陈兵于我们的东境！'),
(16231,5,0,'zhCN','不，我一开始就是对的。死亡之帽必须放在最后。我们必须先稳住整个幽魂之地。我绝不会在侧翼与背后皆有敌的情况下，把这里的兵力投入对抗达尔坎的战斗！'),
(16231,6,0,'zhCN','随你怎样反对，大执行官。我会斟酌你的谏言，然后按我认为必要的方式，迈出解放整个奎尔萨拉斯的步伐。我们稍后再续此议。'),
(16237,0,0,'zhCN','当心……暗夜精灵回来了！'),
(16240,0,0,'zhCN','冷静点，伊多尼斯。鲁莽行事只会一事无成！歇一会儿，汲取些法力水晶。你会好起来的。'),
(16240,0,1,'zhCN','他有他的理由，伊多尼斯。他认为远行者发现了什么。'),
(16240,0,2,'zhCN','我们必须专心手头的工作。一旦圣所全负荷运转，银月城便会被迫遣援。能正常运作的奥术圣所可是稀缺得很。'),
(16251,0,0,'zhCN','%s点头表示同意。'),
(16251,0,1,'zhCN','%s张开嘴似要补充什么，随后显然改变了主意。'),
(16251,0,2,'zhCN','%s面带得意地看向顾问瓦尔温。'),
(16251,0,3,'zhCN','%s对大执行官的话报以咧嘴一笑。'),
(16251,0,4,'zhCN','%s似乎对整场讨论感到厌烦。'),
(16251,0,5,'zhCN','%s向顾问瓦尔温狡黠地眨了眨眼。'),
(16251,0,6,'zhCN','%s不安地摆弄着盔甲，显然对讨论的语气感到不自在。'),
(16251,0,7,'zhCN','%s看起来宁可身在别处，也不愿在此。'),
(16251,1,0,'zhCN','%s转向顾问瓦尔温，朝她暧昧地眨了眨眼。'),
(16252,0,0,'zhCN','恕我直言，小姐，您不像我这样与天灾交过手。女士正是为此才派我来助您击败达尔坎，您最好听听我的话。'),
(16252,0,1,'zhCN','我强烈反对。达尔坎得不到增援，因为他会被卡死。死亡之帽只有一条进出之路。你的叛徒蠢到把自己困在那里，而我要利用这弱点！'),
(16252,0,2,'zhCN','这是战争，奥里菲洛斯女士，任何战争都免不了死人！我们只需拿下两座神庙。我们会缩进去，以蛮力夺取诅咒之塔与其主人。到时奎尔萨拉斯便是您的了。'),
(16252,0,3,'zhCN','若你的远行者在此增援，我或许会同意。但他们正忙着对付你们东境的暗针巨魔。我们等得越久，天灾便越强。'),
(16252,1,0,'zhCN','我想你倒是在替我佐证，不过没错，若多有援军自是好事。我倒认为，把远行者从与巨魔那无谓的缠斗中抽离更快。'),
(16252,1,1,'zhCN','奥里菲洛斯女士，我们便是援军。或许女士日后会再派兵来。你不如去说服银月城集结全部兵力，交由我们在此调遣。'),
(16252,1,2,'zhCN','你说得对；我们必须专注于天灾。无视巨魔与村庄，把注意力放在死亡之帽上！达尔坎一败，你会发现天灾其余的''躯体''失了''头'',便会迅速崩垮。'),
(16252,1,3,'zhCN','被遗忘者的援军？幽暗城四面受天灾夹击，已捉襟见肘。不，此事多半要由血精灵来办。我们被遗忘者只是来当后备与顾问的。'),
(16252,2,0,'zhCN','我再次强烈反对你对战略局势的看法。你的计划会让我们的兵力过于分散，只剩一小股力量去进攻死亡之帽。凭良心我无法执行这样的策略。'),
(16252,2,1,'zhCN','兵力散布在幽魂之地，对进攻死亡之帽无甚助益。不，小姐，我是来杀达尔坎的，而我也正要这么做！'),
(16252,2,2,'zhCN','我们以前就说过。唯有集中兵力进攻死亡之帽方能成功。其他目标都是我们负担不起的干扰。我建议你通传你的赫利俄斯队长，叫他停止对暗针巨魔的战事，只专注天灾。'),
(16252,2,3,'zhCN','或许我们该暂且搁下此事，等你家厨子备好膳食？恕我直言，你气色略显不悦。等你精神些，我们再续谈。'),
(16256,0,0,'zhCN','好，指挥官，你的鱼拼盘，请慢用！'),
(16256,1,0,'zhCN','父亲，你吃的是那碗水果，对吧？'),
(16256,2,0,'zhCN','女士们，烤乳猪。请慢用！'),
(16256,3,0,'zhCN','若还需要什么，尽管告诉我！'),
(16289,0,0,'zhCN','%s在女士耳边低语了些什么。'),
(16289,1,0,'zhCN','%s对执行官的语气感到惊骇！'),
(16289,1,1,'zhCN','%s试图让自己忙于别的事。'),
(16289,1,2,'zhCN','%s朝大执行官马夫伦与死亡猎手马尔滕迪丝的方向投去如刀的怒视。'),
(16289,1,3,'zhCN','%s扬起鼻子，回应大执行官的话嗅了嗅。'),
(16289,1,4,'zhCN','%s对从被遗忘者口中听到的话难以置信地摇了摇头。'),
(16289,1,5,'zhCN','%s脸色煞白，仿佛血色尽褪。'),
(16289,1,6,'zhCN','%s听到回应女士问话的内容，顿时涨红了脸。'),
(16289,1,7,'zhCN','%s专注地盯着对面的墙，明显无视着执行官与其助手投来的目光。'),
(16289,2,0,'zhCN','%s对死亡猎手的调情露出厌恶之色。'),
(16309,0,0,'zhCN','%s变得狂暴！'),
(16328,0,0,'zhCN','%s变得狂暴！'),
(16329,0,1,'zhCN','凡人蠢货！死亡之帽的食尸鬼将把你们的残骸当美餐！'),
(16329,0,2,'zhCN','你们的死将是缓慢而痛苦的！'),
(16333,0,0,'zhCN','%s惊恐地试图逃跑！'),
(16394,0,0,'zhCN','什么？这不是纳克萨玛斯！我们不喜欢这地方……毁灭它！'),
(16394,0,1,'zhCN','嗷嗷嗷啊啊！我们冲你来了！'),
(16394,0,2,'zhCN','克尔苏加德让我转告你……死！'),
(16394,0,3,'zhCN','你为何逃？我们要把你的尸体变成天灾。'),
(16394,0,4,'zhCN','别担心，我们会找到你。'),
(16394,0,5,'zhCN','你们是备件！我们要在浮空城造更多天灾。'),
(16394,0,6,'zhCN','哈哈哈，你的卫兵根本不是天灾的对手！'),
(16394,0,7,'zhCN','我们来摧毁你们这些弱小的东西！'),
(16409,1,2,'zhCN','别管我们！让我们清静！'),
(16414,0,3,'zhCN','你竟敢打翻主人的酒！'),
(16414,1,2,'zhCN','你绝不可能活着出去……'),
(16440,0,0,'zhCN','雷诺……'),
(16440,1,0,'zhCN','你以为你的背叛会被遗忘？会淹没在我之死那精心策划的掩盖之中？吾之血脉，那剑在我心脏停止跳动后许久仍感受着你的残忍。而在死亡中，我知晓了你所行之事。但如今，克尔苏加德的锁链再也无法束缚我。我为伸张正义而来。吾乃灰烬使者。'),
(16440,2,0,'zhCN','你被宽恕了……'),
(16441,0,0,'zhCN','%s在看到克尔苏加德倒下后逃窜！'),
(16441,1,0,'zhCN','一名冰冠守卫加入了战斗！'),
(16464,0,0,'zhCN','%s一边将手中的两种混合物调和，一边发出疯狂的咯咯笑声。'),
(16464,1,0,'zhCN','可恶！这血蓟提取物似乎不愿与我的毒药好好融合。但我不会罢休——那些巨魔必须付出代价！或许换个配方？'),
(16502,0,0,'zhCN','噢不！这一瓶要失败了！'),
(16521,0,3,'zhCN','你们一个也别想活着离开这山谷。'),
(16523,1,0,'zhCN','为了卡加斯！为了胜利！'),
(16523,1,1,'zhCN','嘎卡拉玛！'),
(16523,1,2,'zhCN','洛克纳拉什！'),
(16523,1,3,'zhCN','伊利达雷，胜利！'),
(16523,1,4,'zhCN','鲜血即我们的力量！'),
(16523,1,5,'zhCN','这个世界属于我们！'),
(16523,1,6,'zhCN','我们才是真正的部落！'),
(16524,10,0,'zhCN','%s开始将法力引导进一道强力的奥术法术。'),
(16551,0,0,'zhCN','是的，扎娜，是我！你的信号很弱。'),
(16551,1,0,'zhCN','扎娜！呸，我得把这玩意修好！'),
(16573,0,0,'zhCN','%s陷入狂乱！'),
(16573,1,0,'zhCN','一名墓穴守卫加入了战斗！'),
(16573,2,0,'zhCN','尸体甲虫从一名墓穴守卫的尸体中钻出！'),
(16580,0,0,'zhCN','我说我们开火。砍断绳子。'),
(16580,1,0,'zhCN','你砍断了绳子。刀在你手上。'),
(16580,2,0,'zhCN','哼！懦夫。'),
(16580,3,0,'zhCN','你知道吗，我觉得从这儿能打中荣誉堡。'),
(16580,4,0,'zhCN','要是克拉科克将军发现了，会把我们活吞了。别。'),
(16580,5,0,'zhCN','啊！我们可以跟他说哈加什不小心撞上，误发射了！'),
(16580,7,0,'zhCN','%s叹了口气。'),
(16700,1,5,'zhCN','这个世界属于我们！'),
(16700,1,6,'zhCN','我们才是真正的部落！'),
(16700,2,9,'zhCN','我们必须阻止他们的推进！各就各位！'),
(16700,3,0,'zhCN','战士倒下！'),
(16700,3,1,'zhCN','快，换人！'),
(16700,3,2,'zhCN','下一个战士，快上！'),
(16700,3,3,'zhCN','列队！莫克-索拉卡！'),
(16700,3,4,'zhCN','我的支援在哪儿？'),
(16700,3,5,'zhCN','打起精神！'),
(16700,3,6,'zhCN','与敌交战！'),
(16700,3,7,'zhCN','进攻！'),
(16700,3,8,'zhCN','下一个战士，上前！'),
(16700,3,9,'zhCN','加入战斗！阿格拉玛-卡！'),
(16700,4,0,'zhCN','醒醒，我们遭袭了！'),
(16700,4,1,'zhCN','要睡等你自己的时间！'),
(16700,4,2,'zhCN','起来！'),
(16700,4,3,'zhCN','站起来！'),
(16700,4,4,'zhCN','没时间睡了！加入战斗！'),
(16700,5,0,'zhCN','列队碾碎这些蠢货！'),
(16700,5,1,'zhCN','列队！速战速决！'),
(16700,5,2,'zhCN','准备好！应该很快……'),
(16700,5,3,'zhCN','列阵，让入侵者付出代价！'),
(16700,5,4,'zhCN','勿留活口！列队！'),
(16700,5,5,'zhCN','洛克-纳拉什！防守位！'),
(16700,5,6,'zhCN','守住阵线！绝不容他们突破！'),
(16700,5,7,'zhCN','嘎卡拉玛！'),
(16700,5,8,'zhCN','不惜一切代价挡住他们！'),
(16700,5,9,'zhCN','我们必须阻止他们的推进！各就各位！'),
