(16700,9,7,'zhCN','进攻！'),
(16700,9,8,'zhCN','下一个战士，上前！'),
(16700,9,9,'zhCN','加入战斗！阿格拉玛-卡！'),
(16700,10,0,'zhCN','醒醒，我们遭袭了！'),
(16700,10,1,'zhCN','要睡等你自己的时间！'),
(16700,10,2,'zhCN','起来！'),
(16700,10,3,'zhCN','站起来！'),
(16700,10,4,'zhCN','没时间睡了！加入战斗！'),
(16700,11,0,'zhCN','我们要饮他们的血，食他们的骨！'),
(16700,12,0,'zhCN','为恶魔部落效力！'),
(16700,13,0,'zhCN','力量归于恶魔部落！'),
(16700,13,1,'zhCN','打断他们的骨头！'),
(16700,14,0,'zhCN','认清你们的主人，你们这群无用的杂种！'),
(16700,15,0,'zhCN','就凭你们这些弱者，也配威胁我们？我们要把你们吞掉。'),
(16700,16,0,'zhCN','我们要毁灭你。'),
(16781,0,0,'zhCN','部落的火焰永不熄灭！'),
(16781,1,0,'zhCN','我倒想看看联盟怎么来偷我们的圣火。'),
(16781,2,0,'zhCN','部落曾试图偷走我们的火焰。但愿我们礼尚往来。'),
(16781,3,0,'zhCN','联盟的圣火燃得旺盛而纯粹！'),
(16781,4,0,'zhCN','仲夏火焰节正是欢庆夏日的好时节！'),
(16781,5,0,'zhCN','我喜欢仲夏火焰节末尾的烟花表演。'),
(16790,0,0,'zhCN','谢谢你，$N。看来他们会相处得挺好。'),
(16793,0,0,'zhCN','你真是我的好朋友，闪亮。你绝不会离开我的，对吧？'),
(16793,0,1,'zhCN','现在只有你和我了，闪亮。爸爸不会再回家了。'),
(16793,0,2,'zhCN','闪亮，你找到什么好玩的追着跑了吗？我打赌你找到了！'),
(16803,0,0,'zhCN','师父，弟子恳请您因他愚钝而责打他！'),
(16803,0,1,'zhCN','弟子不配，师父！'),
(16803,0,2,'zhCN','弟子一无是处，师父！弟子为他的不足告罪！'),
(16807,7,0,'zhCN','我已经觉得无聊了！'),
(16807,7,1,'zhCN','快点，给我来场真格的战斗！'),
(16807,7,2,'zhCN','我折磨苦工都比这有趣！'),
(16807,7,3,'zhCN','你输了。'),
(16807,7,4,'zhCN','噢，去死吧！'),
(16807,8,0,'zhCN','真是……遗憾。'),
(16808,5,0,'zhCN','懦夫！你们永远别想把我拖入暗影！'),
(16816,0,0,'zhCN','很好。游戏开始吧。'),
(16816,1,0,'zhCN','或许该换个花样了。'),
(16816,1,1,'zhCN','是时候换套剧本了。'),
(16816,1,2,'zhCN','人不可太过自满。'),
(16816,2,0,'zhCN','%s作弊'),
(16816,3,0,'zhCN','让我们看看。'),
(16816,3,1,'zhCN','一个显而易见的策略。'),
(16816,3,2,'zhCN','啊，齿轮已开始转动。'),
(16816,4,0,'zhCN','愚蠢！太愚蠢了！'),
(16816,5,0,'zhCN','没错……一切尽在计划中。'),
(16816,6,0,'zhCN','只需一丝松懈，便足矣。'),
(16816,7,0,'zhCN','现在有趣了。'),
(16816,8,0,'zhCN','本该如此。'),
(16816,9,0,'zhCN','嗯。'),
(16816,9,1,'zhCN','无所谓。'),
(16816,9,2,'zhCN','有趣。'),
(16816,10,0,'zhCN','小事一桩。'),
(16816,11,0,'zhCN','是的……当然。'),
(16816,12,0,'zhCN','必要的牺牲。'),
(16816,13,0,'zhCN','啊，我早该料到。'),
(16816,14,0,'zhCN','于是，终局将近'),
(16816,15,0,'zhCN','唯有完美，方堪其用。'),
(16816,15,1,'zhCN','于是，一切终结。'),
(16816,16,0,'zhCN','卡拉赞的厅堂震颤，束缚博弈者大厅之门的诅咒就此解除。'),
(16833,0,0,'zhCN','不！不要……塞戴！兽人必须付出代价！'),
(16834,0,0,'zhCN','不！不要……塞戴！兽人必须付出代价！'),
(16834,1,0,'zhCN','你做了什么，马库鲁？！这绝非我们的作风！'),
(16834,2,0,'zhCN','我理解你的感受，马库鲁。毕竟塞戴是我的兄弟。可我们不能以违背他理想的方式，玷污他的遗志。'),
(16863,0,0,'zhCN','%s陷入狂乱！'),
(16871,1,0,'zhCN','入侵者死！'),
(16871,1,1,'zhCN','为了断脊锤！'),
(16871,1,2,'zhCN','你的骨头将被啃食！'),
(16871,1,3,'zhCN','不惜一切代价保护大酋长！'),
(16873,0,0,'zhCN','入侵者死！'),
(16873,0,1,'zhCN','为了断脊锤！'),
(16873,0,2,'zhCN','你的骨头将被啃食！'),
(16873,0,3,'zhCN','不惜一切代价保护大酋长！'),
(16876,1,0,'zhCN','%s变得狂暴！'),
(16876,2,0,'zhCN','入侵者死！'),
(16876,2,1,'zhCN','为了断脊锤！'),
(16876,2,2,'zhCN','你的骨头将被啃食！'),
(16876,2,3,'zhCN','不惜一切代价保护大酋长！'),
(16907,0,0,'zhCN','入侵者死！'),
(16907,0,1,'zhCN','为了断脊锤！'),
(16907,0,2,'zhCN','你的骨头将被啃食！'),
(16907,0,3,'zhCN','不惜一切代价保护大酋长！'),
(16915,0,0,'zhCN','我迟早会让你动起来的，你这堆破铜烂铁。'),
(16915,0,1,'zhCN','什么？！你以为我做不到？我会证明给你看……等我找到我的零件就证明。'),
(16915,0,2,'zhCN','它动了！我发誓，我看到它动了！'),
(16915,0,3,'zhCN','哎哟！不对劲。'),
(16915,0,4,'zhCN','噢对，很好笑是吧？'),
(16923,0,0,'zhCN','既然那可恶的家伙脑袋上挂了赏金，我或许该去猎猎他了。'),
(16925,0,0,'zhCN','入侵者死！'),
(16925,0,1,'zhCN','为了碎脊者！'),
(16925,0,2,'zhCN','你的骨头将被啃食！'),
(16925,0,3,'zhCN','不惜一切代价保护大酋长！'),
(16927,0,0,'zhCN','%s 拼命自卫。'),
(16928,0,0,'zhCN','%s 拼命自卫。'),
(16929,0,0,'zhCN','%s 拼命自卫。'),
(16938,0,2,'zhCN','我会照你说的做，恶魔。至少目前如此。'),
(16972,0,0,'zhCN','%s 闻到附近有一具新鲜尸体。'),
(16973,0,0,'zhCN','%s 闻到附近有一具新鲜尸体。'),
(16980,2,0,'zhCN','入侵者……在这儿？！消灭他们，克尔苏加德！纳克萨玛斯绝不能陷落！'),
(16980,3,0,'zhCN','很好。冰封荒原的战士们，起来！我命令你们为主人战斗、杀戮、赴死！一个不留！'),
(16980,4,0,'zhCN','你会得到你的挑战的，弗丁。'),
(16980,5,0,'zhCN','你那些阵亡勇士的灵魂将归我所有，弗丁。'),
(16995,0,0,'zhCN','你们能感觉到吗，可悲的家伙？笼罩这片土地的阴霾不过是个前奏。很快你们珍视的领地就将落入我们手中！你们将在巫妖王的力量面前倒下！'),
(16995,0,1,'zhCN','前进，我的奴仆！前进！谁也别挡我们的路！'),
(16995,1,0,'zhCN','你们或许以为赢了，蠕虫们，但在巫妖王的力量面前，生者无胜利可言！你们还没见识到我的最终手段！'),
(16995,1,1,'zhCN','你竟敢破坏我在此的杰作？！趁现在准备吧……等我回来，留下的将只有死亡与毁灭！'),
(16995,1,2,'zhCN','看来这些脆弱的生者到底也有几颗牙齿。那就暂且把这地方让给你们。我会以双倍之强归来，你们那点可怜的兵力将土崩瓦解！'),
(16995,2,0,'zhCN','在我们的威势面前颤抖吧！逃命吧！生者不会有胜利！'),
(16995,2,1,'zhCN','随着你们战死沙场，我们的力量愈发壮大。结局只有一个，不可避免。准备迎接你的末日吧！'),
(16995,2,2,'zhCN','绝望吧，凡人！你们的末日已至！'),
(16995,2,3,'zhCN','让这片阴霾提醒你：天灾的阴影无所不在！无处可逃！'),
(17000,0,0,'zhCN','蠢货！你们妄图拒绝我父亲的降临？死亡在等着你们，凡人！'),
(17015,0,0,'zhCN','醒醒，加尔蕾莎。'),
(17015,1,0,'zhCN','你伤愈修养的时间已经够长了，加尔蕾莎。是时候回到路上了。'),
(17015,2,0,'zhCN','你绝不会那样做。我们只是没地方留你。现在，请便吧。'),
(17015,3,0,'zhCN','好吧，随你的便。等我们拒他人于门外时，他们的苦难就由你负责。你掂量着办。'),
(17046,0,0,'zhCN','%s 揉了揉惺忪的睡眼。'),
(17046,1,0,'zhCN','你想要什么，塔勒里斯？'),
(17046,2,0,'zhCN','我不会独自前行，塔勒里斯，就这么定了。我要在这儿等下一批朝圣者，与他们一同出发。'),
(17046,3,0,'zhCN','以太阳井之名，你这顽固的家伙！你休想欺负我离开，塔勒里斯。现在，从我眼前消失！'),
(17063,0,0,'zhCN','于是我说：‘行啊，不过那得额外收费。’'),
(17063,0,1,'zhCN','五秒。我没开玩笑！'),
(17063,0,2,'zhCN','他问那小鬼能不能一起加入——你敢信？其实，还不算太糟……'),
(17063,0,3,'zhCN','他们是事后睡着。我嘛，我是事中睡着……'),
(17063,1,0,'zhCN','来和我玩呀！'),
(17063,1,1,'zhCN','你终将属于我。'),
(17063,1,2,'zhCN','过来，小美人。你身上有我要的东西！'),
(17063,2,0,'zhCN','趁它还在的时候还挺有意思……'),
(17063,2,1,'zhCN','<叹息> 总是结束得太快。'),
(17063,2,2,'zhCN','偏偏在事情变得有趣的时候。'),
(17063,2,3,'zhCN','我们本可以玩得那么开心的！'),
(17063,3,0,'zhCN','再靠近我就喊人了。'),
(17063,3,1,'zhCN','我想让你看看我不同的一面……'),
(17063,3,2,'zhCN','我要你和我在一起……永远永远。'),
(17063,3,3,'zhCN','嘘……我保守着一个小秘密。'),
(17063,3,4,'zhCN','我一直很、很调皮……'),
(17063,3,5,'zhCN','前戏够了。我们来办正事吧。'),
(17083,0,0,'zhCN','好痛！'),
(17083,0,1,'zhCN','啊！别再打了！'),
(17083,0,2,'zhCN','这挠得可不好！'),
(17083,0,3,'zhCN','皮肤着火了！'),
(17083,1,0,'zhCN','好痛！'),
(17083,1,1,'zhCN','啊——！'),
(17083,1,2,'zhCN','再也不怕了！'),
(17083,1,3,'zhCN','妈妈！'),
(17083,1,4,'zhCN','不要了！'),
(17083,2,0,'zhCN','痛！'),
(17083,2,1,'zhCN','好疼！'),
(17083,2,2,'zhCN','格拉啊啊！！'),
(17083,2,3,'zhCN','不要了！！'),
(17093,0,0,'zhCN','%s 从板条箱中取出试剂，将每种各取一份混入烧瓶。'),
(17093,1,0,'zhCN','我历经艰辛才完成研究，而在你的帮助下，$n，我终于做到了。为更光明的未来干杯！'),
(17093,2,0,'zhCN','我觉得……头晕……我……怎么了？'),
(17093,3,0,'zhCN','不，这不可能！这药剂……本该逆转我的瘾症，而不是加速我堕入被遗弃者的行列！'),
(17093,4,0,'zhCN','这么多年的研究……全都白费了！或许他们是对的，或许这是我们必须学会与之共存的东西。'),
(17099,0,0,'zhCN','光明使者乌瑟尔只给奎尔萨拉斯带来了黑暗。让我们看看，能否也给他的坟墓带去些黑暗！'),
(17099,1,0,'zhCN','我终于能报仇了！'),
(17109,0,0,'zhCN','哈哈哈！那个蠢货永远也发现不了我在搞什么！就算发现了，对德莱尼来说也太迟了！'),
(17109,0,1,'zhCN','这些兽人真是蠢货！近在咫尺的力量正等着被人取走，他们却只是袖手旁观，看着别人掠夺财宝！'),
(17109,0,2,'zhCN','我等不及想看这批最新的成果了！'),
(17109,0,3,'zhCN','阿冯竟敢反对我？！我要碾碎他！等我收拾完德莱尼，他们只会希望自己当初成了被流放者！'),
(17109,0,4,'zhCN','哦，你能不能别再一刻不停地修指甲和自我陶醉了？真的，没人在乎！'),
(17109,0,5,'zhCN','你饿了吗？我饿了。我实在受不了再想到图尔塔什的腌火腿排。要是我们能弄点多汁的烤鹌鹑就好了！'),
(17109,1,0,'zhCN','你有什么话要当面说？'),
(17109,2,0,'zhCN','我就知道不会！'),
(17109,3,0,'zhCN','我需要点新鲜空气，虽然这沼泽里根本没那玩意儿！我出去一会儿。我不在时帮我收拾收拾，好吗？'),
(17109,4,0,'zhCN','你非得处处跟着我吗？<叹息>'),
(17127,0,0,'zhCN','马格图尔，谢谢你让我留在这里陪你。我相信我们能从彼此身上学到很多。我也急于了解东方那些被流放者的一切。'),
(17127,1,0,'zhCN','你为何与部落勾结？他们那污秽作派，配不上你。'),
(17127,2,0,'zhCN','我必须想办法制止教条师阿冯对我们迷失的兄弟姐妹所行之事的恶行！'),
(17127,3,0,'zhCN','马格图尔，我相信有办法让被流放者从深渊归来。通过研究他们，我会找到治愈吞噬他们的邪能的方法。如此一来，也能逆转破碎者所受的损伤。'),
(17207,0,0,'zhCN','谁敢挑战奈亚斯？弱小的 $r，你比那些被我像棋盘上的棋子一样耍得团团转的无脑巨魔好不了多少！'),
(17220,0,0,'zhCN','%s 看向坦珀，似乎不太情愿开口。'),
(17220,1,0,'zhCN','谢谢你，萨满。我重获新生，将比以往燃烧得更加明亮！'),
(17228,0,0,'zhCN','那东西四处散播异端邪说，我怎么可能干得成任何活？'),
(17228,1,0,'zhCN','%s 厌恶地叹了口气，转回身继续干活。'),
(17228,2,0,'zhCN','%s 转身面向图伦，轻蔑地冷笑。'),
(17228,3,0,'zhCN','我们这儿不需要你们这种人。'),
(17233,4,0,'zhCN','你为何如此？我生前可曾在哪里得罪过你？'),
(17233,5,0,'zhCN','啊，我现在从你脑海中看到了。这是我从前一个学生的手笔……梅拉尔·黎明之刃。得知他的心已如此黑暗，实在令人痛心。'),
(17233,6,0,'zhCN','回去找他。回到梅洛身边，告诉他我原谅他，也理解他为何如此坚信。'),
(17233,7,0,'zhCN','我只盼他能看见圣光，转而将精力投入到重建昔日美丽的奎尔萨拉斯上。'),
(17238,3,0,'zhCN','定是光明使者印记的纯净之力，将天灾引向了我们。我们必须谨慎行事，以免被淹没！'),
(17238,4,0,'zhCN','我们又被围攻了！自卫！'),
(17238,5,0,'zhCN','这片土地确实需要被圣光净化！我们继续前往墓穴吧。不远了。'),
(17238,6,0,'zhCN','很好，我们继续吧。'),
(17238,7,0,'zhCN','朋友，谢谢你让这一切成为可能。这是我永生难忘的一天！我想我会留下来待一阵。请回到营地的麦克唐奈高阶女祭司那里。我知道她一定会迫切想了解这里发生的一切。'),
(17243,8,0,'zhCN','主人费尽心力才获取了有关埃索达下落的情报。你本可能毁掉整个行动，包括我们内应身份的掩护。'),
(17243,9,0,'zhCN','放松？吉兹尔，你知道凯尔萨斯怎么对付那些让他失望的人吗？永恒的折磨与痛苦……别搞砸了，蠢货。'),
(17243,10,0,'zhCN','我们的血谜岛侦察兵已锁定了我们的联络人。那个蠢货维伦，很快就会露出破绽、毫无防备——足够我们下手！现在从我眼前消失，免得我把你汽化……'),
(17243,11,0,'zhCN','啊哈！找到了一个！'),
(17243,11,1,'zhCN','又一个！'),
(17243,11,2,'zhCN','哦那可是条大的！'),
(17243,11,3,'zhCN','真讽刺，我讨厌大海却爱海滩。'),
(17243,11,4,'zhCN','我在想，你真能从这些东西里听到海吗。'),
(17243,11,5,'zhCN','是，主人，一切按计划进行。'),
(17243,12,0,'zhCN','%s 把贝壳放进了背包。'),
(17243,12,1,'zhCN','%s 仔细检查贝壳。'),
(17243,12,2,'zhCN','%s 把贝壳贴在耳边。'),
(17268,0,0,'zhCN','迪冯，是你吗？'),
(17268,1,0,'zhCN','我几乎听不清你……<杂音> 醒了！'),
(17311,0,0,'zhCN','女儿！'),
(17359,0,0,'zhCN','你对我毕生心血做了什么？！去死！！！'),
(17359,1,0,'zhCN','错的是你们！等我宰了这多管闲事的萨满，再收拾你们俩！'),
(17393,0,0,'zhCN','[Furbolg] 来吧，$n。让我们一同离开水面，获得净化。'),
(17393,1,0,'zhCN','[Furbolg] 我们现在就走，一起。我们会去寻找瓦尔克。'),
(17393,2,0,'zhCN','[Furbolg] 跟我来，去瓦尔克。'),
(17393,3,0,'zhCN','[Furbolg] 快，$n。瓦尔克在等你。'),
(17424,0,0,'zhCN','现在，让我看看……'),
(17424,1,0,'zhCN','在翻译这个的过程中，我发现自己对某个‘安德鲁·克莱门汀’的醉酒事迹了解得，比对本日记作者还多。'),
(17424,2,0,'zhCN','不过无所谓了。尽管克莱门汀先生的……呃，‘贡献’如此，这似乎是一个名叫诺凯的人的日记。末尾的条目描述了一场残酷的战斗。'),
(17424,3,0,'zhCN','看看这段……'),
(17426,0,0,'zhCN','莫蕾……是你吗？'),
(17426,1,0,'zhCN','不……你不是莫蕾，但我感觉你见过她。等你见到她，告诉她我从坠机中活了下来，却死于渗透者之手。'),
(17426,2,0,'zhCN','告诉她……我最后的念头是她……'),
(17433,0,0,'zhCN','这些象形文字讲述了一个故事。开头这个身影，几乎就像我们在碧蓝岗哨遇到的那种生物……'),
(17433,1,0,'zhCN','不，这不可能……上面说这只生物自愿成了军团的仆从。他变成萨特，接受了军团的‘祝福’。'),
(17433,2,0,'zhCN','不，这不可能……上面说这只生物自愿成了军团的仆从。他变成萨特，接受了军团的‘祝福’。'),
(17445,0,0,'zhCN','静松突袭者，出击的时刻到了！冲锋！'),
(17465,0,0,'zhCN','战斗！'),
(17465,2,0,'zhCN','够了。现在退后！'),
(17528,0,0,'zhCN','蠢货！弱者！泽拉克不需要你们的帮助！'),
(17542,0,0,'zhCN','%s 无比惊奇地盯着你。'),
(17542,1,0,'zhCN','我现在就跑！'),
(17612,0,0,'zhCN','谁敢在我面前施展魔法？'),
(17626,1,0,'zhCN','%s 陷入狂乱！'),
(17651,0,0,'zhCN','你引起了我的注意，巨龙。你会发现我可不像下面的村民那样容易吓唬。'),
(17651,1,0,'zhCN','你竟敢在我的居所挑战我？你的狂妄令人震惊，即便对一条龙而言！'),
(17651,2,0,'zhCN','我不知道你在说什么，巨龙……但我不会被你这无礼的做派吓倒。我想离开卡拉赞时自然会离开！'),
(17651,3,0,'zhCN','%s 开始施放一个强大的法术，将自己的精魄编织进魔法之中。'),
(17651,4,0,'zhCN','他不该惹怒我。我得走了……现在去恢复我的力量……'),
(17652,0,0,'zhCN','你对奥术的涉足已走得太远，麦迪文。你已引来远超你理解之力的注意。你必须立刻离开卡拉赞！'),
(17652,1,0,'zhCN','一股黑暗力量企图利用你，麦迪文！若你留下，灾厄之日将接踵而至。你必须快走，我们时间不多了！'),
(17652,2,0,'zhCN','你让我别无选择。若你不听劝告，我就用武力制止你！'),
(17652,3,0,'zhCN','你做了什么，巫师？这不可能！我从……体内开始燃烧！'),
(17658,0,0,'zhCN','向 $N 致敬，奥瑟睿与血谜岛的救星。阿古斯之手的英雄，德莱尼人民的捍卫者！'),
(17663,0,0,'zhCN','要是我能回到蘑菇丛就好了。我这辈子从没见过这么成熟的一丛！'),
(17681,0,1,'zhCN','哇哦！谢啦！'),
(17681,0,2,'zhCN','以维伦的额饰之名，我得救了！'),
(17681,0,3,'zhCN','我就知道科尼利厄斯不会丢下我们！'),
(17693,0,0,'zhCN','入侵者已突破防御！'),
(17703,0,0,'zhCN','你们这些人难道从不去查邮件？'),
(17703,0,1,'zhCN','要我怎么把这些消息全送出去？'),
(17703,0,2,'zhCN','我需要被重新分配。这工作快把我逼疯了……'),
(17703,0,3,'zhCN','他以为自己多了不起。总是使唤我……我要让他好看。我要让他们全都好看！'),
(17703,0,4,'zhCN','总有一天我会亮出水晶毁灭之锤，对这座镇子彻底兽人式地大开杀戒。到时候他们就后悔了……'),
(17715,0,0,'zhCN','谁敢亵渎我们挚爱之人的雕像？'),
(17716,0,0,'zhCN','自卫吧，小家伙！我们倒要看看，你体内是否藏着一名血骑士。'),
(17735,1,0,'zhCN','%s 变得暴怒！'),
(17768,1,0,'zhCN','别误会，$n。我真的很感激你能复活我，但我想这是我最后一次执行这种任务了。或许来一两杯酒能缓解这头疼。'),
(17770,0,0,'zhCN','亨加芬痛苦地咆哮。'),
(17772,7,0,'zhCN','%s 开始引导一个巨大的传送法术。'),
(17797,4,0,'zhCN','享受这场风暴吧，温血的家伙们！'),
(17798,5,0,'zhCN','%s 开始从附近的蒸馏器引导能量……'),
(17855,0,0,'zhCN','尝尝刀刃的滋味吧，杂种！'),
(17855,0,1,'zhCN','请告诉我，你刚才没做我以为你做的事。请告诉我，我不必伤害你……'),
(17855,0,2,'zhCN','好像我们的麻烦还不够多似的，你又去添乱！'),
(17855,0,3,'zhCN','你竟敢在中立之地流血？滚！滚出去，我说！'),
(17855,0,4,'zhCN','我们可不容忍为非作歹之徒，$r。'),
(17855,0,5,'zhCN','拿绳子来！'),
(17855,0,6,'zhCN','听好了：你会巴不得自己没出生过，娘娘腔！'),
(17855,0,7,'zhCN','你的行为让我们所有人都蒙羞，$c。在把你打得失去知觉时，我内心也在痛。'),
(17862,3,1,'zhCN','你真以为你能活着离开这里？'),
(17862,4,0,'zhCN','卫兵……卫兵！'),
(17876,21,0,'zhCN','萨尔一声怒吼，惊了马！'),
(17876,22,0,'zhCN','萨尔试图让马平静下来。'),
(17876,23,0,'zhCN','塔蕾莎不在这儿。我们去镇上吧。'),
(17892,0,1,'zhCN','消灭最后的守护者！'),
(17892,0,2,'zhCN','我们不会失败！'),
(17893,1,0,'zhCN','哎呀！看来你弄出的动静已经引来了不速之客！'),
(17893,2,0,'zhCN','我……受够了……你！'),
(17918,0,1,'zhCN','继续前进！不惜一切代价取胜！'),
(17918,0,2,'zhCN','继续战斗！别动摇！'),
(17957,1,0,'zhCN','入侵者带着囚犯！杀光他们！！！'),
(17969,5,0,'zhCN','我从这里能看到我的德鲁伊同胞了。谢谢你，$n。伊瑟尔一定会为你的行动奖赏你！'),
(17994,1,0,'zhCN','杀了 $n！'),
(18042,0,0,'zhCN','你逃不出我们的手心，德鲁伊！'),
(18096,7,0,'zhCN','没那么快！'),
(18096,7,1,'zhCN','随你怎样挣扎……'),
(18096,8,0,'zhCN','不！主人会……不……高兴的。'),
(18109,0,0,'zhCN','烧！烧！烧！'),
(18174,0,0,'zhCN','莉亚德琳女士一定会找到办法。她必须找到。'),
(18174,0,1,'zhCN','我……听到的可是真的？是太阳王本人？'),
(18174,0,2,'zhCN','即便如此，血骑士们会挺过这次损失。我们别无选择……必须找到另一处源头。'),
(18174,1,0,'zhCN','他们以为自己是谁？'),
(18174,1,1,'zhCN','我懂你的意思……他们以为我们听不见时，就在背后议论我们。他们会有报应的。'),
(18174,1,2,'zhCN','嫉妒，他们就是嫉妒。他们不敢投身于真正的力量。'),
(18174,1,3,'zhCN','他们只是害怕自己根本无法理解的东西。'),
(18175,0,0,'zhCN','如今局势如此莫测，下面的密室已空……'),
(18175,0,1,'zhCN','没了。我不敢相信它没了。谁能想到我们会这样被背叛？'),
(18175,1,0,'zhCN','我们的邻居真可笑。你见过他们冲我们嗤之以鼻的样子吗？'),
(18175,1,1,'zhCN','那些游侠未免太自视甚高了。'),
(18175,1,2,'zhCN','我很快就受够了外面那些肮脏弓箭手那副傲慢态度。'),
(18180,0,0,'zhCN','哎呀，那些雄鹿看起来对我们不太友好！'),
(18180,1,0,'zhCN','小心，菲茨，他们正朝我们冲来！'),
(18185,0,0,'zhCN','%s 发出响亮的嘶嘶声，准备攻击。'),
(18200,0,0,'zhCN','%s 微笑着将步枪入鞘。'),
(18218,0,0,'zhCN','呃……没问题，甘克利。就……<咳嗽>……在那儿等着。 <咳嗽> 弟兄们？'),
(18218,1,0,'zhCN','怎么回事？！'),
(18218,2,0,'zhCN','呃……弟兄们？'),
(18218,3,0,'zhCN','海米特？菲茨？'),
(18218,4,0,'zhCN','哦太好了，我正开始担心呢。'),
(18218,5,0,'zhCN','%s 变换形态，因荆棘划伤的疼痛而呻吟。'),
(18218,5,1,'zhCN','%s 痛苦地呻吟。'),
(18218,5,2,'zhCN','%s 看了看他的朋友们，然后痛苦地哼了一声。'),
(18218,5,3,'zhCN','%s 打着鼾自己醒了过来。'),
(18218,5,4,'zhCN','%s 碰到抓伤周围的敏感处时龇牙咧嘴。'),
(18218,5,5,'zhCN','%s 开始吹起口哨，却突然停下，发出一声呻吟。'),
(18241,0,0,'zhCN','%s 变得暴怒！'),
(18248,0,0,'zhCN','%s 哼了一声，转身离开通缉告示，回到火边他温暖的位置。'),
