(18265,0,0,'zhCN','没什么意外的。带点真消息回来，行吗？'),
(18265,0,1,'zhCN','果然如此。很好，解散。'),
(18292,0,2,'zhCN','他是怎么做到的？'),
(18293,0,1,'zhCN','他真是训练有素！'),
(18294,0,0,'zhCN','嗨，哈罗德。你的兽皮我带来了！'),
(18294,1,0,'zhCN','啊！快来人救我！'),
(18297,0,0,'zhCN','那些兽皮我收下了，小不点。'),
(18297,1,0,'zhCN','%s 翻找着克莉丝汀的东西，抓起她那捆兽皮。'),
(18297,2,0,'zhCN','这是我的兽皮，哈罗德。现在把赏金给我！'),
(18338,0,0,'zhCN','艾泽拉斯在我们阴影下畏缩得太久了！现在，感受燃烧远征的力量，然后绝望吧！'),
(18338,0,1,'zhCN','你的命运已定，艾泽拉斯！我会找到守护巨龙碎片，届时你无法阻挡我们的力量！'),
(18338,0,2,'zhCN','颤抖吧，小虫子！你们的英雄算得了什么！你们的救世主将成为我们的第一顿盛宴！'),
(18338,0,3,'zhCN','在哪？碎片在哪！你们藏不住的！'),
(18338,0,4,'zhCN','你的世界将要灭亡，凡人！你的末日近在眼前！'),
(18338,1,0,'zhCN','你自己的力量在喂养我，$n！'),
(18338,2,0,'zhCN','哈！这地方还不配让我动手。'),
(18340,0,0,'zhCN','我要让你知道，别再招惹我们！'),
(18340,0,1,'zhCN','督军卡利特雷什会听到这等无礼之举的！'),
(18340,0,2,'zhCN','我要让你为此付出代价！'),
(18384,0,0,'zhCN','%s 穿上了他的狼皮法衣。'),
(18384,1,0,'zhCN','森林的狼之灵，聆听我的呼唤！'),
(18384,2,0,'zhCN','很久以前，你曾是我族人的同伴。我们投身邪恶，你便被遗忘了。'),
(18384,3,0,'zhCN','但我们回来了，英灵！我们回来再次向你致敬。请再次降临于我们面前。'),
(18384,4,0,'zhCN','愿我们与你的羁绊永不再次断裂，英灵。'),
(18384,5,0,'zhCN','我们做到了！萨尔会为此骄傲。'),
(18391,0,0,'zhCN','你的鲜血将涂满基尔索罗的墙壁！'),
(18398,0,0,'zhCN','碎趾准备冲锋。'),
(18401,1,0,'zhCN','%s 吸收了攻击中的神圣能量。'),
(18401,2,0,'zhCN','%s 吸收了攻击中的火焰能量。'),
(18401,3,0,'zhCN','%s 吸收了攻击中的自然能量。'),
(18401,4,0,'zhCN','%s 吸收了攻击中的冰霜能量。'),
(18401,5,0,'zhCN','%s 吸收了攻击中的暗影能量。'),
