(18405,0,1,'zhCN','任何入侵者都必须清除！'),
(18408,0,0,'zhCN','新告示贴出来了！冒险者和英雄们，都围到公告板这儿来！'),
(18408,1,0,'zhCN','这应该能给泰拉尔所需的援助！'),
(18420,0,0,'zhCN','嗯……冰霜、火焰与奥术防御的反应比第7批次快，但自然防御仍然被动。'),
(18421,0,0,'zhCN','高阶植物学家？'),
