(18422,0,0,'zhCN','嗯……'),
(18422,1,0,'zhCN','是的。这奏效了。'),
(18440,0,0,'zhCN','它只听命令行事！'),
(18440,0,1,'zhCN','下锅炖了！'),
(18440,0,2,'zhCN','你待在肚子里正合适！'),
(18440,1,0,'zhCN','你爹付给战槌氏族，也许我们就不吃你。'),
(18440,2,0,'zhCN','哈哈！开玩笑的。反正我们肯定会把你吃了！'),
(18440,3,0,'zhCN','砰！看那软骨滋滋作响！'),
(18440,4,0,'zhCN','这就是做最棒破碎者杂烩的配方！'),
(18440,5,0,'zhCN','首先你需要香料。'),
(18440,6,0,'zhCN','盐放进锅里……'),
(18440,7,0,'zhCN','然后把辣椒放进锅里……'),
(18440,8,0,'zhCN','现在我们要用那秘制 ingra……ingor……inrag……那秘制酱料，把档次提上去！'),
(18440,9,0,'zhCN','最后，我们把科基放进去！'),
(18459,0,0,'zhCN','欢庆吧，我的朋友们！$n 将我们从威胁生命的迫近阴影中拯救了出来！'),
(18471,9,1,'zhCN','$n 在地面上只剩下一摊红色污迹！'),
(18471,13,0,'zhCN','$n 被击败了！'),
(18482,0,0,'zhCN','这是什么意思？！'),
(18482,1,0,'zhCN','我现在就走！'),
(18500,0,0,'zhCN','圣光将净化我们所有人！'),
(18537,0,0,'zhCN','我们为你而来，迷失的兄弟。按惯例，在你被毁灭前，我们会给你悔过的机会。我们遵照纳鲁的律法，给予你这次机会。'),
(18537,1,0,'zhCN','我们人虽少，索克雷萨，但我们的信念坚定。这是你永远无法理解的。既然礼数已尽，准备迎接你的末日吧。'),
(18537,2,0,'zhCN','怎么……你怎么能这样？！'),
(18537,3,0,'zhCN','索克雷萨蒙蔽了你的心智，凯兰！你并非真心说出这些话！我还记得你年幼时我训练你的情形。那时你的意志就已坚强！'),
(18548,0,0,'zhCN','这是焰翼据点的东西。你这脏手休想碰它！'),
(18554,4,0,'zhCN','我向您保证我们不会失败，我的主人。我亲自监督建设的每一个环节，最终的密码也由我保管。不出一日，我就会引爆炸弹，炸掉附近那些害虫。'),
(18584,0,0,'zhCN','[Demonic] 卡·卡利克斯！'),
(18585,0,0,'zhCN','拉利克现在教你点教训！'),
(18586,0,0,'zhCN','弗呜隆！库什库什分文不值！去死！'),
(18634,1,0,'zhCN','%s 开始召唤一名密教亡誓者！'),
(18634,2,0,'zhCN','%s 开始召唤一名密教侍僧！'),
(18634,3,0,'zhCN','%s 召唤一名密教侍僧前来助战！'),
(18634,4,0,'zhCN','%s 召唤一名密教亡誓者前来助战！'),
(18635,1,0,'zhCN','%s 陷入狂乱！'),
(18638,1,0,'zhCN','%s 做了几个奇怪的手势。'),
(18644,0,0,'zhCN','%s 从树上摘下一个苹果。'),
(18644,0,1,'zhCN','%s 一边干活一边嘟囔着。'),
(18644,1,0,'zhCN','当然，尽管拿一个，够大家分的！'),
(18644,2,0,'zhCN','是啊，还是坏的。不过没钱买新的。'),
(18644,3,0,'zhCN','不，还是坏的。看来一点运气都没有。'),
(18646,0,0,'zhCN','哎呀你好呀，贝西。今天轮到你散步了吧？'),
(18646,0,1,'zhCN','可怜的贝西，这么热的天被关在这谷仓里。我去给你拿点零食！'),
(18646,0,2,'zhCN','贝西今天饿坏了吧？我去给你拿个苹果。'),
(18646,1,0,'zhCN','日安，本杰明！你介意我拿个苹果给贝西吗？'),
(18646,1,1,'zhCN','你好呀，本杰明！我拿个苹果给老贝西当零嘴，你不介意吧？'),
(18646,1,2,'zhCN','本杰明，我的老朋友，今天能匀一个苹果给贝西吗？'),
(18646,2,0,'zhCN','%s 从树上摘下一个苹果。'),
(18646,3,0,'zhCN','谢了，本杰明！'),
(18646,4,0,'zhCN','塞缪尔，那辆旧马车还在拖累你吗？'),
(18646,4,1,'zhCN','那马车又抛锚了，塞缪尔？'),
(18646,4,2,'zhCN','这么旧的马车，难怪会抛锚，塞缪尔。'),
(18646,5,0,'zhCN','嗯，听你这么说我很难过。要是你需要帮忙，我晚点再来。'),
(18646,6,0,'zhCN','嗯，贝西会喜欢这点小零食。'),
(18646,7,0,'zhCN','来，贝西，趁我帮你备好鞍，先享用这个苹果。'),
(18646,8,1,'zhCN','%s 把那只鲜红的苹果喂给贝西。'),
(18646,9,0,'zhCN','好了好了，布兰奇。别吃醋，你很快也要踏上属于自己的大冒险了。'),
(18646,9,1,'zhCN','哇，慢着，布兰奇，你今天不能吃苹果。明天我们就带你去南海镇，从那儿乘船漂洋过海。'),
(18646,9,2,'zhCN','哎，布兰奇，别担心，我在西部荒野的兄弟会好好照顾你的。听说他有个漂亮的农场，有大把地方让你撒欢。'),
(18646,10,0,'zhCN','好了贝西，咱们带你出来遛遛。驾，驾！'),
(18646,11,0,'zhCN','好姑娘，贝西！'),
(18646,12,0,'zhCN','有收获吗，塞缪尔？'),
(18650,0,0,'zhCN','贝西开心地嘶鸣。'),
(18651,0,0,'zhCN','小布兰奇嫉妒地跺了跺脚。'),
(18655,0,0,'zhCN','抓到了！轮到你了！'),
(18656,0,0,'zhCN','我能一起玩吗？'),
(18656,0,1,'zhCN','呸，男孩真恶心！'),
(18657,0,0,'zhCN','钓鱼的好天气！'),
(18657,0,1,'zhCN','再好不过的天气了！'),
(18657,0,2,'zhCN','没有比一个美好的傍晚更适合钓鱼的了！'),
(18657,1,0,'zhCN','你觉得今天能见到老煤灰吗？'),
(18657,1,1,'zhCN','我打赌这次能钓上条大的……'),
(18657,1,2,'zhCN','我最好别再钓上雷吉的靴子了……'),
(18657,2,0,'zhCN','感谢圣光，伯莎不在这儿……'),
(18657,2,1,'zhCN','没有什么比暖洋洋的日子，再加上没有老太婆冲你吼叫更惬意了……'),
(18657,2,2,'zhCN','安宁与寂静真是独一无二……不像家里！'),
(18657,3,0,'zhCN','确实！温暖的空气配上清凉的池塘，再好不过了……'),
(18657,3,1,'zhCN','我只盼着鱼上钩比虫子多……'),
(18657,3,2,'zhCN','是啊，要是每天都能像今天这样就好了……'),
(18657,4,0,'zhCN','也许……'),
(18657,4,1,'zhCN','什么事都可能发生……'),
(18657,4,2,'zhCN','哈哈，别把希望抱得太高……'),
(18657,5,0,'zhCN','我懂你！没有萨拉抱怨家务，我连一刻清净都没有！'),
(18657,5,1,'zhCN','是啊，也没有吵闹的小鬼来打扰一个男人和他的鱼之间的清静……'),
(18657,6,0,'zhCN','闭嘴，你聒噪会把鱼吓跑的！'),
(18657,6,1,'zhCN','呸，真正的渔夫才不怕最猛的暴雨！'),
(18657,6,2,'zhCN','你说什么？'),
(18657,7,0,'zhCN','抓到一个！'),
(18657,7,1,'zhCN','你们有额外的鱼饵吗？'),
(18657,7,2,'zhCN','还记得那次我们在艾尔文林地逮到红鳍鱼人的事吗？'),
(18657,8,0,'zhCN','你现在倒是这么说，不过至少你有顿热乎晚饭等着你……'),
(18657,8,1,'zhCN','情况可能更糟呢，你老婆说不定跟着哪个奶酪贩子跑去暴风城了！'),
(18657,8,2,'zhCN','这话最好别太大声说！'),
(18677,0,0,'zhCN','%s 变得暴怒！'),
(18679,0,0,'zhCN','%s 变得暴怒！'),
(18683,1,0,'zhCN','%s 吸收了攻击中的神圣能量。'),
(18683,2,0,'zhCN','%s 吸收了攻击中的火焰能量。'),
(18683,3,0,'zhCN','%s 吸收了攻击中的自然能量。'),
(18683,4,0,'zhCN','%s 吸收了攻击中的冰霜能量。'),
(18683,5,0,'zhCN','%s 吸收了攻击中的暗影能量。'),
(18683,6,0,'zhCN','%s 吸收了攻击中的奥术能量。'),
(18693,0,0,'zhCN','莫格多格真蠢，竟以为某个小种族会成为我们的救星。'),
(18693,0,1,'zhCN','别听莫格多格的谎言！奥格瑞拉只是个神话！我们在此用一切企图分裂奴役我们的人的鲜血，缔造自己的天堂！'),
(18693,0,2,'zhCN','时机已到。击倒每一个挡在氏族路上的生物！'),
(18693,0,3,'zhCN','我们永远学不会同心协力吗？还是只会彼此残杀，终被时间遗忘。'),
(18693,0,4,'zhCN','别向莫格多格的傀儡低头！他要用低劣血统的领主取代我们的戈隆霸主。我们为何要换一个主人？'),
(18693,0,5,'zhCN','但愿氏族的首领们肯听。团结是唯一答案。其他一切道路只会导向我们的毁灭。'),
(18693,1,0,'zhCN','我团结的讯息是传达给食人魔氏族的，不是给你这种 $R 的！'),
(18693,1,1,'zhCN','我不会再允许你杀害我的同胞！准备受死！'),
(18693,1,2,'zhCN','我宣判，你是食人魔氏族的敌人。刑罚是死刑！'),
(18693,1,3,'zhCN','食人魔氏族绝不会被征服。无论是戈隆，还是你这种弱小的 $R，都不行！'),
(18713,0,0,'zhCN','格拉维尔锤中尉翻弄着桌上成堆的书籍与卷轴，开始饶有兴致地审视其中一本。'),
(18713,1,0,'zhCN','什么？这是怎么回事？！'),
(18713,1,1,'zhCN','那简直难以想象！'),
(18713,1,2,'zhCN','看来我选了个戒酒的坏日子。'),
(18713,1,3,'zhCN','这怎么会漏掉的？！'),
(18713,2,0,'zhCN','船长，长官，我们出了点小麻烦。'),
(18713,3,0,'zhCN','遵命，长官。看来有人没告诉我，塞纳里奥树丛的德鲁伊已经被消灭了！'),
(18713,3,1,'zhCN','坏消息。我们又挨打了。他们走了，但前哨瞭望塔烧着了。'),
(18713,3,2,'zhCN','我们的一名商人失踪了！'),
(18713,3,3,'zhCN','那群刚从荣誉堡来的人——他们是雇佣兵！开始惹事了。也许我该跟他们谈谈？'),
(18713,3,4,'zhCN','我们一名侦察兵报告，一个神秘组织已进驻格兰戈瓦尔村庄的废墟。哎呀，这份报告是一周多前的了。'),
(18713,3,5,'zhCN','我们收到外勤侦察兵的报告，一名塞纳里奥德鲁伊在焰翼据点被俘。'),
(18713,4,0,'zhCN','遵命，长官。马上！'),
(18745,5,0,'zhCN','稍息，中尉。说吧。'),
(18745,5,1,'zhCN','又怎么了，格拉维尔？'),
(18745,5,2,'zhCN','还能有什么更糟的？'),
(18745,5,3,'zhCN','中尉，有何报告？'),
(18745,6,0,'zhCN','这确实是令人不安的消息。务必立即处理！'),
(18745,6,1,'zhCN','我没空管这个，中尉。你务必处理好。'),
(18745,6,2,'zhCN','若我们想在各方面帮忙，就需要更多人手。叫些侦察兵进来协助吧。'),
(18745,6,3,'zhCN','中尉，我要你把那当作首要任务。通知任何你认为能帮忙的人。'),
(18805,1,1,'zhCN','我要粉碎你那妄自尊大的幻想！'),
(18805,2,1,'zhCN','以高等精灵之血起誓！'),
(18805,2,2,'zhCN','为了太阳井！'),
(18805,4,1,'zhCN','我将与虚空……融为一体！'),
(18810,0,0,'zhCN','你要是不吃鱼，哪来的布丁吃？'),
(18810,0,1,'zhCN','你要是不吃鱼，就别想吃什么布丁！'),
(18827,0,0,'zhCN','%s 的双眼泛起红光，开始疯狂地咯咯大笑！'),
(18870,1,0,'zhCN','%s 吸收了攻击中的神圣能量。'),
(18870,2,0,'zhCN','%s 吸收了攻击中的火焰能量。'),
(18870,3,0,'zhCN','%s 吸收了攻击中的自然能量。'),
(18870,4,0,'zhCN','%s 吸收了攻击中的冰霜能量。'),
(18870,5,0,'zhCN','%s 吸收了攻击中的暗影能量。'),
(18870,6,0,'zhCN','%s 吸收了攻击中的奥术能量。'),
(18881,0,0,'zhCN','%s 碎裂成片。'),
(18897,0,0,'zhCN','欢迎，欢迎，来到这座最近被霸占并草率改名的蒸汽挖掘机体育场！'),
(18926,0,0,'zhCN','对付被遗弃者遇到了麻烦？我正好有你需要的东西。'),
(18926,1,0,'zhCN','只是别问我从哪儿弄来的……'),
(18926,2,0,'zhCN','必须对这些被遗弃者做点什么……'),
(18926,3,0,'zhCN','一旦解决了他们，我们就能把更多资源投入战事。'),
(18929,1,0,'zhCN','时光本会过得甜美得多。'),
(18929,2,0,'zhCN','噢，这活儿真要命！'),
(18929,3,0,'zhCN','一整天，都被臭脚丫的味道包围着。'),
(18929,4,0,'zhCN','妈妈为什么不能献身于别的事呢？'),
(18929,5,0,'zhCN','蛋糕、酥饼，连面包都行——就是别放奶酪！'),
(18947,0,0,'zhCN','嘎！每次我把东西装进马车，它转眼就又出现在这儿！'),
(18947,1,0,'zhCN','我真不该把那本戏法之书交给西兰娜。'),
(18952,0,1,'zhCN','为了碎脊者！'),
(18952,0,2,'zhCN','你的骨头将被啃食！'),
(18952,0,3,'zhCN','不惜一切代价保护大酋长！'),
(18966,0,1,'zhCN','每过一刻，我都看到艾泽拉斯的子民再次印证我们降临的理由。我怀着庄严的骄傲与你们并肩作战，若今日我死去，也是死于朋友之间。'),
(18966,0,2,'zhCN','恶魔们应当毫不怀疑，我们正是他们的克星；尽管他们妄图毁灭我们，但将其推向覆灭的却是我们。卡扎克及其军队将在这联盟之下被削弱、被击败。为此，我们必须将血肉与赤心抛向他们，因为他们所求的，无非是这个世界的毁灭。'),
(18966,0,3,'zhCN','继续战斗吧，艾泽拉斯的善良人民。振作起来！你们的同胞正奔向这座地狱般的传送门，很快也会如你们这般勇敢地扑向这些恶魔。愿圣光庇佑你们！'),
(18966,0,4,'zhCN','见证圣光的力量！愿恩典与荣耀归于联盟！'),
(18969,0,0,'zhCN','猎人们，到我这儿来！让我们让这些恶魔见识，在艾泽拉斯战斗与赴死是何等滋味！'),
(18969,0,1,'zhCN','神灵为我们歌唱！他们唱着战斗之歌！'),
(18969,0,2,'zhCN','精准出击，兄弟姐妹们！今日我们的猎物是恶魔！'),
(18969,0,3,'zhCN','我们再次要向燃烧军团证明，我们的世界不容夺取！'),
(18969,0,4,'zhCN','这些恶魔必败！为了艾泽拉斯！'),
(18969,0,5,'zhCN','若今日赴死是我们的宿命，那我们绝不会轻易就范！记住我的话，这些恶魔会像麦子一样倒下！'),
(18969,0,6,'zhCN','纵然你筋疲力尽，鲜血从伤口淌入这片泥泞之地，你仍为世界的精灵而战。任何邪恶之力都无法与我们为敌！'),
(18969,0,7,'zhCN','我的兄弟，我的战友！我必须去求援部落的军队，把他们引到这里！鼓起勇气，勇敢的猎手们！别倒在传送门滋生的恶魔手下！'),
(18976,0,0,'zhCN','干快点！'),
(18976,1,0,'zhCN','我的石头！凿开石头！快点！快点！'),
(19191,2,0,'zhCN','蠢货！你不过是个在超乎你理解的世界里玩耍的孩子。闭嘴！'),
(19191,3,0,'zhCN','你的武器对我毫无意义！屈服吧！'),
(19191,4,0,'zhCN','你对你的技艺有信心？仔细想想，答案或许会让你意外。'),
(19209,0,0,'zhCN','%s 陷入狂乱！'),
(19220,1,1,'zhCN','现在你为我效力了！'),
(19227,0,3,'zhCN','外面很危险，对吧？知道你需要什么吗？保护。我能帮你挑战死亡本身！你把这块狂石戴在脖子上，瞧，要是你发现自己进了灵界，就能回来！只要快速奔向你的尸体，你就能复活，焕然一新！'),
(19227,0,4,'zhCN','神奇的护符！不可思议的奇物！那些新潮的珠宝匠比起老格里夫塔久经考验的神秘法门可差远了！用这些魔法护符提升你自己，价格公道！'),
(19227,0,5,'zhCN','过来，$r。你不想在地下城里冒险送命吧？那活儿又脏又累，图啥？就为点不值钱的破玩意儿？得了吧，你需要的是我的一枚护符。保证管用！'),
(19227,0,6,'zhCN','你看上去累了，$c。我这儿有点东西给你。这些护符能帮你跨越障碍、像天生就会似的在河里游泳。它们还能给你的食物充能，让你的伤口在你眼前愈合！'),
(19228,51,0,'zhCN','嘿，醉鬼拉利克来了……他老妈胖得哟，飞到刀锋山时人家按磅收费！'),
(19255,0,4,'zhCN','大酋长悬赏阿拉齐乌斯的人头！从现在起，那坨没用的恶魔渣滓就是头号敌人。'),
(19257,0,0,'zhCN','来袭！别让他们通过！集火！现在，现在，现在！'),
(19270,0,1,'zhCN','几分钟后，来欣赏佩里·加特纳的喜剧表演！'),
(19270,1,0,'zhCN','牛头人酋长乐队！现场 live 演出，就在世界尽头酒馆！整点准时到场！被沙塔斯驱逐了？偷偷溜回来！'),
(19270,1,1,'zhCN','准备好摇滚了吗？那就去世界尽头酒馆吧！牛头人酋长乐队整点开演。'),
(19270,1,2,'zhCN','谁？牛头人酋长乐队！什么？现场演出！在哪？世界尽头酒馆！何时？整点！准时到场！'),
(19270,1,3,'zhCN','现在，在沙塔斯城：牛头人酋长乐队！整点在世界尽头酒馆开演！'),
(19308,0,3,'zhCN','我很遗憾地通知各位，今天我们又送了十名士兵回家——装在裹尸袋里。'),
(19316,0,0,'zhCN','拆了它，士兵们！我们要把这玩意儿运回暴风城！'),
(19316,0,1,'zhCN','我们要把这堆破铜烂铁熔了，用铸锭造武器！看看军团喜不喜欢尝尝联盟风味的邪能收割者！'),
(19316,0,2,'zhCN','干得好，士兵们！我们可不会让部落那些肮脏的畜生盖过我们的风头！'),
(19316,0,3,'zhCN','让他们再朝我们扔这种膨胀的铁皮罐头！我们要让他们见识联盟的骨气！'),
(19380,0,1,'zhCN','要是你修不好，我们就看看你适不适合下锅。现在干活！'),
(19383,0,1,'zhCN','求你别打我！'),
(19385,0,0,'zhCN','元帅们……持剑的兄弟姐妹们。我宁愿与你们并肩作战，也不要千军万马。我们是雄狮！你们可知穿过这些恶魔、越过那黑暗之门后等待我们的是什么？永生！去夺取吧！'),
(19385,1,0,'zhCN','人人奋战，无人退缩。'),
(19385,1,1,'zhCN','因此，让我们振奋精神，恪尽职守，好让即便艾泽拉斯的人类存续千年，人们仍会说：‘这是他们最光辉的时刻。’'),
(19385,1,2,'zhCN','今日我们战斗！！以你在这片美好土地上所珍视的一切起誓，我号令你挺身而出，艾泽拉斯的英雄们！'),
(19385,1,3,'zhCN','是的。战斗，你或许会死。逃跑，你能活命，但又能活多久？恶魔已扑向我们！而那些不在这里的人，几周后将在自己的村庄里等死——他们可愿用从今天到那日的所有日子，换一个来此阻止这些恐怖之物入侵我们世界的机会？'),
(19385,1,4,'zhCN','守住阵地！守住阵地！联盟的儿女！部落的儿女！我的兄弟姐妹们！我在你们眼中看到了与我同样的恐惧，那恐惧足以令我的心枯萎。也许有一天，我们的勇气会消逝，我们会背弃朋友、离散同盟……但绝不是今天！'),
(19385,1,5,'zhCN','我们少数人，我们幸福的少数人，我们同胞的兄弟姊妹。今日与我同洒热血者，皆为我手足；即便他们再卑劣，这一日也将宽宥他们的境遇。'),
(19385,1,6,'zhCN','此刻安卧于艾泽拉斯的人，定会自惭形秽未曾在此，只要有人讲述我们在这黑暗之日并肩作战，他们便觉自己的勇武微不足道。'),
(19385,1,7,'zhCN','无论作为王国还是个人，是时候放下我们长久的恩怨，团结一致了。一场无法取胜的战争浪潮已逼近，我们必须向高处避难，以免被黑暗的洪流吞没。'),
(19385,2,0,'zhCN','银色黎明！我们去召集更多援手！继续战斗吧，兄弟姐妹们。要知道，你们不会孤军奋战太久！'),
(19392,0,0,'zhCN','我们遭到袭击！快找掩护！'),
(19392,0,1,'zhCN','地狱火！清空庭院！'),
(19392,0,2,'zhCN','地狱火雨增多！找掩护！'),
(19422,0,0,'zhCN','入侵者死！'),
(19422,0,1,'zhCN','为了碎脊者！'),
(19422,0,2,'zhCN','你的骨头将被啃食！'),
(19422,0,3,'zhCN','不惜一切代价保护大酋长！'),
(19424,0,0,'zhCN','入侵者死！'),
(19424,0,1,'zhCN','为了碎脊者！'),
(19424,0,2,'zhCN','你的骨头将被啃食！'),
(19424,0,3,'zhCN','不惜一切代价保护大酋长！'),
(19447,0,0,'zhCN','圣光，引领逝者由虚妄归于真理，由黑暗归于圣光，由死亡归于永生。'),
(19447,1,0,'zhCN','愿圣光与你同在，直至永恒。'),
(19447,2,0,'zhCN','圣光，赐我力量。'),
(19447,3,0,'zhCN','牧师跪地默祷。'),
(19477,0,0,'zhCN','工头死了！快，德雷格之子们！跑！'),
(19477,0,1,'zhCN','逃！逃！'),
(19477,0,2,'zhCN','这是我们的机会！快逃！'),
(19510,0,0,'zhCN','入侵者已突破工厂！立即启动紧急防御协议！'),
(19523,3,1,'zhCN','我们杀别人！'),
(19523,3,2,'zhCN','我不喜欢这个……'),
(19523,3,3,'zhCN','我们杀了他的朋友！'),
(19524,3,1,'zhCN','我还没完呢，白痴！'),
(19524,3,2,'zhCN','嘿，你这笨蛋！'),
(19561,0,0,'zhCN','我是瞎了，你这蠢母猪崽子，又不是聋了。别打歪主意。'),
(19569,0,0,'zhCN','希望对面那些血精灵别以为我在监视他们！'),
(19569,1,0,'zhCN','我要是聪明点，就该把这项研究卖了，换张火箭船的票。我有种预感，我们很快就得离开这儿！'),
(19569,2,0,'zhCN','如果这没错，我们时间不多了！唉，算了。'),
(19569,3,0,'zhCN','这是我最后一次从虚灵手里买二手装备！'),
(19570,0,0,'zhCN','哦不！X-52 虚空火箭遭到攻击！卫兵！卫兵！'),
(19616,0,0,'zhCN','%s 回应玛卢卡兹的呼唤而嚎叫。'),
(19616,1,0,'zhCN','%s 表示赞许。'),
(19667,0,0,'zhCN','致敬，格哲！哈拉萨米德区又下了十七份订单。正如你所料，重维达尔矿市场几乎崩溃了。'),
(19667,0,1,'zhCN','赫拉齐的出口正在增长，长官。我们已经贿赂了相关税务官，违禁品几天内就会开始运抵。'),
(19667,1,0,'zhCN','恕我告退，长官。'),
(19671,14,0,'zhCN','好，休息时间结束。出发！'),
(19671,15,0,'zhCN','哦是吗？那会是什么呢？'),
