(20351,4,0,'zhCN','那怪物是你的吗，艾德？啊呵……她可真大个儿！'),
(20351,5,0,'zhCN','啊呵，艾德！她绝对经得起风浪！'),
(20351,6,0,'zhCN','你能保守秘密吗，艾德？啊呵，死人不会泄密！'),
