(20363,0,2,'zhCN','%s 移动了一块石头。'),
(20363,1,0,'zhCN','我恨这地方和里面所有人！史密斯去做这个！史密斯去做那个！哦，所以我现在成农夫了，嗯？所以我得去收东西，嗯？我盼着有一天这整片地方变成一座大墓园，把所有大嘴巴都埋在这儿！'),
