(20428,1,0,'zhCN','阿尔萨斯王子？得了吧。据我所闻，他成天追着普罗德摩尔的女儿跑。我跟你说，这小子心里装的可不止国事。'),
(20428,2,0,'zhCN','是啊，说得对。乌瑟尔——那才是真正属于人民的英雄。'),
(20429,0,0,'zhCN','自战争以来他就变了个人。仿佛一夜之间苍老，成了个老头。不过他那儿子——将来会成为一位出色的国王。'),
(20429,1,0,'zhCN','我不太确定。我听说他正被训练成圣骑士。泰瑞纳斯希望白银之手能教他些纪律。要说谁能把阿尔萨斯引回正途，那只能是老乌瑟尔了。'),
(20429,2,0,'zhCN','那你听说了布莱克摩尔中尉的新角斗士吗？有人说他无人能敌。'),
(20429,3,0,'zhCN','无论输赢，中尉养那种宠物兽人准是疯了。那些家伙不可信。它们就是畜生。'),
(20430,0,0,'zhCN','是啊，我见过他打架。他是个兽人——块头大得很。上次赌他输，赔了一周工钱。再不会犯这错了！'),
