(23224,0,73,'zhCN','伙计，你今天选错了来摇我的时机！准备好失望吧。'),
(23224,0,74,'zhCN','除非你是某种超人。别自欺欺人了，你不是。'),
(23224,0,75,'zhCN','那概率就跟我和魅魔约会差不多。'),
(23224,0,76,'zhCN','我的占卜之力深不可测——而你的几率是：毫无机会。'),
