(23335,2,0,'zhCN','你知道吗，$n，能和你共事真是我的荣幸！$B$B等你不用驯捕的时候，也许我们可以 $g go out some place for dinner? : get together for a girl''s night?;$B$B哦，我有没有提过，我们现在能很快把你送到我们在斯克希尔山脉的基地？如果你想，去和天卫管理员伊雷娜谈谈这事。'),
(23335,3,0,'zhCN','嗯，你最近常来，不过咱们下班后聚聚却总是错过。$B$B是我的问题吗？$B$B<卡蒂刻意打起精神。>$B$B总之，我只是想说……我……我们真的很感激你为天卫所做的一切！'),
(23335,4,0,'zhCN','我希望你别觉得我是个跟踪狂，或者别的什么，$n。$B$B我是说，我知道你现在在天卫里很有名了，而且……我肯定你不会想跟像我这样低贱的苦工混在一起。$B$B不过，要是你想聚聚、随便逛逛，或者再弄几条鳐鱼，随时过来！我会在这儿。$B$B我想你……'),
(23353,0,0,'zhCN','我的年纪远超你的想象。放尊重些！'),
