(23543,0,0,'zhCN','听着，恶犬！我唾弃的正是你！现在感受……烈焰的灼烧吧！'),
(23543,1,0,'zhCN','准备好吧，丧钟已敲响！庇护你们当中的弱者、幼者与老者！你们每个人都得付出最终代价！乞求怜悯吧；清算已至！'),
(23543,2,0,'zhCN','天色昏暗。火焰燃烧。命运之轮转动，你徒劳挣扎。'),
(23543,3,0,'zhCN','小镇仍在燃烧。一场净化之火！时日无多，我很快就要歇息了！'),
(23543,4,0,'zhCN','烈焰吞噬！你们尝试过，却失败了。毋庸置疑，正义胜出！'),
(23543,5,0,'zhCN','我的火焰已熄，再无半点星火！现在我将送你前往死寂的黑暗！'),
(23543,6,0,'zhCN','你如此急切，要让我的鲜血横流。可要击败我，你得斩下我的头颅！'),
(23560,0,0,'zhCN','现在不行，麦克。我没心情让你这醉鬼动手动脚。滚开！'),
(23560,0,1,'zhCN','滚开，麦克！不然我就让巴德把你炖了喂我的猎犬……'),
(23560,0,2,'zhCN','这儿没啥可喝的，麦克。一边去！'),
(23560,0,3,'zhCN','滚到湖里淹死吧，麦克？我没看见你就先闻到你的味儿了……'),
(23566,0,0,'zhCN','让这些传单白白浪费掉，岂不可惜？'),
(23566,1,0,'zhCN','只要稍加巧妙的编排，这些东西就有用得多……'),
(23569,0,0,'zhCN','嗯……旧硬币……丑陋的珠宝……'),
(23569,1,0,'zhCN','更多丑陋的珠宝……家书……我开始放弃希望了！'),
