(24035,1,6,'zhCN','你救了我的命！'),
(24035,1,7,'zhCN','谢天谢地有你！'),
(24041,6,0,'zhCN','听你部下的临终喘息吧，我要将他们的灵魂一饮而尽！'),
(24041,7,0,'zhCN','你不会就此摆脱我。等乌特加德的大军降临于你，我会回来朝你的尸体吐唾沫！'),
