(24405,4,1,'zhCN','祝你好运！'),
(24406,0,0,'zhCN','哇哦！我得救了！谢谢你，$n。'),
(24406,1,0,'zhCN','哦天。那是什么味道——哦等等，嘿，哎呀！看来我的感官得花点时间重新适应。'),
(24406,2,0,'zhCN','抱歉了，朋友们。来，这个应该能弥补搭救我花掉的那些费用。'),
(24406,3,0,'zhCN','回头见！'),
(24407,0,0,'zhCN','嗯，现在。真是令人愉快的发展。'),
(24407,1,0,'zhCN','你救了我而不是那些可怜虫，你真是走运。'),
(24407,2,0,'zhCN','请收下我的酬劳，还有我的谢意，辛苦你了。'),
(24407,3,0,'zhCN','保重，$n。'),
(24408,0,0,'zhCN','哦，可能吗？我……我摆脱了那可怕的诅咒？'),
(24408,1,0,'zhCN','言语无法表达我的感激，$n。谢谢你的善意。'),
(24408,2,0,'zhCN','如你所见，被那些野蛮人抓住后，我只剩这点东西了，但你想拿尽管拿。来，看看吧。'),
(24409,0,0,'zhCN','嗯嗯，苍蝇！现在我能尝到味道，更好了。'),
(24409,1,0,'zhCN','多亏了你，能重回不死之列真好。'),
(24409,2,0,'zhCN','也许我能提供一些你感兴趣的东西？来吧，看看有没有喜欢的。'),
(24445,0,0,'zhCN','哇——！我又变回女孩啦！'),
(24445,1,0,'zhCN','谢谢你救了我。我简直讨厌死当只恶心的青蛙了！'),
(24445,2,0,'zhCN','我其实不该和陌生人说话，不过你对我说实在太好了。这是我被绑架前找到的一件特别的东西。'),
(24445,3,0,'zhCN','我现在该走了。保重！'),
(24448,0,0,'zhCN','哎呀，糟了！你把一切都搞砸了！'),
(24448,1,0,'zhCN','你知不知道，跳那么远有多带劲？'),
(24448,2,0,'zhCN','哦算了，反正我正开始想念我的伙伴们——他们才不肯信呢！哦，给——这个你拿去，我玩捉迷藏时找到的。'),
(24448,3,0,'zhCN','看看我还能不能发出那声音……'),
(24453,0,0,'zhCN','哼。心领了，不过我并不需要帮忙。'),
(24453,1,0,'zhCN','我当时在钻研一个能化解我困境的戏法，已经非常接近找到……<呱>……噢天哪！'),
(24453,2,0,'zhCN','嗯，我想我确实欠你点什么——给，拿一个这个。我多的是。'),
(24453,3,0,'zhCN','你或许该考虑离开此地。我觉得变成青蛙算是这里能发生在你身上的较好结果之一。'),
(24455,0,0,'zhCN','哦！回到我美丽的模样了？太好了！我还以为自己要永远当只青蛙了。'),
(24455,1,0,'zhCN','简直糟透了。我浑身黏糊糊的，还不停舔自己的眼睛！'),
(24455,2,0,'zhCN','谢天谢地你来得正是时候。请拿一个巨魔箱子，留作纪念。'),
(24455,3,0,'zhCN','我再也不想见到这潭臭水了。谢谢你，$n。我永远不会忘记你！'),
