(25032,0,9,'zhCN','如果我是那些破晓之刃的血精灵，眼下$n在此，我早就游离这座岛了。'),
(25032,0,10,'zhCN','你觉得$n超度了多少可怜虫？'),
(25032,0,11,'zhCN','立正！我们最出色的战士之一$n来了！'),
(25032,0,12,'zhCN','欢迎回来，$n。'),
(25032,0,13,'zhCN','那位就是我们的$g hero : heroine;！你近来可好，$n？'),
(25032,0,14,'zhCN','我敢说，没有$n，这次进攻早就失败了。'),
(25032,0,15,'zhCN','无论如何，你的功绩在此永远受颂扬，$n！'),
