(25032,0,17,'zhCN','$n，改天我想请你喝一杯。'),
(25032,0,18,'zhCN','$n，你不知道见到你让我多松口气！'),
(25032,0,19,'zhCN','好巧……我们刚才还在说你呢，$n！'),
(25032,0,20,'zhCN','要什么哨兵？$n来了！'),
(25032,0,21,'zhCN','嘿，$n，把点荣耀留给我们成不？'),
