(25222,2,1,'zhCN','怕是不行，朋友。给你剑和盾。去兵营报到服役。'),
(25222,2,2,'zhCN','你真让我伤心——我可是有名额要填满的，知道吗？你会使剑吗？去兵营吧。'),
(25222,2,3,'zhCN','就凭你那使剑的臂力？朋友，恐怕我们需要你上前沿。去兵营报到。'),
(25222,2,4,'zhCN','看来还能再收一个……不，我看错了。那是七不是一。希望你剑使得好——去兵营报到。'),
(25222,3,0,'zhCN','下一位，麻烦了！'),
(25222,3,1,'zhCN','大家往前走，别堵着。'),
(25222,3,2,'zhCN','下一个！'),
(25238,0,0,'zhCN','大家去镇厅！我们给你们带来了武器！武装自己，把天灾军团打回去！'),
(25242,0,0,'zhCN','$g Sir:Ma''am;, 我为部落献出生命！'),
