(25242,0,6,'zhCN','那里走来一位英雄！'),
(25242,0,7,'zhCN','是$n！低下你们的头！'),
(25242,0,8,'zhCN','%s 向你欢呼。'),
(25243,0,0,'zhCN','$g Sir:Ma''am;, 我为部落献出生命！'),
(25243,0,1,'zhCN','欢迎回来，勇士。'),
(25243,0,2,'zhCN','$g sir:ma''am;，能与你并肩作战是我的荣幸。'),
(25243,0,3,'zhCN','Lok''tar ogar！'),
(25243,0,4,'zhCN','Throm-Ka，英雄！'),
(25243,0,5,'zhCN','有你的力量与决心，我们绝不会败！'),
(25243,0,6,'zhCN','那里走来一位英雄！'),
(25243,0,7,'zhCN','是$n！低下你们的头！'),
(25243,0,8,'zhCN','%s 向你欢呼。'),
(25245,0,0,'zhCN','你们几个知道规矩。值勤军人禁酒。想让将军亲自动手杀了我？'),
(25245,1,0,'zhCN','行行行……但可不是从我这儿拿的！'),
(25258,0,0,'zhCN','上前线前最后喝一杯？'),
(25258,1,0,'zhCN','酒保！上你最烈的麦酒。我们要上前线了。'),
(25258,2,0,'zhCN','你总该为我们破个例吧，嗯？我们可能回不来了。'),
(25258,3,0,'zhCN','看来就这样了。走了。'),
(25259,0,0,'zhCN','当然，有何不可？'),
(25260,0,0,'zhCN','嘿，兄弟们！等等我！'),
(25261,0,0,'zhCN','那是我喝过最难喝的啤酒。'),
(25270,0,0,'zhCN','哇哈哈！我自由啦！'),
(25270,0,1,'zhCN','谢啦，哥们！'),
(25270,0,2,'zhCN','莫图斯先生肯定要气炸了！我回家了。'),
(25270,0,3,'zhCN','它为啥老让我把乳液放进篮子里？我才不要那乳液！'),
(25270,0,4,'zhCN','哈？我在哪？这看着不妙！我跑了！'),
(25274,0,0,'zhCN','把火烧旺，你这大笨蛋！'),
(25274,0,1,'zhCN','那些武器可不会自己长出来！快点！'),
(25274,0,2,'zhCN','你管那叫锤击？我身边都是些什么业余货？'),
(25274,0,3,'zhCN','你再这么糊弄，我就把你装进箱子送回你娘身边，胸口贴张条子写着：失败者。'),
(25274,0,4,'zhCN','那堆破烂玩意儿我们的士兵能拿来干啥？'),
(25274,0,5,'zhCN','你简直是这整个行动的耻辱！收拾东西滚蛋！'),
(25286,0,0,'zhCN','遵命，长官！'),
(25289,0,0,'zhCN','是，兵仔！该起飞了！'),
(25301,1,0,'zhCN','陛下，我们的教徒渗透并掌控联盟权力结构之举已进行得十分顺利。'),
(25301,2,0,'zhCN','您赐予我的力量，让我对人类心智有了极大的精神操控力。我献上这些祭品，以证我的进展。'),
(25301,3,0,'zhCN','主上，让我来料理这些入侵者。我会把他们的内脏喂给蛆虫。'),
(25301,4,0,'zhCN','是，我的主上！'),
(25317,0,0,'zhCN','$c，怎么了？觉得自己高人一等，不屑和我们一起排队？'),
(25317,1,0,'zhCN','这比看上去难。'),
(25317,1,1,'zhCN','刚才那样还行吗？'),
(25317,1,2,'zhCN','我胳膊都酸了。'),
(25317,1,3,'zhCN','嗯……'),
(25317,1,4,'zhCN','我觉得我开始上手了。'),
(25317,1,5,'zhCN','这可不容易。'),
(25317,2,0,'zhCN','你不会让我睡觉对吧？'),
(25317,2,1,'zhCN','你还要这样搞多久？'),
(25317,2,2,'zhCN','你能不能小点声？'),
(25317,3,0,'zhCN','我只是不想让任何人失望。'),
(25317,3,1,'zhCN','我得找点事做，别闲着。'),
(25317,3,2,'zhCN','我只是紧张。抱歉。'),
(25319,4,0,'zhCN','我已倾尽所能引导！力量已交到你手中！'),
(25324,0,1,'zhCN','你需要什么？'),
(25324,0,2,'zhCN','你发现了什么吗？'),
(25324,0,3,'zhCN','元素之灵焦躁不安……'),
(25339,0,0,'zhCN','哦不……他们锁住了他的灵魂！'),
(25379,1,0,'zhCN','看那些，乌格。你知道那是什么吗？'),
(25379,2,0,'zhCN','那些……'),
(25379,3,0,'zhCN','那些是懦夫。'),
(25379,4,0,'zhCN','%s 摇了摇头。'),
(25379,5,0,'zhCN','不，我的骨血，他们是联盟的士兵。我们立誓要灭的死敌。'),
(25379,6,0,'zhCN','他们来这里，是因为不愿保卫自己的家园……自己的家人……'),
(25379,7,0,'zhCN','他们已经放弃，心甘情愿地向我们投降。'),
(25379,8,0,'zhCN','乌格索尔，他们怕死。'),
(25379,9,0,'zhCN','%s 大笑。'),
(25379,10,0,'zhCN','没错，乌格。不胜利，毋宁死！'),
(25379,11,0,'zhCN','[用破碎的通用语] 听见没，懦夫小子？去死吧！小子为自由而死！'),
(25381,0,0,'zhCN','太糟了！你完全瘫痪了？虚弱？一阵阵发热？'),
(25414,0,0,'zhCN','我的斧头归你，英雄！我们一起消灭这些虫子！'),
(25414,0,1,'zhCN','我们将并肩作战，把天灾从这采石场清除！'),
(25414,1,0,'zhCN','我得回战歌要塞了。英勇作战吧，英雄！'),
(25414,1,1,'zhCN','我得回战歌要塞了，英雄。愿你畅游敌人的鲜血，饱餐他们的哀恸！'),
(25414,1,2,'zhCN','再会，朋友。我得回战歌要塞了。'),
(25414,1,3,'zhCN','英雄，后会有期。职责在召唤！'),
(25420,0,0,'zhCN','以太阳之井的怒火，我终获自由！'),
(25420,0,1,'zhCN','复仇将属于我！为了奎尔萨拉斯！为了辛多雷！'),
(25420,1,0,'zhCN','再会，朋友。我得回战歌要塞了。'),
(25420,1,1,'zhCN','英雄，后会有期。职责在召唤！'),
(25421,0,0,'zhCN','得救了！朋友，谢过你，我也助你一臂之力。'),
(25421,0,1,'zhCN','我们将并肩作战，把天灾从这采石场清除！'),
(25421,1,0,'zhCN','祖先与你同在，英雄。再会！'),
(25421,1,1,'zhCN','灵魂守护着你，朋友。我得回战歌要塞了。'),
(25426,0,0,'zhCN','不，爸爸。他们看着有点像猪。他们是猪吗？'),
(25426,1,0,'zhCN','他们是胆小鬼猪吗，爸爸？'),
(25426,2,0,'zhCN','可是爸爸，他们怕什么？为什么来这儿？'),
(25426,3,0,'zhCN','%s 挠了挠头。'),
(25426,4,0,'zhCN','我……我不明白，爸爸。'),
(25426,5,0,'zhCN','%s 挺起胸膛，踮起脚尖。'),
(25426,6,0,'zhCN','Lok''tar ogar，爸爸！'),
