(25446,2,0,'zhCN','射手们！到前面来！天灾进攻来袭！'),
(25446,3,0,'zhCN','射手们，上膛！'),
(25446,4,0,'zhCN','奈幽因他们的冒犯已受惩罚！'),
(25446,5,0,'zhCN','一个不留！让阿尔萨斯去收拾他们……'),
(25446,5,1,'zhCN','为了地狱咆哮！为了部落！'),
