(26189,0,0,'zhCN','神塔失守了！逃向神庙！'),
(26189,0,1,'zhCN','那个死亡骑士……他疯了！'),
(26189,0,2,'zhCN','阿尔萨斯救救我们——我们完了！'),
(26204,0,0,'zhCN','凡人，你阻止不了霜王降临这个世界。潮猎者的伟力将彻底碾碎拉格纳罗斯，让你的土地成为冰封乐土！'),
(26206,0,0,'zhCN','拉洛瑟拉克，再次见到你真好。'),
(26206,1,0,'zhCN','命运看似格外仁慈。玛里苟斯已挨了一击。等他得知，我确信他会离开魔网枢纽的庇护。'),
(26206,2,0,'zhCN','好好训练他们，拉洛瑟拉克。玛里苟斯的力量超乎他们所见。这一调虎离山，我们大概只能拖延他的计划。'),
(26206,3,0,'zhCN','再会，拉洛瑟拉克。'),
(26214,0,0,'zhCN','凡人，你阻止不了霜王降临这个世界。潮猎者的伟力将彻底碾碎拉格纳罗斯，让你的土地成为冰封乐土！'),
(26215,0,0,'zhCN','凡人，你阻止不了霜王降临这个世界。潮猎者的伟力将彻底碾碎拉格纳罗斯，让你的土地成为冰封乐土！'),
(26216,0,0,'zhCN','凡人，你阻止不了霜王降临这个世界。潮猎者的伟力将彻底碾碎拉格纳罗斯，让你的土地成为冰封乐土！'),
(26225,0,0,'zhCN','命匣不是你能拿走的，$n！你会为冒犯付出代价。'),
(26280,0,0,'zhCN','不行。'),
(26280,0,1,'zhCN','不。'),
(26280,0,2,'zhCN','你得耐心等着。'),
(26280,0,3,'zhCN','戈拉莫什正在举行仪式，没空。'),
(26280,0,4,'zhCN','我的命令是让你在此等候。'),
(26280,0,5,'zhCN','主人马上就来见你。'),
(26280,0,6,'zhCN','很快了。'),
(26280,0,7,'zhCN','抱歉，大使。我的命令很明确。'),
(26445,0,0,'zhCN','将返回铁与石的摇篮。'),
(26445,1,0,'zhCN','回到奥杜尔，安卧于风暴的怀抱。'),
(26445,2,0,'zhCN','造物主最卓越的孩子们，觉醒吧，去继承你们与生俱来之权。'),
(26450,0,0,'zhCN','帕利亚的亡者不会安息，孩子。找到那娜迦女祭司！'),
(26496,0,0,'zhCN','你去告诉你指挥官，我一刻也不愿再等！他到底要不要这结盟？！'),
(26496,0,1,'zhCN','自上次会面后我在此等了无尽时光！戈拉莫什的仪式何时才完？'),
(26496,0,2,'zhCN','这叫人无法忍受！我代表一位聚源亲王，岂容他人让我等候！该是戈拉莫什等着我！'),
(26496,0,3,'zhCN','玛里苟斯亲口向我保证，你们的指挥官会把这项协议的细节列为头等要务。现在让我过去！'),
(26496,0,4,'zhCN','若再让我久等，我将被迫重新考虑以太坊与蓝龙军团的拟议协议！'),
(26496,0,5,'zhCN','你不过是个下属！我片刻也不等了！立刻护送我去见戈拉莫什！'),
(26496,0,6,'zhCN','好，好，我明白了，魔网线路已被引开。我不再等了……即刻召唤戈拉莫什！'),
(26496,0,7,'zhCN','你的冲击针似乎完美起效了。戈拉莫什现在总该有空详谈那拟议协议了吧？'),
(26496,1,0,'zhCN','这又是怎么回事，还要拖延？！'),
(26499,39,0,'zhCN','我抽不出人手放过你。'),
(26527,0,0,'zhCN','哦不！冒险者们，出了可怕的事！我的一位同僚被永恒龙军团抓走了，他们正对他做可怕的事！盯住阿尔萨斯仍是你们的首要任务，但若动作快，你们或许能救下一位时光守护者！'),
(26527,1,0,'zhCN','冒险者们，快！时光守护者撑不了多久了！'),
(26527,2,0,'zhCN','我几乎感知不到时光守护者了！他的时间线正在迅速消逝！'),
(26538,0,0,'zhCN','飞往奥格瑞玛的飞艇刚刚抵达！前往杜隆塔尔的旅客请登艇！'),
(26539,0,0,'zhCN','飞往复仇港的飞艇刚刚抵达！前往嚎风峡湾的旅客请登艇！'),
(26540,0,0,'zhCN','飞往幽暗城的飞艇刚刚抵达！前往提瑞斯法林地的旅客请登艇！'),
(26544,0,0,'zhCN','为了德拉卡塔隆！'),
(26544,1,0,'zhCN','津波必须活下去，斩杀我们的叛徒！'),
(26544,2,0,'zhCN','津波不可阻挡！那要塞必须解放！'),
(26544,3,0,'zhCN','你和这一堆天灾一起完蛋吧！'),
(26544,4,0,'zhCN','我们被自己人背叛了。蒙羞……'),
(26544,5,0,'zhCN','啊，又有精华可捕获了……'),
(26564,0,0,'zhCN','快！快！这些军备今天就必须送到科卡尔先锋军！'),
(26564,0,1,'zhCN','我很乐意把你们全换成地精！别让我失望！'),
(26564,0,2,'zhCN','阿加玛督军对我们要求更高！我们绝不能让他失望！'),
(26564,0,3,'zhCN','别逼我从这箱子上跳下去！兽人，我揍扁你的脑袋。'),
(26568,0,0,'zhCN','别害羞嘛，小精灵。你没感觉到咱俩之间这炽热的爱意在萌芽？'),
(26568,1,0,'zhCN','瞧泽布坦给你弄来了啥！给玫瑰的玫瑰！'),
(26568,2,0,'zhCN','%s 嘟囔着。'),
(26568,3,0,'zhCN','嘿漂亮小姐，泽布坦这儿有两张地毯！你为啥不过来给他暖暖身子，嗯？'),
(26568,4,0,'zhCN','这巨魔觉得你对他有意思！过来嘛！'),
(26569,0,0,'zhCN','滚开，变态！'),
(26569,1,0,'zhCN','咦——！'),
(26569,2,0,'zhCN','就算你是艾泽拉斯最后一个巨魔也不行！'),
(26569,2,1,'zhCN','我名草有主了！快走开！'),
(26569,3,0,'zhCN','休想！'),
(26605,0,0,'zhCN','你犯了致命错误，凡人……无路可逃……'),
(26649,0,0,'zhCN','嘘……过来，邮箱旁边。快，别让人跟踪。'),
(26653,0,0,'zhCN','叛徒！清算之日已至，你们的末日随之而来！届时看你们的巫妖王能否将你们从古神之审判中拯救！现在受死吧！'),
(26763,5,0,'zhCN','%s 为自己施展护盾，将力量引向裂隙！'),
(26769,0,0,'zhCN','我甘愿为主人赴死……'),
(26769,0,1,'zhCN','你的胜利毫无意义。'),
(26769,0,3,'zhCN','阿努贝特坎……会终结你。'),
(26769,0,4,'zhCN','我会再度崛起，更加强大……更……强……'),
(26770,0,0,'zhCN','我甘愿为主人赴死……'),
(26770,0,1,'zhCN','你的胜利毫无意义。'),
(26770,0,3,'zhCN','阿努贝特坎……会终结你。'),
(26770,0,4,'zhCN','我会再度崛起，更加强大……更……强……'),
(26771,0,0,'zhCN','我甘愿为主人赴死……'),
(26771,0,1,'zhCN','你的胜利毫无意义。'),
(26771,0,3,'zhCN','阿努贝特坎……会终结你。'),
(26771,0,4,'zhCN','我会再度崛起，更加强大……更……强……'),
(26811,1,0,'zhCN','你取了我的心，现在我也取你的！'),
(26811,1,1,'zhCN','你为啥要折腾我的内脏，兄弟？'),
(26811,1,2,'zhCN','你捏的是我的肝，兄弟！'),
(26811,1,3,'zhCN','把我的肠子还回来，$r！'),
(26812,1,0,'zhCN','你取了我的心，现在我也取你的！'),
(26812,1,1,'zhCN','你为啥要折腾我的内脏，兄弟？'),
(26812,1,2,'zhCN','你捏的是我的肝，兄弟！'),
(26812,1,3,'zhCN','把我的肠子还回来，$r！'),
(26828,0,0,'zhCN','你考验我的耐心，现在让你见识蓝龙的真正威力。'),
(26828,1,0,'zhCN','我的女士，冲击针已完全就绪。'),
(26828,2,0,'zhCN','这座暗夜精灵神殿下方的魔网，如今正流入蔚蓝龙眠圣地。我们的弟兄应有足够力量碾碎敌人。'),
(26828,3,0,'zhCN','我活着只为侍奉主人，我的女士。'),
(26832,0,0,'zhCN','你做得好，凯尔多努斯。玛里苟斯大人会对你的进展相当满意。'),
(26832,1,0,'zhCN','去对付这搅局者，凯尔多努斯。了结之后，把那人唤作$n者的头颅取来。我要用$g his:her; 的头骨装点我的厅室。'),
(26832,2,0,'zhCN','你们对蓝龙军团的冒犯已被记下。将生命能量从你体内抽离，我会格外快意！'),
(26860,0,0,'zhCN','我从未见你如此急于伤人，姐妹。真是令人欣慰……好吧，去吧！'),
(26860,1,0,'zhCN','那个没骨气的巨魔最后一次让我失望了。安西斯！打断他的腿！'),
(26862,0,0,'zhCN','遵命，我的女士！'),
(26893,0,0,'zhCN','%s 深吸一口气！'),
(26893,1,0,'zhCN','无情者斯卡迪已进入鱼叉发射器射程！'),
(26919,0,0,'zhCN','他们比我料想的强，兄弟，进攻！'),
(26919,1,0,'zhCN','听我号令，我自己对付！'),
(27010,0,0,'zhCN','这些人都让我忙得团团转。把这匹马牵回你的马厩吧。'),
(27017,0,0,'zhCN','启动能量收集。'),
(27017,1,0,'zhCN','能量收集完成。'),
(27037,0,0,'zhCN','不，求你了！别！'),
(27052,0,0,'zhCN','我……我不知道。'),
(27054,0,0,'zhCN','%s 眉开眼笑，浑然不知她在逗他，用他那口音浓重的通用语答道。'),
(27054,1,0,'zhCN','呃！你看，是奥鲁巴祖母给的礼物。她用德莱尼最上等的丝绸手工编织！俺相当自豪，是的。'),
(27055,0,0,'zhCN','%s 不耐烦地哼了一声，朝哨兵甜泉草草瞪了一眼，便昂着鼻子扭过身去。'),
(27056,0,0,'zhCN','%s 隔着营地冲哨兵琥珀线咧嘴一笑，挑逗地抖动着长眉。'),
(27056,1,0,'zhCN','%s 盯着莫多鲁的德莱尼长袍看。'),
(27056,2,0,'zhCN','嘘。纳奥欣。莫多鲁为什么还穿那身荒唐长袍？他活像六小时前刚从阿门戴尔跌出来的异次元乡巴佬。'),
(27056,3,0,'zhCN','我说，莫多鲁。你那身……啊……"绝妙"的长袍打哪儿弄来的，嗯？'),
(27056,4,0,'zhCN','哦。哦……我懂了。真不错！'),
(27056,5,0,'zhCN','%s 忍住笑意。'),
(27071,0,0,'zhCN','我知道，我知道。回囚室去……'),
(27102,0,0,'zhCN','让我来处理，姐妹。'),
(27102,1,0,'zhCN','你到底在想什么，那样挑衅她？'),
(27102,2,0,'zhCN','你毫无判断力时，我做出了正确决断。克伦娜，我不想看你把我们带向毁灭！'),
(27102,3,0,'zhCN','那可不一定。'),
(27102,4,0,'zhCN','你……半吊子蠢货！你这次真干了。我得把你弄得像腿断了的样子。'),
(27102,5,0,'zhCN','要想以后再走路，现在就别动！'),
(27106,0,0,'zhCN','我会保护你的，朋友！'),
(27107,0,0,'zhCN','谢了，朋友。现在这些野兽将感受太阳之井的怒火！'),
(27110,0,0,'zhCN','谢了，哥们！看我能不能让这堆破烂跑快点！'),
(27119,0,0,'zhCN','%s 窃笑着，蹭着哨兵甜泉的脚踝。'),
(27210,1,0,'zhCN','你是来试探突袭军团实力的？'),
(27210,1,1,'zhCN','速速解决这闯入者。我没空理这个！'),
(27210,1,2,'zhCN','你最好重新考虑你的所作所为，蠢货。'),
(27210,1,3,'zhCN','难道要我亲自来处理这闯入者？'),
(27211,0,0,'zhCN','总算来了！'),
(27211,1,0,'zhCN','你这肮脏的杂种，还有什么遗言？'),
(27211,2,0,'zhCN','转念一想，我不在乎。下地狱受煎熬吧，废物！'),
(27211,3,0,'zhCN','哈！这招百看不厌。'),
(27247,0,0,'zhCN','嘿，谁敲的钟？'),
(27277,0,0,'zhCN','好了本。我们又取回了琥珀种子。你懂规矩。'),
(27299,0,0,'zhCN','如果疼就告诉我。'),
(27299,0,1,'zhCN','试试这个……'),
(27299,0,2,'zhCN','我想这次我成功了..'),
(27299,1,0,'zhCN','感觉如何？'),
(27299,1,1,'zhCN','够不够劲？'),
(27299,1,2,'zhCN','你觉得这样能问出点什么吗？'),
(27299,2,0,'zhCN','嗯……'),
(27299,2,1,'zhCN','的确，我们的敌人不会对我们仁慈。'),
(27299,2,2,'zhCN','没错，可我们该逼到什么地步？到了哪一步，我们便与敌人无异？'),
(27300,0,0,'zhCN','你下手还太轻。对我们的敌人别留任何情面。'),
(27300,0,1,'zhCN','施加的痛苦越多，我们越快得到答案。'),
(27315,2,0,'zhCN','朋友，我该怎么报答你才好？'),
(27315,2,1,'zhCN','万岁！'),
(27315,2,2,'zhCN','尤里克，这人并未失却善心。谢了，英雄！'),
(27315,2,3,'zhCN','朋友，我的店门永远为你敞开。'),
(27315,2,4,'zhCN','终于安全了！谢谢你，陌生人！'),
(27315,2,5,'zhCN','谢谢你的帮助，英雄！'),
(27315,2,6,'zhCN','我们成功了！真的成功了！'),
(27315,2,7,'zhCN','你是我的守护天使！你如白衣骑士般自天而降，将我从堕落的深渊中拯救！'),
(27315,2,8,'zhCN','你救了我的命！谢了！'),
(27336,2,0,'zhCN','朋友，我该怎么报答你才好？'),
(27336,2,1,'zhCN','万岁！'),
(27336,2,2,'zhCN','尤里克，这人并未失却善心。谢了，英雄！'),
(27336,2,3,'zhCN','朋友，我的店门永远为你敞开。'),
(27336,2,4,'zhCN','终于安全了！谢谢你，陌生人！'),
(27336,2,5,'zhCN','谢谢你的帮助，英雄！'),
(27336,2,6,'zhCN','我们成功了！真的成功了！'),
(27336,2,7,'zhCN','你是我的守护天使！你如白衣骑士般自天而降，将我从堕落的深渊中拯救！'),
(27336,2,8,'zhCN','你救了我的命！谢了！'),
(27364,0,0,'zhCN','嘿塞莉德！你有没有想让我牵去马厩的宠物？'),
(27364,1,0,'zhCN','走吧，小家伙。'),
(27364,2,0,'zhCN','如果我是国王，我也要有一匹像你这样的马。我会确保你不迷路，我打赌你也会确保我不迷路。'),
(27364,3,0,'zhCN','我们会是最好的朋友。我打赌我和安杜因也会成为最好的朋友。朋友很重要。'),
(27364,4,0,'zhCN','我带你去见别的马。你大概想念同伴了。它们也能当你的朋友。'),
(27440,0,0,'zhCN','外面的奈幽围城令人胆寒，萨盖。它们似乎无穷无尽。'),
(27440,1,0,'zhCN','没错……我昨天才从采石场找回弹药，正是为此。'),
(27440,2,0,'zhCN','但愿炸药尽快布好。大家都盼着歇口气。'),
(27440,3,0,'zhCN','萨鲁法尔来了，萨盖！萨鲁法尔！布洛克斯加的亲兄弟本人，前来助我们一臂之力！'),
(27441,0,0,'zhCN','呀。是那些塌陷坑。你看见没？听说要把它们炸塌填平。'),
(27441,1,0,'zhCN','你说得对。'),
(27441,2,0,'zhCN','呀。地狱咆哮，那是条狠角色，但太急于证明自己了，我寻思着。萨鲁法尔来了，倒是好事，没错。'),
(27629,2,1,'zhCN','我需要治疗！'),
(27629,2,2,'zhCN','我想该我施放回春了！'),
(27705,0,0,'zhCN','啊，我爱斯通纳德的气味！闻起来像……像……兽人臭汗。还有腐臭。不过合在一起，倒也别有风味！这气味得慢慢习惯。'),
(27705,0,1,'zhCN','访客们抱怨空气格外潮湿，我却觉得这对我的肤色有好处！皮肤干燥可不好看。'),
(27705,0,2,'zhCN','真遗憾，莫大的遗憾，我的同族看不见真正沉浸于一种文化能带来何种裨益。'),
(27705,0,3,'zhCN','我在此处，身处一座粗凿石塔，它蹲踞在泥泞沼泽之上，成群的蠓虫肆意穿行于敞开的门洞，我立于那些佝偻、绿皮、卫生堪忧、举止粗鲁的身影之间。我从未如此快活。'),
(27705,0,4,'zhCN','派驻此地前，我只听说过泥浴对皮肤有焕新之效。初次被树根绊倒，我便领略了全部好处！大自然的能耐真是神奇，连一点魔法辅助都不需。'),
(27705,0,5,'zhCN','时至今日，我仍思忖为何偏偏选中我来此驻守。我只能想，上司觉得我格外契合此任，且能迅速习惯此地部落的古怪文化；可我也听到一个着实恶意的传言，说或许是因为我话太多。'),
(27705,1,0,'zhCN','你得学着欣赏周遭环境，瑟曦！'),
(27719,1,0,'zhCN','就在你以为见多不怪之时！$n 将在征服坑与你面对面，对决一头正宗的灰熊丘陵狂暴熊怪！下注吧，各位！'),
(27719,2,0,'zhCN','围过来，各位！拿杯热饮，找个好位子，你们即将见证$r与机器之间的对决！'),
(27719,3,0,'zhCN','直接来自索尔莫丹，由百分百正宗……金属……打造，这就是以闪电为动力的铁魔像——锈血！'),
(27719,4,0,'zhCN','女士们先生们……围到坑边来！'),
(27719,5,0,'zhCN','一角站着……$n，名副其实的世界级$c。屠戮爬行类、哺乳类、机械造物，偶尔还有龙……族。你从未见过像$g him : her; 这样的另一个$r。'),
(27719,6,0,'zhCN','另一角，一名连环杀手、大规模掷人出窗者，数次被判绞刑与钝器死刑！霍尔格伦……地狱裂！女士们先生们……下注吧！'),
(27719,7,0,'zhCN','女士们先生们！呃……这么说吧，这场你绝对不想错过！'),
(27876,0,0,'zhCN','是，莫里根中士。'),
