(27876,3,0,'zhCN','你在说什么呀，中士！'),
(27876,4,0,'zhCN','你得相信我，我是清白的！'),
(27877,0,0,'zhCN','佩雷利先生，若你在旅途中碰见任何天灾活动或可疑勾当的蛛丝马迹，请通知最近的洛丹伦士兵。'),
(27877,1,0,'zhCN','佩雷利先生，我知道你四处奔波叫卖货物。总该听过些关于天灾的流言或消息吧？'),
(27877,2,0,'zhCN','佩雷利先生，这些货物可一直由你监管？'),
(27877,3,0,'zhCN','你该不会正好有希尔斯布莱德的罐头龟汤吧？'),
(27877,4,0,'zhCN','佩雷利先生，你可曾见到任何亡灵的踪迹？你提供的任何消息，阿尔萨斯王子都会感激。'),
(27877,5,0,'zhCN','若我们还有疑问，你打算很快离开此地吗？'),
(27877,6,0,'zhCN','你该不介意我检查你的货品有无被篡改的痕迹吧？'),
(27877,7,0,'zhCN','等等，这是什么？你瞒着我，佩雷利！'),
(27877,8,0,'zhCN','佩雷利，我没收这可疑的谷物。我们正寻找食物被篡改的痕迹，在阿尔萨斯王子查验期间，你最好待着别动。'),
(27877,9,0,'zhCN','那可不一定，佩雷利。那可不一定。'),
(27884,0,0,'zhCN','哦你好，耶娜。你当然可以借点谷物。自取吧。'),
