(27885,0,1,'zhCN','我得给他做点健康的东西，他上周那场病还没好。'),
(27885,0,2,'zhCN','我有不少腌培根，可他早餐已经吃过。'),
(27885,0,3,'zhCN','看看，我们昨晚吃了鸡肉。'),
(27885,1,0,'zhCN','玛莎，我的面包粉用完了。你该不会正好有那批新到的谷物吧？'),
(27885,2,0,'zhCN','谢了，玛莎！我欠你一个人情。'),
(27885,3,0,'zhCN','哦，天哪。'),
(27885,4,0,'zhCN','玛莎，这谷物有问题！王子的一些士兵正在找这个。我去找一个来。'),
(27887,0,0,'zhCN','我们出发！'),
