(28394,0,3,'zhCN','我……我醒来竟是一场噩梦？'),
(28416,0,0,'zhCN','我可不会躺在这里任你宰割！凡人，你想杀我，就得先挣来再吸一口气的资格！'),
(28472,0,0,'zhCN','作为鲜血的弟子，你们力求掌控敌人最本源的生命之力。'),
(28472,1,0,'zhCN','无论刀刃或咒文，鲜血滋养我们的攻击，削弱敌手。'),
(28472,2,0,'zhCN','真正的宗师懂得让鲜血不只为战力效劳。'),
(28472,3,0,'zhCN','从敌手——无论死活——身上剥夺能量，令我们能在劣等存在力竭之处坚持。'),
(28472,4,0,'zhCN','每个倒下的敌人，能量被榨取被窃取，只会进一步助燃我们的攻势。'),
(28472,5,0,'zhCN','作为鲜血之主，我们知晓无终之战……'),
(28472,6,0,'zhCN','我们知晓永难餍足的饥饿……'),
(28472,7,0,'zhCN','我们知晓永不可撼的力量……'),
(28472,8,0,'zhCN','作为鲜血之主，我们亦是生死之主。对抗我们，连希望也会枯竭而死。'),
(28500,0,0,'zhCN','先是他把我的珍贵萨隆邪铁全送了人，又勒令我开始锻造威力更强的符文剑！呸！'),
(28500,0,1,'zhCN','修我的甲，科沃斯！我的剑锈了，科沃斯！……这些该死的凡人何时才学会照顾自己？'),
(28500,0,2,'zhCN','我或许没有那些无脑仆从，但至少还不时能见到一把好剑。'),
(28500,0,3,'zhCN','这儿有活要干，可你见有人抢着来帮我吗？没有！全是一群废物！'),
(28500,0,4,'zhCN','这些死亡骑士真不知荣耀为何物。先是把我精心打造、承巫妖王祝福的最强兵甲取走，接着不知溜去何处，回来时却穿得像个地精，嘟囔着要把铠甲当掉换几个铜板！可悲！'),
(28500,0,5,'zhCN','这什么圣光的鬼话？我还有武器铠甲要打造！'),
(28548,0,0,'zhCN','心地纯洁者方可留在新阿瓦隆。被审判者认定缺失神圣圣光者，将被拒之门外。'),
(28548,1,0,'zhCN','肃静！圣光未曾舍弃我们！在纯洁者之中，圣光比以往更强大！'),
(28548,2,0,'zhCN','我们战斗！我们将他们击退，一如往昔！'),
(28548,3,0,'zhCN','我们正派出十字军，夺回本属我们的东西！任何挡路的天灾，都将被化为灰烬。'),
(28558,0,0,'zhCN','不过你们谁都不必担心，对吧？'),
(28605,0,0,'zhCN','哆……'),
