(28912,10,0,'zhCN','十字军们，你们的大审判官不过是一堆肉！没有任何人能逃出天灾之手！'),
(28912,11,0,'zhCN','%s 瘫倒在地。'),
(28921,1,0,'zhCN','%s 沿隧道向上移动！'),
(28922,2,0,'zhCN','%s 陷入狂暴！'),
(28936,1,0,'zhCN','你很快就要吊在绞架上了，天灾恶魔！'),
(28936,1,1,'zhCN','你除非杀了我，怪物。我什么都不会告诉你！'),
(28936,1,2,'zhCN','你打人像女孩子。说真的。你就这点能耐？'),
(28936,1,3,'zhCN','啊！你烧了我最后一件像样的战袍！'),
(28936,1,4,'zhCN','啊……这痛……痛得几乎和我小时候在文法学校挨鞭子时一样难忍。'),
(28936,1,5,'zhCN','我曾为大审判官伊希利恩效力！你所谓的痛苦，对我不过是寻常午后！'),
(28936,2,0,'zhCN','我全告诉你！住手！求求你！'),
(28936,3,0,'zhCN','我们……我们只被告知"猩红黎明"是一场觉醒。你……你看，圣光向大将领低语。那是圣光……'),
(28936,4,0,'zhCN','指引我们的圣光。这场运动在你到来之前便已启动……我们……我们只是奉命行事。这是必须之举。'),
(28936,5,0,'zhCN','其余我知之甚少……大将领决定谁可前往、谁须留下。再无别的……你务必信我！'),
(28936,6,0,'zhCN','谎言！你即将承受的痛苦，将成为数年谈资！'),
(28936,7,0,'zhCN','不！求你了！还有一件我忘了提的事……信使很快会来……从壁炉谷来。它……'),
(28936,8,0,'zhCN','我要从你灵魂里撕出秘密！说出"猩红黎明"，或可饶你不死！'),
(28936,8,1,'zhCN','说出你所知的"猩红黎明"，否则殴打不停！'),
(28936,8,2,'zhCN','我对你们这种人客气够了，人类！"猩红黎明"到底是什么？'),
(28936,8,3,'zhCN','你的命就这么不值？只要说出我需要知道的"猩红黎明"，我便让你速速解脱。'),
(28936,8,4,'zhCN','我能这样耗很久，血色走狗！说出"猩红黎明"！'),
(28936,8,5,'zhCN','"猩红黎明"是什么？'),
(28936,8,6,'zhCN','"猩红黎明！"那到底是什么！说！'),
(28941,0,0,'zhCN','要什么尽管说，我都给！只求饶我一命！'),
