(28941,0,3,'zhCN','我还太年轻，不想死！'),
(28941,0,4,'zhCN','快逃命啊！'),
(28941,0,5,'zhCN','天灾！！！快跑！！！'),
(28941,0,6,'zhCN','谁来救救我！'),
(28941,0,7,'zhCN','饶我一命吧，$n！求你了！'),
(28941,0,8,'zhCN','天灾突破了防线！快逃！快逃！'),
(28941,0,9,'zhCN','他们……他们曾承诺我们平安……'),
(28941,0,10,'zhCN','难道没有一处能躲过这些怪物？'),
(28941,0,11,'zhCN','我们都要死了！！！'),
(28941,0,12,'zhCN','肮脏的懦夫！给我个痛快……'),
(28941,0,13,'zhCN','天灾渣滓……愿圣光将你从这世界净化！'),
(28941,1,0,'zhCN','那就来吧，$c！'),
(28941,1,1,'zhCN','死吧，天灾走狗！死！'),
(28941,1,2,'zhCN','死！'),
(28941,1,3,'zhCN','我没那么容易倒下！'),
(28941,1,4,'zhCN','天灾就这点本事？'),
(28941,1,5,'zhCN','你可以取走我的性命，却夺不走我的自由！'),
(28941,1,6,'zhCN','想抓我？没那么容易！'),
(28941,2,0,'zhCN','我可以向你保证，昆比，下届选举你别想拿到我的票！'),
(28941,2,1,'zhCN','我要上最后一艘船！别丢下我们！'),
(28941,2,2,'zhCN','你再不出来，我们就把这地方拆了！'),
(28941,2,3,'zhCN','我全家都被杀了！我们最需要军队时，他们在哪？'),
(28941,2,4,'zhCN','纳克萨玛斯没了？谁管它！阿彻鲁斯就在这儿，死亡骑士正在屠杀所有人！'),
(28941,2,5,'zhCN','别再撒谎了，昆比！我们要真相！'),
(28941,2,6,'zhCN','昆比！！！！！！'),
(28941,2,7,'zhCN','这就是血色‘天堂’的下场！'),
(28941,2,8,'zhCN','天灾正在街巷中横行！'),
(28941,2,9,'zhCN','这简直是当面打脸！我们要个说法！'),
(28941,2,10,'zhCN','他们曾许诺我们安全！保障！'),
(28941,2,11,'zhCN','我们完了！救救我们，昆比！'),
(28941,2,12,'zhCN','‘猩红黎明’到底是什么？我们有权知道真相，昆比！'),
(28941,2,13,'zhCN','那些船要去哪儿，昆比！告诉我们真相！'),
(28941,2,14,'zhCN','你真没用，昆比！'),
(28941,2,15,'zhCN','大家都在死！救救我们！'),
(28948,2,1,'zhCN','自从他从德拉卡塔隆到来，主人便常说起你将前来与他相聚的时日。'),
(28964,1,0,'zhCN','你很快就要吊在绞架上了，天灾恶魔！'),
(28964,1,1,'zhCN','你除非杀了我，怪物。我什么都不会告诉你！'),
(28964,1,2,'zhCN','你打人像女孩子。说真的。你就这点能耐？'),
(28964,1,3,'zhCN','啊！你烧了我最后一件像样的战袍！'),
(28964,1,4,'zhCN','啊……这痛……痛得几乎和我小时候在文法学校挨鞭子时一样难忍。'),
(28964,1,5,'zhCN','我曾为大审判官伊希利恩效力！你所谓的痛苦，对我不过是寻常午后！'),
(28964,2,0,'zhCN','我全告诉你！住手！求求你！'),
(28964,3,0,'zhCN','我们……我们只被告知"猩红黎明"是一场觉醒。你……你看，圣光向大将领低语。那是圣光……'),
(28964,4,0,'zhCN','指引我们的圣光。这场运动在你到来之前便已启动……我们……我们只是奉命行事。这是必须之举。'),
(28964,5,0,'zhCN','其余我知之甚少……大将领决定谁可前往、谁须留下。再无别的……你务必信我！'),
(28964,6,0,'zhCN','谎言！你即将承受的痛苦，将成为数年谈资！'),
(28964,7,0,'zhCN','不！求你了！还有一件我忘了提的事……信使很快会来……从壁炉谷来。它……'),
(28964,8,0,'zhCN','我要从你灵魂里撕出秘密！说出"猩红黎明"，或可饶你不死！'),
(28964,8,1,'zhCN','说出你所知的"猩红黎明"，否则殴打不停！'),
(28964,8,2,'zhCN','我对你们这种人客气够了，人类！"猩红黎明"到底是什么？'),
(28964,8,3,'zhCN','你的命就这么不值？只要说出我需要知道的"猩红黎明"，我便让你速速解脱。'),
(28964,8,4,'zhCN','我能这样耗很久，血色走狗！说出"猩红黎明"！'),
(28964,8,5,'zhCN','"猩红黎明"是什么？'),
(28964,8,6,'zhCN','"猩红黎明！"那到底是什么！说！'),
