(29110,0,14,'zhCN','血色领地之劫，将成千古之鉴！'),
(29110,0,15,'zhCN','已无处可逃……'),
(29110,0,16,'zhCN','让此地的毁灭，成为所有胆敢对抗天灾者之戒训！'),
(29112,0,0,'zhCN','奉承毫无用处。'),
