(29643,0,0,'zhCN','这看着不妙啊，小子。'),
(29643,1,0,'zhCN','是吗？那你干嘛不蹦蹦跳跳地过去把东西捡来，嗯？'),
(29643,2,0,'zhCN','真怪……刚才那一瞬，我差点以为你叫我矮子。'),
(29643,3,0,'zhCN','把我扔过去？！好啊，小子，你完了。'),
(29643,4,0,'zhCN','你自己留着吧。'),
(29643,5,0,'zhCN','小子，你最好祈祷他们活不成。'),
(29643,6,0,'zhCN','因为等他们把你扔进去，我只会看着笑。'),
(29643,7,0,'zhCN','总该有处入口。'),
(29643,8,0,'zhCN','那地精是怎么把工具落那儿的？'),
(29643,9,0,'zhCN','就是这样，小子！看着完全安全。上吧，我紧跟在你后头！'),
(29643,10,0,'zhCN','孬种。'),
(29644,0,0,'zhCN','我不知道，贝利……没那么糟。我们从这儿扔石头就能碰到工具。'),
(29644,1,0,'zhCN','嗯……我只是想……你个头小点，所以较不易触发那些地雷。'),
(29644,2,0,'zhCN','不不不！不是矮……只是……嗯……也许我能把你扔过去大半段？'),
(29644,3,0,'zhCN','啊！'),
(29644,4,0,'zhCN','好险！你吓着我了。'),
(29644,5,0,'zhCN','我有个主意，贝利……'),
(29644,6,0,'zhCN','不，不——这或许行得通！'),
(29644,7,0,'zhCN','那儿就有条路……只有尽头几颗地雷隔着我们和工具。'),
(29644,8,0,'zhCN','我们等下个冒险者过来，告诉他那是必经之路……等他们引爆地雷，我们直接走进去取工具！'),
(29644,9,0,'zhCN','贝利，真看不出来。'),
(29644,10,0,'zhCN','哦……说得对。那儿怎样？看着挺干净……差不多。'),
(29644,11,0,'zhCN','呃……没事。上次弄的还隐隐作痛。'),
(29650,0,0,'zhCN','又是那些该死的铁矮人！不知怎的，他们比我们先找到他。'),
(29650,1,0,'zhCN','不找到他他们不会罢休。我们不能让他们得逞，$n，布兰也清楚。'),
(29650,2,0,'zhCN','这纸条上的指示相当隐晦。布兰一定备了某种后手，但他不可能永远躲过追捕……'),
(29650,3,0,'zhCN','在他被铁矮人找到之前，找到他的重任就交给你了！'),
