(31016,1,0,'zhCN','你敢挑战我？你还没资格！'),
(31016,2,0,'zhCN','瓦德玛德拉？！巫妖王亲自派你来的？'),
(31016,3,0,'zhCN','好吧。我会打发这些家伙。不过是桩麻烦事。受死吧！'),
(31016,4,0,'zhCN','萨菲德朗，让他们感受冰冠的寒意！'),
(31016,5,0,'zhCN','住手！跪下，蠢货们，那是巫妖王！'),
(31016,6,0,'zhCN','可是，吾王……？'),
(31016,7,0,'zhCN','死吧，走狗！'),
(31017,0,0,'zhCN','够了，迈克尔。这恐慌已经够伤生意了。我们每个铜板都用得着。'),
(31017,1,0,'zhCN','%s 不情愿地点了点头。'),
(31017,2,0,'zhCN','这话我没法反驳。'),
(31019,0,0,'zhCN','不是我的食物有问题！'),
(31019,1,0,'zhCN','求你了，不是我的错！如果……如果我给你退款，也许你能去找治疗者？我不知道你指望我怎么办！'),
(31021,0,0,'zhCN','出什么事了？我听见愤怒的声音。'),
(31021,0,1,'zhCN','外面在闹什么？'),
(31021,0,3,'zhCN','最近一切都好怪……'),
(31023,0,0,'zhCN','求你了，我只是个送货的！'),
(31027,0,0,'zhCN','希望你进来不是来找架打的。今天街上有太多愤怒的人。'),
(31027,0,1,'zhCN','外面这么乱，今天我不知还能开多久。你要修什么，我快速看看。'),
(31027,0,2,'zhCN','听着，今天我卖你盾牌，但不卖锤。我最不希望有无辜者被我的武器敲破脑袋。'),
(31028,0,0,'zhCN','治安官很忙。'),
(31028,0,1,'zhCN','请回各自的家吧。'),
(31028,0,2,'zhCN','各位，请保持冷静……'),
(31028,0,3,'zhCN','巴塞拉斯治安官此刻无暇接待……'),
(31028,1,0,'zhCN','请别再往里走了！'),
(31028,1,1,'zhCN','请勿打扰治安官！'),
(31029,0,0,'zhCN','他来了！'),
(31029,1,0,'zhCN','错了，巴兰加德。你必须接受这挑战！'),
(31029,2,0,'zhCN','吾王。'),
(31029,3,0,'zhCN','可是……！'),
(31083,0,0,'zhCN','近卫留原地待命。'),
(31083,1,0,'zhCN','瓦德玛德拉。我正奇怪你去了何处。伊斯卡尔德可好？'),
(31083,2,0,'zhCN','我识破了你的伪装，夜林女士。你以为能骗过我？！'),
(31083,3,0,'zhCN','你可以继续战斗，督军。'),
(31083,4,0,'zhCN','少废话！解决他们！别让我失望，巴兰加德！'),
(31083,5,0,'zhCN','你击败了我的一员良将，但你的努力终归徒劳。'),
(31083,6,0,'zhCN','冰冠的冰封之心正在等待……'),
(31099,0,0,'zhCN','%s 陷入狂暴！'),
(31126,2,0,'zhCN','巴塞拉斯在哪？！'),
