(31127,0,4,'zhCN','让我们过去！'),
(31135,1,0,'zhCN','$n 与$g his : her; 战友们已选择于瓦尔哈拉斯的神圣疆界内接受荣耀之战。'),
(31135,2,0,'zhCN','此战结局只有一个：一方死，一方活。让$n 在先前倒下的外乡人骸骨之上，证明$g himself : herself; 之价值！'),
(31135,3,0,'zhCN','瓦尔哈拉斯的陨落英雄自大地中升起，再战一场！'),
(31135,4,0,'zhCN','$n 已击败昔日瓦尔哈拉斯之战的陨落英雄。这只是开端，但已足够。'),
(31135,5,0,'zhCN','做好准备。基特里克斯将从东南面进入瓦尔哈拉斯。记住，勿离圆环，否则判你败。'),
(31135,6,0,'zhCN','$n 已接受暗影之主基特里克斯的挑战。愿众神怜悯$g him : her;，因基特里克斯绝不会。'),
(31135,7,0,'zhCN','暗影之主基特里克斯从东南面窜入瓦尔哈拉斯！'),
(31135,8,0,'zhCN','暗影之主基特里克斯已被$n 与$g his : her; 的同伴们击败。发出下一道挑战吧！'),
(31135,9,0,'zhCN','寒冰之裔希格莉德重返约顿海姆高地，要与$n 一决高下。上次相逢，$n 在单挑中胜她。且看此战胜负。'),
(31135,10,0,'zhCN','希格莉德绕着瓦尔哈拉斯逼近，前来复仇！'),
(31135,11,0,'zhCN','$n 再度击败希格莉德。嗯，这次$g he : she; 是借助$g his : her; 朋友之力，但胜就是胜！'),
(31135,12,0,'zhCN','大屠杀来了！记住，无论发生什么，绝勿离开战斗圆环，否则我取消你与队伍的资格。'),
(31135,13,0,'zhCN','大屠杀自幽深地厅而来。$n 勇敢又愚勇地接受了挑战。$G He : She; 与$g his : her; 队伍已准备直面那怪物。'),
(31135,14,0,'zhCN','自南方蹒跚而来，大屠杀的腥气先于其身！'),
(31135,15,0,'zhCN','名为大屠杀的恐怖已不复存在。$n 真配在瓦尔哈拉斯一战？且看分晓。'),
(31135,16,0,'zhCN','望向东南，你便能见那督军现身于无情者约纳尔旁的平台上。让他下来。留在瓦尔哈拉斯圆环之内。'),
(31135,17,0,'zhCN','督军巴纳霍格久别重归瓦尔哈拉斯，欲证维库人是唯一配在其圣环中战斗的存在。$n 能否证其谬误？'),
(31135,18,0,'zhCN','督军巴纳霍格现身于东南面的高台！'),
(31135,19,0,'zhCN','终结者巴纳霍格督军已败于$n 与$g his : her; 奋战的同伴之手。$G He : She; $g him : her; 前方仅余一挑战。会是谁？'),
(31135,20,0,'zhCN','现在逃跑已晚。勿离圆环。英勇赴死吧，$n！'),
(31135,21,0,'zhCN','自冰冠堡垒深处，巫妖王的一名遴选者前来终结$n 与$g his : her; 朋友的性命。'),
(31135,22,0,'zhCN','约顿海姆的战士们，我向你们引荐——血王子桑多瓦尔！'),
(31135,23,0,'zhCN','毫无征兆，桑多瓦尔王子魔法般现身于瓦尔哈拉斯之中！'),
(31135,24,0,'zhCN','不可思议之事已然发生……$n 已斩杀桑多瓦尔王子！'),
(31135,25,0,'zhCN','击败他之后，$g he : she; 与$g his : her; 奋战的同伴们，已证明自己配在这维库人荣誉的至圣之地一战。'),
(31135,26,0,'zhCN','万岁，$n，瓦尔哈拉斯的勇士！'),
(31135,27,0,'zhCN','你还没准备好！'),
(31242,1,0,'zhCN','我说过下次相见我会准备更充分。我已征战并赢下希尔兹米特，在瓦尔基里昂受训，如今我来了。来领教吧！'),
