(31320,0,6,'zhCN','那是你犯的最后错误，骷髅。'),
(31397,2,0,'zhCN','%s 陷入狂暴！'),
(31412,0,0,'zhCN','科卡尔，退下！'),
(31412,1,0,'zhCN','吉安娜……'),
(31412,2,0,'zhCN','吉安娜，愤怒之门发生了什么。那是来自内部的背叛……'),
(31412,3,0,'zhCN','部落已失去幽暗城。'),
(31412,4,0,'zhCN','我们正准备围攻那座城，将这不可饶恕罪行的元凶绳之以法。'),
