(31412,7,0,'zhCN','科卡尔，准备前往幽暗城的交通工具。'),
(31418,0,0,'zhCN','萨尔，发生了什么？国王正在备战……'),
(31418,1,0,'zhCN','我会把这情报送达瓦里安国王，萨尔，但是……'),
(31418,2,0,'zhCN','博瓦尔于他如兄弟。国王不在时，博瓦尔维系着联盟的统一。在我们最黑暗的时刻，他为我们人民寻得力量。他照看安杜因，视如己出。'),
(31418,3,0,'zhCN','我怕怒火会吞噬他，萨尔。我仍期盼理智能占上风，但我们必须做最坏的准备……为战争。'),
(31418,4,0,'zhCN','再会，大酋长。我祈祷下次相见，我们已是盟友。'),
