(31425,0,0,'zhCN','大酋长在哪？'),
(31425,1,0,'zhCN','这些被遗忘者在这儿干什么？'),
(31427,0,0,'zhCN','发生什么事了？'),
(31427,1,0,'zhCN','这太不像话了！'),
(31428,1,0,'zhCN','看！冰霜巨龙来这儿干什么？它正朝我们直冲过来。'),
(31429,0,0,'zhCN','我们要个说法！'),
(31430,0,0,'zhCN','发生什么事了？'),
(31431,0,0,'zhCN','肃静！'),
