(34054,0,0,'zhCN','你们做到了！你们攻破了奥杜尔的防御。再过片刻，我们就要空降进……'),
(34054,1,0,'zhCN','那是什么？小心！有东西朝你去了！'),
(34054,2,0,'zhCN','快！规避！规避动——'),
(34054,3,0,'zhCN','有四台发电机为防御设施供能。若你破坏发电机，导弹攻击就会停止！'),
(34054,4,0,'zhCN','看来你在维修站附近！把载具开上平台，它应该会自动修复。'),
(34054,5,0,'zhCN','啊，克罗尔米尔之塔。据说托里姆之力仅被动用过一次……便令整片大陆化为尘土。'),
(34054,6,0,'zhCN','此塔为霍迪尔之锤供能。据说它有能力将整支军队化为寒冰！'),
(34054,7,0,'zhCN','你正接近芙蕾雅之塔。它蕴含令荒芜之地一夜之间化为生机丛林之力。'),
(34054,8,0,'zhCN','这台发电机为米米尔隆之眼供能。片刻间，它便能将大地化为灰烬、岩石化为岩浆——绝不能让它充满能量！'),
(34102,0,0,'zhCN','感谢各位前来听这场布道。见到这么多熟悉的面孔，真好！'),
(34102,1,0,'zhCN','今天我想谈谈圣光的三美德。'),
(34102,2,0,'zhCN','这是我们所有人黑暗而艰难的时日。天灾大军在南方集结。同伴倒于战场，片刻后便起身侍奉我们的敌人。'),
(34102,3,0,'zhCN','你们许多人经历过信任的背叛。'),
(34102,4,0,'zhCN','然而你们坚持着，一如我们都必须做的。在这等时日，无人不识坚韧之德。面对绝望与仇恨，我们继续坚守信念，奋战不懈。'),
(34102,5,0,'zhCN','你们的坚韧毋庸置疑……但还有其他美德值得思量。'),
(34102,6,0,'zhCN','尊敬，是授予以身许道圣光者之首德。'),
(34102,7,0,'zhCN','望向过道对面的那些你称之为敌者。纵有仇恨相隔，你的对手仍有值得尊敬之处。他们的勇武当被承认。'),
(34102,8,0,'zhCN','聚集于此的众人皆懂荣耀之战为何物。以荣耀立身，待对手如你愿受之待，便是尊敬。'),
(34102,9,0,'zhCN','在战场上尊敬你的对手，无论他是你的兄弟还是死敌。无论你信念何在，此等尊敬便是对一种联结的承认……'),
(34102,10,0,'zhCN','……而承认那些联结，你便更接近圣光。'),
(34102,11,0,'zhCN','圣光之道尚有更进一步：怜悯。'),
(34102,12,0,'zhCN','当今天下，敌对丛生。无论转向何方，差异皆易见。'),
(34102,13,0,'zhCN','挑战在于看透表象，理解我们的相通之处。藉此理解，你便能对其他人的失去感同身受……'),
(34102,14,0,'zhCN','……即便受害者高举的是另一面旗帜。'),
(34102,15,0,'zhCN','在敌友身上皆感知并理解怜悯，你便重申了与这世界的联结。'),
(34102,16,0,'zhCN','践行这些信条、这些美德，助我们共创一个众所珍视的世界。一个荣耀与正义的世界。'),
(34102,17,0,'zhCN','思量我的话吧，朋友们。在笼罩我们众人的黑暗中，圣光比以往更被需要。'),
(34102,18,0,'zhCN','若有人想与我交谈，我就在忏悔屏风之后。任何疑虑、忧烦、不安，我都乐意为你抚平。'),
(34102,19,0,'zhCN','打起精神。重要的不是体型，而是你如何运用已有的技艺。'),
(34102,20,0,'zhCN','小家伙，你在体型上的不足，已由抱负与奉献补足。愿圣光与你同行。'),
(34102,21,0,'zhCN','那么，我的矮人朋友，饮酒须有度，不过眼下你或许该交还长枪与缰绳。愿圣光与你同行。'),
(34102,22,0,'zhCN','我理解你的沮丧。你的族人在战场上凶猛无比，而这并非你们习惯之事。'),
(34102,23,0,'zhCN','不过，这是一种不同的荣耀之战。或许难以适应，但我确信凭你的勇武，定能让所有人见识你族的力量。'),
(34102,24,0,'zhCN','此外……斧头虽是战争利器，长枪亦有其用。'),
(34102,25,0,'zhCN','这或许看似徒劳，但请在一场好战斗中寻得自豪。终有一日，这一切练习与竞争都将派上用场。'),
(34102,26,0,'zhCN','而且你的头发看着真美。'),
(34102,27,0,'zhCN','你的心摆对了地方，我也知你立志侍奉圣光。但这些小打小闹对庞大的亡灵大军作用甚微。'),
(34102,28,0,'zhCN','这比武大会正助力铸就一支强韧、同心之力，尽管这并不显眼。待我们准备就绪，十字军的目光与所有勇士将转向冰冠。'),
(34102,29,0,'zhCN','我们将倾尽万族之力直指巫妖王，他必败无疑。'),
(34102,30,0,'zhCN','我知这看似并非你心目中的明路，但它会带你更接近圣光。善战吧，兄弟。'),
(34102,31,0,'zhCN','哦天哪。你至少感到悔恨了吗？'),
(34320,0,0,'zhCN','%s 有力的颚撕咬着食物。'),
(34320,0,1,'zhCN','%s 飞快地吃完食物，四下张望还想再吃。'),
(34320,0,2,'zhCN','%s 吞噬了食物。'),
(34320,0,3,'zhCN','%s 一口叼住食物，囫囵吞下。'),
(34496,6,1,'zhCN','不配！'),
(34497,6,1,'zhCN','不配！'),
(34526,0,0,'zhCN','跟我说话呀，塔胡。随便什么。什么都行！我快闷疯了。'),
(34526,1,0,'zhCN','没什么。'),
(34526,2,0,'zhCN','就像玛沙。'),
(34526,3,0,'zhCN','你这番话想说什么？'),
(34526,4,0,'zhCN','我听出你话里的‘但是’了……'),
(34526,5,0,'zhCN','你觉得他的教诲是错的？'),
(34526,6,0,'zhCN','那你打算向长老提出这事？'),
(34526,7,0,'zhCN','我想是吧。不过你说的并不傻。'),
(34526,8,0,'zhCN','我看见你那若有所思的皱眉了，塔胡。'),
(34526,9,0,'zhCN','不过你有心事，对吧？'),
(34526,10,0,'zhCN','那又怎样？'),
(34526,11,0,'zhCN','有句话……‘黎明前最黑暗’。但黎明终会到来，塔胡。太阳会升起。平衡终将回归它应在之处。'),
(34526,12,0,'zhCN','%s 微笑着指向北方。'),
(34526,13,0,'zhCN','即便在冰川之上，阳光也能穿透阴霾。我有希望，塔胡。我想我们能挺过这一关，无论看来多绝望。'),
(34526,14,0,'zhCN','但我仍宁愿在前线助它成真，而非用信念自我安慰。我们不能干坐着指望它发生。'),
(34526,15,0,'zhCN','而藉由那份希望，在战斗中增强我方？'),
(34528,0,0,'zhCN','%s 轻声笑了。'),
(34528,1,0,'zhCN','好吧，阿波妮。我心中确有足够多可分享的。你可曾与月光林地的精灵交谈过？'),
(34528,2,0,'zhCN','精灵们谈论一位月之女神，你知道吗？他们极看重月光所赐之光。'),
(34528,3,0,'zhCN','正与她相仿。我所闻的相似之处颇有意思。而且众所周知，所有德鲁伊——无论是牛头人还是精灵——皆能召唤玛沙之光。'),
(34528,4,0,'zhCN','我寻思着。哈缪尔指引有方，我从他身上学到良多。传说我们的族人在时间之初便是德鲁伊……'),
(34528,5,0,'zhCN','……但哈缪尔所授，正是精灵所知。那暗夜精灵。作为夜之生灵，他们如此信奉他们的月之女神。'),
(34528,6,0,'zhCN','不！不，绝不是那样。他身为长老自有其因，姐妹。玛沙是大地母亲之眼之一，她看护着我们。那并非邪恶。'),
(34528,7,0,'zhCN','但我们若非追求平衡之族，便什么也不是。我们的战士只在必要时出战。我们的猎人只取部落生存所需，且在取用时物尽其用。萨满则是元素之灵的向导与调停者。'),
(34528,8,0,'zhCN','而身为德鲁伊的我们虽是自然守护者，我却疑心是否忽略了万物平衡中关键的一环。'),
(34528,9,0,'zhCN','不，不。他正陪朋友，不必为学生的闲来哲思烦心。'),
(34528,10,0,'zhCN','嗯，这念头倒也不算新，姐妹。'),
(34528,11,0,'zhCN','抱歉，姐妹。没什么好担心的。'),
(34528,12,0,'zhCN','我在想北面的前线。你急于回去的那处。'),
(34528,13,0,'zhCN','阿波妮，我知道我在劝人耐心，但我并不比你更愿留在此地。时局黯淡，而不作为只会让我忧心，怕我这闲着的手，恰恰是那翻转局势的手。'),
(34528,14,0,'zhCN','即便如此……万物皆有平衡，连死亡也是。我只是厌恶那种毁灭与黑暗或许必不可免的想法。'),
(34528,15,0,'zhCN','我知道，姐妹。我知道。终有一日我们会重返战斗。不过眼下，或许最好把话传开……把你的希望给予他人。'),
(34528,16,0,'zhCN','正是此意。'),
(34565,0,0,'zhCN','嗯……没什么比得上可口家常的人类食物。'),
(34565,1,0,'zhCN','我撒谎了。你们这难吃的食物臭不可闻，不过比不上这镇子即将散发的臭味！'),
(35476,0,2,'zhCN','用不了多久，菲兹班就会成为家喻户晓的词，用来吓孩子上床！‘当心，不然菲兹班会召来凶恶魔怪把你吃掉！’'),
(35476,0,3,'zhCN','我，威尔弗雷德·菲兹班，受邀来到这场别致的比武大会，以施展我在召唤术上的渊博学识。还有比这更合适的选择吗？'),
(35589,0,0,'zhCN','银色十字军诚邀你前往银色锦标赛，以荣耀之战与其他艾泽拉斯英雄较量技艺。'),
(35589,1,0,'zhCN','世界各国之勇士已集结于冰冠东北部的银色锦标赛场地，迎战一切挑战者。'),
(35604,0,0,'zhCN','银色十字军诚邀你前往银色锦标赛，以荣耀之战与其他艾泽拉斯英雄较量技艺。'),
(35604,1,0,'zhCN','世界各国之勇士已集结于冰冠东北部的银色锦标赛场地，迎战一切挑战者。'),
(36095,0,0,'zhCN','勇士们，你们还活着！你们不仅击败了十字军试炼的每一重挑战，更挫败了阿尔萨斯的图谋！你们的技艺与智谋，将成为对抗天灾的利器。干得好！让十字军的一位法师将你们传送至地面吧！'),
(36095,1,0,'zhCN','让我把宝箱作为奖赏交予你们，愿其中之物在对抗阿尔萨斯的冰冠堡垒核心之战中忠实效劳！'),
(36272,0,0,'zhCN','妙极了。我们不是没胆，是没本事。'),
(36296,0,0,'zhCN','他们可曾费心告诉你我是谁、又为何做此事？'),
(36296,1,0,'zhCN','……还是说他们只是像利用其他人那样利用你？'),
(36296,2,0,'zhCN','但那又如何。是时候了结这一切了。'),
(36296,3,0,'zhCN','巴克斯特！进来帮忙！立刻！'),
(36296,4,0,'zhCN','是时候了，弗莱！进攻！'),
(36296,5,0,'zhCN','……请别因此小看我。'),
(36296,6,0,'zhCN','药剂师们！为幽暗城献出生命！'),
(36479,0,0,'zhCN','哨兵，我要面见你们的大祭司。'),
(36479,1,0,'zhCN','必须吗？我怀疑泰兰德有更紧要的事务。'),
(36479,2,0,'zhCN','权柄之诱巨大。错误已然铸成。'),
(36479,3,0,'zhCN','未得倾听，我绝不离开。此事关系重大。'),
(36479,4,0,'zhCN','风中有变，我们无法忽视。我自往昔的尘灰与废墟中跋涉而来，只为达成和解。'),
(36479,5,0,'zhCN','或许不久，暗夜精灵便需要我们所献的学识与技艺。'),
(36479,6,0,'zhCN','我会等候，哨兵……但我终将获得觐见。'),
(36479,7,0,'zhCN','%s 叹了口气，望向月井。'),
(36479,8,0,'zhCN','冷静，哨兵。我无意动用它。我只是在……追忆。'),
(36479,9,0,'zhCN','够了。我已与此隔绝数世纪。这神殿中的井，或许只是永恒之井苍白的幽影，却仍保有同样的……美。纯粹。'),
(36479,10,0,'zhCN','我竟忘了。'),
(36479,11,0,'zhCN','我不认为欣赏与怅惘之思，有悖于社会常伦。'),
(36479,12,0,'zhCN','是你因我不过望了一眼便向我挑战。我仍在等候觐见泰兰德。'),
(36481,0,0,'zhCN','你必须等候觐见。'),
(36481,1,0,'zhCN','上层精灵，你竟敢踏上泰达希尔，胆子不小。你等不受欢迎。我们未曾忘记上古之战，及其背后的那些心计。'),
(36481,2,0,'zhCN','我们也不愿那些错误重演。回到你的放逐之地去。'),
(36481,3,0,'zhCN','放逐者，把目光从月井上移开。其中的力量非你所能驾驭。'),
(36481,4,0,'zhCN','在回想你的背叛？'),
(36481,5,0,'zhCN','放尊重点，上层精灵。'),
(36481,6,0,'zhCN','时候到了自会。'),
(36565,0,0,'zhCN','能与你并肩，是我此生莫大的荣耀，胡默尔。'),
(36856,1,4,'zhCN','这才叫干活！'),
(36856,1,5,'zhCN','干净又整洁！'),
(36856,1,6,'zhCN','不错。我可不想知道那污渍是什么。'),
(36856,1,7,'zhCN','阿夸诺斯都快跟不上了！'),
(36856,9,0,'zhCN','哦不！那不对。现在我得去拿更多洗涤剂，咱们重来！'),
(36899,0,0,'zhCN','%s 变得更加不稳定！'),
(36899,1,0,'zhCN','%s 愈发躁动不安！'),
(36899,2,0,'zhCN','%s 几乎维持不住形体！'),
(36899,3,0,'zhCN','|TInterface\\\\\\\\Icons\\\\\\\\spell_shadow_unstableaffliction_2.blp:16|t%s 开始施放 |cFFFF0000Unstable Ooze Explosion!|r'),
(36913,0,7,'zhCN','他注视着你的一举一动……'),
(37172,0,0,'zhCN','你知道吗，那闻着还挺……嘿！别拿那玩意儿喷我！'),
(37172,1,0,'zhCN','别引诱我！你可知那些东西里装的是什么？'),
(37181,5,0,'zhCN','拿去吧，凡人！这些灵魂很快便又归我所有……'),
(37181,5,1,'zhCN','很快，凡人，你也将拥有一柄作囚笼的利刃。'),
(37181,5,2,'zhCN','记住，英雄：我也曾追求一柄伟力之武器……'),
(37181,5,3,'zhCN','我见你也在为己谋而聚敛灵魂。我们当真如此不同吗，勇士？'),
(37181,5,4,'zhCN','对，动手！铸你的骇人新武器。待你的灵魂归我，它也将为我效劳！'),
(37181,5,5,'zhCN','把你的武器拿来，勇士，或可用其主人之魂喂养它……'),
(37181,5,6,'zhCN','看看你，孩子；自诩的灵魂持有者……你无法想象我掌中之力。'),
(37181,5,7,'zhCN','到我身边来，僭越者！喂养我的利刃！'),
(37181,5,8,'zhCN','我的试炼已使你强大，勇士，你将好好为我效劳！'),
(37181,5,9,'zhCN','凡人，我从未有过后悔留你一命的理由。你总能找到法子逗我发笑。'),
(37181,5,10,'zhCN','时刻将临，凡人。你将在崭新的艾泽拉斯永世劳役！'),
(37181,5,11,'zhCN','更多灵魂，对，更多！你会发现难以停下。'),
(37181,5,12,'zhCN','你的武器所感之饥，不过是等候者之影。你想见识真正的饥饿？真正的力量？继续前行吧，英雄！我等着。'),
(37181,5,13,'zhCN','你在黑暗中跌撞。此处无光。无怜悯。冰冠已收去比你更杰出英雄之魂。'),
(37181,5,14,'zhCN','你的心……那不息的擂动令我厌恶。我会让它静默，一如我对自己所做。'),
(37181,5,15,'zhCN','圣光会抛弃你，英雄，正如它曾抛弃我。'),
(37187,15,0,'zhCN','那圣骑士还活着？可能吗，大领主？他竟能幸存？'),
(37187,16,0,'zhCN','那我们必须救他！若救出伯瓦尔·弗塔根，或能平息联盟与部落间的动荡。'),
(37187,17,0,'zhCN','任务现已明确：巫妖王必须为他的罪行付出代价，而我们定要救出伯瓦尔·弗塔根大领主！'),
(37187,18,0,'zhCN','科卡尔，让‘奥格瑞姆之锤’准备最后一航！勇士们，我们的炮舰将在堡垒上层找到停靠点。在那里与我们会合！'),
(37200,13,0,'zhCN','可能吗，弗丁领主？若伯瓦尔尚存，或许联盟与部落间尚有和平之望。我们必须登上这被诅咒之地顶层，解救那圣骑士！'),
(37200,14,0,'zhCN','让‘破天者’准备对堡垒的空袭！'),
(37200,15,0,'zhCN','英雄们，你们得杀出一条路，抵达冰冠内一处清晰的撤离点。我们尽量在城垛上会合！'),
(37538,0,0,'zhCN','生者当死！'),
(37539,0,0,'zhCN','加入我们……嘿嘿哈！'),
(37541,0,0,'zhCN','天灾必胜！'),
(37592,0,0,'zhCN','英雄们！我们会尽量拖住亡灵，哪怕拼上性命。去对付天灾领主！'),
(37592,1,0,'zhCN','勇敢的勇士们，我们的性命与自由皆欠你们……尽管面对这浩大恩情，这不过微小之举，我立誓：自今日起，所有人都将知晓你们的功绩，以及你们在这黑暗堡垒的阴影中劈出的炽光之路。'),
(37592,2,0,'zhCN','此日将不仅为你的英勇作见证，更见证这一事实：当联盟与部落放下分歧，再无对手——纵是巫妖王本人——能与之抗衡——'),
(37671,0,0,'zhCN','那箱子可不会自己送货，朋友。快点！'),
(37671,0,1,'zhCN','时间就是金钱，朋友。快快快！'),
(37671,0,2,'zhCN','可爱的商人正等着它呢。快点！'),
(37704,0,0,'zhCN','奎尔德拉在霜之哀伤面前跃然而生！'),
(37893,1,0,'zhCN','敌人将饱尝苦痛，主人！'),
(38065,0,0,'zhCN','那箱子可不会自己送货，朋友。快点！'),
